window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-infectologia-inf-3"]={"block":"medcurso:medcurso-infectologia-inf-3","label":"Medcurso · INF 3","count":436,"questions":[{"id":"medcurso-infectologia-inf-3-345455","number":"345455","sourceNumber":"345455","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"VFI, 68 anos, sexo masculino, procedente de Cajazeiras chega ao pronto-socorro com\nhistória de febre de início súbito há três dias, associado a cefaléia, artralgia e mialgia intensa.\nHoje\npela manhã, ao se levantar, apresentou tontura. Ao exame físico: REG, desidratado +/4+, T: 39ºC,\nFr16ipm, FC 100 bpm, PA 130x80 mmhg em duas posições. Abdome indolor, sem VCM e sem\noutras alterações no exame. Qual a hipótese diagnóstica e a conduta inicial?","options":{"A":"Dengue. Iniciar analgesia e hidratação oral.","B":"Dengue. Orientar internamento devido à tontura.","C":"Dengue. Solicitar Hemograma completo e reavaliar.","D":"Dengue. Iniciar analgesia, hidratação oral e solicitar sorologia com 7 dias."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345462","number":"345462","sourceNumber":"345462","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O envolvimento renal na leptospirose pode evoluir para insuficiência renal aguda que se\napresenta, em geral:","options":{"A":"Com oligúria e com hipocalemia.","B":"Sem oligúria e com hipocalemia.","C":"Com oligúria e com hipercalemia.","D":"Sem oligúria e com hipercalemia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345472","number":"345472","sourceNumber":"345472","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No Brasil, a febre maculosa brasileira causada por Rickettsia rickettsii é a riquetsiose\nmais prevalente e reconhecida. No entanto,\nrecentemente novas riquetsioses também causadoras\nde quadros clínicos da \"febre maculosa\" têm sido confirmadas em diversas regiões do país.\n(Ministério da Saúde, 2017). Sobre a Febre Maculosa, é INCORRETO afirmar que:","options":{"A":"O início costuma ser abrupto e os sintomas são inespecíficos de início (febre, em geral, alta,\ncefaleia, mialgia intensa, mal-estar generalizado, náuseas e vômitos).","B":"Se não tratado, o paciente pode evoluir para um estágio de torpor e confusão mental, com\nfrequentes alterações psicomotoras, chegando ao coma profundo, Icterícia e convulsões podem\nocorrer em fase mais avançada da doença.","C":"É recomendada a antibioticoterapia profilática para indivíduos assintomáticos que tenham sido\nrecentemente picados por carrapatos, como forma de prevenção da doença.","D":"A partir da suspeita de febre maculosa, a terapêutica com antibióticos deve ser iniciada\nimediatamente, não se devendo esperar a confirmação laboratorial do caso."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-343841","number":"343841","sourceNumber":"343841","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem, 45 anos, com diagnóstico laboratorial confirmado de malária vivax não grave.\nFez tratamento completo usando as drogas que\ncompõem o esquema de primeira linha para tal\nsituação. No entanto, 54 dias após o término do tratamento, mesmo sem ter voltado para a área de\ntransmissão, os sintomas reapareceram e novamente foi feito o diagnóstico laboratorial de malária\nvivax. Não há sinais ou sintomas ou indícios laboratoriais de malária grave. Nesta situação as\ndrogas e a duração do tratamento atual deverá ser:","options":{"A":"Cloroquina 3 dias + Primaquina 7 dias.","B":"Cloroquina 6 dias + Primaquina 14 dias.","C":"Artemether + Lumefatrine 3 dias + Primaquina em dose única.","D":"Artemether + Lumefantrine por 3 dias + Primaquina por 14 dias."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-343849","number":"343849","sourceNumber":"343849","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual das condições abaixo relacionadas se detectada isoladamente em um paciente\ncom suspeita de dengue, NÃO tem indicação de\ninternação hospitalar?","options":{"A":"Prova do laço positiva.","B":"Plaquetometria de 15.000/mm 3.","C":"Hepatomegalia dolorosa.","D":"Aumento rápido do hematócrito."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-217734","number":"217734","sourceNumber":"217734","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 33 anos, não grávida, com síndrome icterofebril aguda foi diagnosticada\nlaboratorialmente com malária pós Plasmodium\nvivax. Ao exame físico: febril; ictérica +++/4+; PA =\n90 x 50 mmHg. Os exames laboratoriais evidenciaram: ureia = 43 mg/dl; creatinina = 2,1 mg/dl.\n\nNessa situação, segundo orientações do Ministério da Saúde, a conduta CORRETA é:","options":{"A":"Acompanhar ambulatorialmente e tratar com cloroquina e primaquina.","B":"Acompanhar ambulatorialmente e administrar artesunato e clindamicina.","C":"Internar e tratar com cloroquina e primaquina.","D":"Internar e administrar artesunato e clindamicina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-217741","number":"217741","sourceNumber":"217741","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A suspeita de dengue recai em pessoas com quadro febril agudo, as quais, na maioria\ndas vezes, não manifestam sinais de\ngravidade. Há, porém, indivíduos que evoluem para formas\nque exigem maior cuidado e monitoração mais rigorosa, portanto identificar tais sinais de alarme é\nfundamental para o manejo adequado do paciente. Dentre esses SINAIS DE ALARME pode-se\ncitar:","options":{"A":"Hepatomegalia ? 2cm abaixo do RCD.","B":"Leucopenia < 1.000 leucócitos/mm³.","C":"Plaquetopenia < 100.000 plaquetas/mm³.","D":"Redução progressiva do hematócrito."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-182639","number":"182639","sourceNumber":"182639","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A malária é uma doença de grande importância na Amazônia, podendo causar quadros\ngraves e fatais. Todos os médicos que\natuam nessa área necessitam conhecer o adequado manejo\nda doença. Com relação à malária, considere as afirmativas abaixo: I. Gestantes com malária vivax\ngrave deverão ser tratadas com cloroquina isolada. II. As recaídas de malária vivax se devem à\nreativação dos esporozoítos. III. Menores de 6 meses com malária vivax não deverão tomar\nprimaquina. IV. Malária grave pode ser tratada com Artesunato e Clindamicina endovenosos. V.\nCaso surja icterícia durante o tratamento de malária vivax deve-se suspender a cloroquina.\n\nAnalisando as afirmativas acima, estão CORRETAS:","options":{"A":"I, II, III.","B":"I, III, IV.","C":"II, III, IV","D":"II, IV, V."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183212","number":"183212","sourceNumber":"183212","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As causas mais comuns de óbito em pacientes com leishmaniose visceral grave são:","options":{"A":"Insuficiência renal / pancreatite.","B":"Infecções fúngicas / infecção por anaeróbicos.","C":"Comprometimento do Sistema Nervoso Central / Insuficiência Hepática.","D":"Infecções bacterianas / sangramentos.","E":"Desnutrição / edema agudo de pulmão."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-159066","number":"159066","sourceNumber":"159066","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em um paciente com suspeita de dengue no atendimento na Unidade Básica de Saúde,\nquais dentre os itens abaixo relacionados são sinais de agravamento para dengue hemorrágica? I.\nDor abdominal intensa.; II. Hipotensão postural.; III. Redução repentina do hematócrito.; IV.\nOligúria.","options":{"A":"Apenas I e II.","B":"Apenas III e IV.","C":"Apenas I, II e III.","D":"Apenas I, II e IV."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-159124","number":"159124","sourceNumber":"159124","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os casos graves e/ou complicados de malária habitualmente têm como agente\netiológico o Plasmodium falciparum, porém\nhá relatos em portadores de P.vivax. O tratamento dos\ncasos graves e/ou complicados se fez com drogas distintas das usadas nos casos leves ou\nmoderados, fato que torna importante o reconhecimento dos critérios de gravidade ou complicações\nnos portadores de malária. Dentre tais critérios de gravidade, pode-se citar:","options":{"A":"Insuficiência renal.","B":"Leucocitose.","C":"Hipertensão arterial.","D":"Cefaléia intensa."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-159127","number":"159127","sourceNumber":"159127","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Amazônia concentra a grande maioria dos casos de malária do país. Diante de um\npaciente adulto, masculino, com malária por P. vivax diagnosticada laboratorialmente, que evolui\ncom sinais de gravidade, você indica como primeira escolha o tratamento com:","options":{"A":"Cloroquina associada à primaquina endovenosas.","B":"Artemether combinado com lumefantrine oral.","C":"Artesunato associado à clindamicina endovenosos.","D":"Quinino associado à clindamicina endovenosos."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-159130","number":"159130","sourceNumber":"159130","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Zika vírus é uma doença infecto-contagiosa principalmente transmitida às pessoas\natravés da picada do mosquito Aedes infectado\n(Ae.aegypt e Ae albopictus). Analise as afirmativas:\n\nI. A infecção durante a gestação pode causar microcefalia e outras alterações cerebrais severas no\nfeto; II. O vírus também é transmitido pela via sexual, e pode permanecer até 6 meses no sêmen do\nhomem ; III. Não há evidências de associação observada entre a infecção pelo vírus e a Síndrome\nde Guillain Barré; Estão corretas as afirmativas:","options":{"A":"Apenas a I.","B":"I, II e III.","C":"I e III.","D":"I e II."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-135991","number":"135991","sourceNumber":"135991","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"João Pedro, 7 meses, veio ao Posto de Saúde do Universitário trazido pela sua genitora\npara consulta de rotina de puericultura, que\nse queixou do aparecimento, na criança, de\nvermelhidão no tronco e coceira. A criança tinha história de desmame precoce, mas apresentava\nbom ganho de peso e de estatura nas últimas consultas, bem como desenvolvimento\naparentemente satisfatório. No prontuário, também não havia internações pregressas. Ao exame, o\nlactente apresentava hiperemia, edema e calor, lesão por escoriação com drenagem de pus. Qual a\nconduta mais recomendada para esse caso?","options":{"A":"Iniciar antibiótico oral com penicilinas ou eritromicina e, após melhora, identificar a doença de\nbase;","B":"Iniciar antibiótico oral e associar permetrina tópica por tratar-se provavelmente de escabiose,\nmoléstia comum na população;","C":"Realizar banhos com permanganatos de potássio e antibiótico tópico;","D":"Nenhuma das anteriores."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-108663","number":"108663","sourceNumber":"108663","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 60 anos adquire malária por Plasmodium vivax não grave através de uma\ntransfusão de concentrado de hemácias. Levando em consideração o ciclo biológico do P. vivax, o\ntratamento de primeira escolha deve ser:","options":{"A":"Cloroquina isoladamente.","B":"Cloroquina associada à primaquina.","C":"Arteméter combinado com lumefantrina.","D":"Artesunato combinado com mefloquina."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-108653","number":"108653","sourceNumber":"108653","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de cinco anos de idade, do sexo feminino, procedente do interior do estado do\nAcre, com história de febre há 4 semanas, prostração e mau estado geral. Encontrava-se irritada\nporém orientada. Ao exame físico: face pálida 3+/4+, precórdio hiperdinâmico com íctus propulsivo\nno 4º e 5º espaço intercostal, de duas polpas digitais, próximo ao mamilo esquerdo. Ausculta\ncardíaca: ritmo cardíaco em três tempos com sopro sistólico 3+/6+ audível na borda esternal\nesquerda baixa na região tricúspide e mitral, irradiado à fossa axilar esquerda. Frequência\ncardíaca:\n125 bpm em repouso. Saturação: 95% em ar ambiente. Frequência respiratória: 55 irpm. Abdome\ndoloroso, porém sem sinais de irritação peritoneal. Fígado palpável a 5 cm do rebordo costal\ndireito.\nGenitália feminina sem alterações. Pulsos presentes e simétricos nas quatro extremidades.\n\nMembros: hemiplegia esquerda com evolução de aproximadamente duas semanas. Assinale a\nalternativa que mais explica os sintomas e sinais da paciente:","options":{"A":"Endocardite infecciosa.","B":"Cardite reumática.","C":"Acidente vascular cerebral.","D":"Lúpus eritematoso sistêmico."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-84512","number":"84512","sourceNumber":"84512","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São medicações de primeira escolha para o tratamento da Cistite bacteriana, EXCETO:","options":{"A":"Fosfomicina.","B":"Nitrofurantoína.","C":"Sulfametoxazol + trimetropim.","D":"Ciprofloxacina.","E":"Pivmecillinam."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-66919","number":"66919","sourceNumber":"66919","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 20 anos, do sexo feminino, sem antecedentes patológicos, apresenta um\nquadro de cistite não complicada. Durante sua consulta, explica ao médico do PSF que gostaria de\num tratamento em dose única. Neste caso, qual o tratamento de primeira eleição?","options":{"A":"Pefloxacino 800 mg VO dose única;","B":"Ciprofloxacino 1 g dose única;","C":"Fosfomicinatrometamol 3 g VO dose única;","D":"Nenhuma das acima está correta."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-50043","number":"50043","sourceNumber":"50043","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, masculino, diabético, 52 anos, em uso de hipoglicemiante oral, refere que há\n3 dias iniciou quadro de prurido em bolsa\nescrotal, evoluindo com dor local e hiperemia. Ao exame\nfísico apresenta bolsa escrotal edemaciada com hiperemia, e área de necrose de pele e crepitação\nque se estendem até a região perineal. O diagnóstico mais provável é:","options":{"A":"Gangrena de Fournier.","B":"Epididimite aguda.","C":"Torção testicular com necrose.","D":"Furunculose necrótica."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-37091","number":"37091","sourceNumber":"37091","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa CORRETA. Em relação à etiopatogenia da Meningite Bacteriana\nem crianças, podemos afirmar que:","options":{"A":"A maioria dos casos ocorre a partir de contaminação direta do Sistema Nervoso Central","B":"A invasão do SNC por via hematogênica, após colonização da nasofaringe, é o principal\nmecanismo","C":"A maioria dos casos é precedida de uma infecção como Otite Média Aguda, Sinusite, Mastoidite,\nCelulite Orbitária, etc.","D":"Todas as crianças colonizadas em nasofaringe por bactérias potencialmente patogênicas\ndesenvolverão Meningite","E":"Nenhuma das alternativas"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-314240","number":"314240","sourceNumber":"314240","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O exame direto consiste na visualização das formas amastigotas do parasito da\nLeishmaniose em material obtido das lesões ou dos tecidos afetados. Podemos aceitar como\ncorreto que:","options":{"A":"Constitui o exame de primeira escolha, por ser mais rápido, apesar de maior custo e de difícil\nexecução, embora um examinador experiente seja necessário para o diagnóstico, visto que\ncontaminantes dos corantes, outros agentes infecciosos (principalmente fungos) e até mesmo\nplaquetas podem sugerir a presença de formas amastigotas.","B":"Constitui o exame de primeira escolha, por ser mais rápido, de menor custo e de fácil execução,\nembora um examinador experiente seja\ndesnecessário para o diagnóstico, visto que contaminantes\ndos corantes, outros agentes infecciosos (principalmente fungos) e até mesmo plaquetas podem\nsugerir a presença de formas amastigotas.","C":"Constitui o exame de primeira escolha, por ser mais rápido, de menor custo e de fácil execução,\nembora um examinador experiente seja\nnecessário para o diagnóstico, visto que contaminantes dos\ncorantes, outros agentes infecciosos (principalmente fungos) e até mesmo plaquetas podem sugerir\na ausência de formas amastigotas.","D":"Constitui o exame de primeira escolha, por ser mais rápido, de menor custo e de fácil execução,\nembora um examinador experiente seja\nnecessário para o diagnóstico, visto que contaminantes dos\ncorantes, outros agentes infecciosos (principalmente fungos) e até mesmo plaquetas podem sugerir\na presença de formas amastigotas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-231359","number":"231359","sourceNumber":"231359","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual das opções abaixo contém apenas Flavivirus?","options":{"A":"Hepatite C, Hepatite D, dengue","B":"Coksakie, Mayaro, Febre amarela.","C":"Dengue, Zika, Chikungunya","D":"Dengue, Zika, Febre amarela.","E":"NDA"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-249319","number":"249319","sourceNumber":"249319","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Geralmente, a leptospirose é associada à intensa mialgia, principalmente em região\nlombar e nas panturrilhas. Entretanto,\nnenhum desses sinais clínicos da fase precoce é\nsuficientemente sensível ou específico para diferenciá-la de outras causas de febre aguda. O item\ncom erro é:","options":{"A":"Podem ocorrer diarreia, artralgia, hiperemia ou hemorragia conjuntival, fotofobia, dor ocular e\ntosse.","B":"Exantema ocorre em 10 a 20% dos pacientes e apresenta componentes de eritema macular,\npapular, urticariforme ou purpúrico, distribuídos no tronco ou região pré-tibial.","C":"Em menos de 20% dos casos de leptospirose também podem ocorrer hepatomegalia,\nesplenomegalia e linfadenopatia.","D":"A fase precoce da leptospirose não tende a ser autolimitada e piora entre 3 e 7 dias."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-249321","number":"249321","sourceNumber":"249321","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sufusão conjuntival é um achado característico da leptospirose e é observada em cerca\nde 30% dos pacientes. O item com erro é:","options":{"A":"Costuma ser diagnosticada como uma \"\"síndrome gripal\"\", \"\"virose\"\" ou outras doenças que\nocorrem na mesma época, como dengue ou influenza.","B":"É importante notar a existência de alguns sinais e sintomas que podem ajudar a diferenciar a\nfase precoce da leptospirose de outras causas de doenças febris agudas.","C":"Esse sinal aparece no inicio da fase precoce e caracteriza-se por hiperemia e edema da\nconjuntiva ao longo das fissuras não palpebrais.","D":"Com a progressão da doença, os pacientes também podem desenvolver petéquias e\nhemorragias conjuntivais."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-249323","number":"249323","sourceNumber":"249323","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nas Américas, a hantavirose se manifesta sob diferentes formas, desde doença febril\naguda inespecífica, até quadros pulmonares e cardiovasculares mais severos e característicos,\npodendo evoluir para a síndrome da angústia respiratória (SARA). O item com erro é:","options":{"A":"A infecção humana ocorre mais frequentemente pela inalação de aerossóis, formados a partir da\nurina, fezes e saliva de roedores infectados.","B":"Na fase prodrômica, os pacientes iniciam com manifestações mais frequentes de febre, mialgias,\ndor dorsolombar, dor abdominal, astenia, cefaleia\nintensa e sintomas gastrointestinais como\nnáuseas, vômitos e diarreia.","C":"Quadro inespecífico pode durar cerca de 1 a 6 dias, podendo prolongar-se por até 15 dias, e\ndepois regredir.","D":"Quando surge tosse seca, deve-se suspeitar da possibilidade de evolução para uma fase clínica\nmais leve a cardiopulmonar."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-249324","number":"249324","sourceNumber":"249324","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A hantavirose manifesta na fase cardiopulmonar pelo início da tosse, que em geral é\nseca, mas, em alguns casos, pode ser produtiva, acompanhada por taquicardia, taquidispneia e\nhipoxemia. Apenas um item se mostra correto, assinale-o:","options":{"A":"Derrame pleural, principalmente bilateral, de pequena magnitude, é comum.","B":"Tais manifestações podem ser seguidas por uma lenta evolução para edema pulmonar não\ncardiogênico, hipotensão arterial e colapso circulatório.","C":"Na radiografia do tórax, observa-se infiltrado intersticial difuso bilateral que rapidamente\nevolui\ncom enchimento alveolar, raramente nos hilos e nas bases pulmonares.","D":"A área cardíaca é aumentada."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-249260","number":"249260","sourceNumber":"249260","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O índice cardíaco é baixo e a resistência vascular periférica é elevada na hantavirose\nque manifesta na fase cardiopulmonar, o oposto do\nque se observa no choque séptico. Devido à\nsua gravidade, há mais risco de óbitos nesta fase. Podemos apenas concordar que:","options":{"A":"Comprometimento renal nunca pode aparecer especialmente, em infecções causadas por vírus\nque não ocorrem no Brasil.","B":"Comprometimento renal pode aparecer, mas em geral se apresenta de leve a moderado,\nembora insuficiência renal aguda possa ocorrer,\nespecialmente, em infecções causadas por vírus\nque não ocorrem no Brasil.","C":"Comprometimento renal pode aparecer, mas em geral se apresenta catastrófico.","D":"Comprometimento renal pode aparecer, mas em geral se apresenta de leve a moderado,\nembora insuficiência renal aguda nunca possa\nocorrer, especialmente, em infecções causadas por\nvírus que não ocorrem no Brasil."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215479","number":"215479","sourceNumber":"215479","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O vírus da febre amarela é um arbovírus protótipo do gênero flavivirus, da família\nFlaviviridae. Do ponto de vista etiológico, clínico, imunológico e fisiopatológico, a doença é a\nmesma. Reveste-se da maior importância epidemiológica, por sua gravidade clínica e elevado\npotencial de disseminação em áreas urbanas. Aponte somente o conceito INADEQUADO nas\nalternativas.","options":{"A":"No ciclo silvestre da febre amarela, os primatas não humanos (macacos) são os principais\nhospedeiros e amplificadores do vírus. O homem participa como um hospedeiro acidental.","B":"No ciclo urbano, o homem é o único hospedeiro com importância epidemiológica.","C":"Apenas as fêmeas transmitem o vírus, pois o repasto sanguíneo tem como intuito prover\nnutrientes essenciais para a maturação dos ovos e\na consequente completude do ciclo gonotrófico.","D":"Os mosquitos são considerados os falsos reservatórios do vírus da febre amarela. Uma vez\ninfectados, permanecem assim durante toda a vida."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215245","number":"215245","sourceNumber":"215245","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Não há um perfil clínico definido associado à coinfecção em pacientes portadores de\nHIV. O diagnóstico da coinfecção com HIV\ntem implicações na abordagem da leishmaniose em\nrelação ao diagnóstico, à indicação terapêutica e ao monitoramento de efeitos adversos, à resposta\nterapêutica e à ocorrência de recidivas. NÃO está CORRETO que:","options":{"A":"Não existem casos de indivíduos coinfectados, cuja leishmaniose evolui sem nenhum impacto\naparente da infecção pelo HIV.","B":"Todas as formas de apresentação da infecção por Leishmania spp. já foram descritas em\npessoas infectadas pelo HIV.","C":"A tríade clássica da Leishmania Visceral (LV) é, também, a manifestação mais comum da\ndoença na coinfecção: hepatoesplenomegalia,\nfebre e pancitopenia são observadas em 75% dos\ncasos.","D":"Recomenda-se oferecer a sorologia para HIV para todos os pacientes com LV."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215560","number":"215560","sourceNumber":"215560","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A deposição pulmonar média de um aerossol varia de 6-60% da dose nominal.\nPodemos apenas aceitar como CORRETO:","options":{"A":"Os principais fatores que afetam o diâmetro e a deposição dos aerossois nas vias aéreas não\nsão relacionados com o grau de obstrução ao fluxo\naéreo, e sim a eficácia do dispositivo, a\nformulação dos medicamentos e a técnica de uso.","B":"Os principais fatores que afetam o diâmetro e a deposição dos aerossois nas vias aéreas são\nrelacionados com o grau de obstrução ao fluxo aéreo, a eficácia do dispositivo, a formulação dos\nmedicamentos e a técnica de uso.","C":"Os principais fatores que afetam o diâmetro e a deposição dos aerossois nas vias aéreas são\nrelacionados com o grau de obstrução ao fluxo aéreo, a eficácia do dispositivo, a formulação dos\nmedicamentos, mas não a técnica de uso.","D":"Os principais fatores que afetam o diâmetro e a deposição dos aerossois nas vias aéreas são\nrelacionados com o grau de obstrução ao fluxo aéreo, nunca com a eficácia do dispositivo, nem a\nformulação dos medicamentos e a técnica de uso."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-212180","number":"212180","sourceNumber":"212180","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Dadas as afirmativas a respeito da leishmaniose visceral: I. A forma promastigota\nencontra-se na probóscide do mosquito onde\npode ser inoculada no hospedeiro definitivo e causar\na doença. II. A forma promastigota no hospedeiro definitivo é fagocitada pelos macrófagos e\ntransforma-se na forma amastigota. III. O vetor é da espécie Lutzomyia longipalpis e somente as\nfêmeas podem transmitir a doença por serem hematófagas. IV. A tríade clássica da doença\ncaracteriza-se por febre, hepatoesplenomegalia e pancitopenia. V. O diagnóstico é feito pelo\nencontro de formas promastigotas de leishmanias em esfregaços corados pela coloração de\nGiemsa obtidos por punção de medula óssea. Verifica-se que estão CORRETAS apenas:","options":{"A":"I e IV.","B":"I, III e V.","C":"II, III e V.","D":"II, IV e V.","E":"I, II, III e IV."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216244","number":"216244","sourceNumber":"216244","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Doença causada pelo vírus chikungunya (CHIKV), transmitido por mosquitos do gênero\nAedes, que cursa com enfermidade febril\naguda, subaguda ou crônica. NÃO podemos, apenas,\naceitar que","options":{"A":"a enfermidade aguda caracteriza-se, principalmente, por início insidioso de febre alta, cefaleia,\nmialgias e dor articular intensa.","B":"afetando todos os grupos etários e ambos os sexos.","C":"em uma pequena porcentagem dos casos, a artralgia se torna crônica, podendo persistir por\nanos.","D":"as formas graves e atípicas são raras, mas quando ocorrem, podem, excepcionalmente, evoluir\npara óbito."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216309","number":"216309","sourceNumber":"216309","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Doença causada pelo vírus chikungunya (CHIKV), transmitido por mosquitos do gênero\nAedes com as manifestações clínicas diferem\nconforme a fase da doença. Podemos apenas\nCONCORDAR que","options":{"A":"a febre não pode ser contínua, intermitente ou bifásica, e possui curta duração; porém, a queda\nde temperatura não é associada à piora dos\nsintomas, como na dengue.","B":"a febre pode ser contínua, intermitente, mas nunca bifásica, e possui curta duração; porém, a\nqueda de temperatura não é associada à piora\ndos sintomas, como na dengue.","C":"a febre pode ser contínua, intermitente ou bifásica, e possui curta duração; porém, a queda de\ntemperatura é associada à piora dos sintomas, como na dengue.","D":"a febre pode ser contínua, intermitente ou bifásica, e possui curta duração; porém, a queda de\ntemperatura não é associada à piora dos sintomas, como na dengue."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215549","number":"215549","sourceNumber":"215549","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A poliartralgia tem sido descrita em mais de 90% dos pacientes com Chikungunya na\nfase aguda. A mialgia, quando se apresenta, geralmente é de intensidade leve a moderada.\n\nPodemos, apenas, considerar ERRADO que:","options":{"A":"Normalmente, essa dor é monoarticular e simétrica, embora possa haver assimetria.","B":"Ela acomete grandes e pequenas articulações e abrange, com maior frequência, as regiões mais\ndistais.","C":"Pode haver edema e este, quando presente, normalmente está associado à tenossinovite.","D":"Na fase aguda da poliartralgia, também tem sido observado dor ligamentar."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215552","number":"215552","sourceNumber":"215552","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Doença pelo vírus chikungunya (CHIKV), que cursa com enfermidade febril aguda,\nsubaguda ou crônica, normalmente, o\nexantema é macular ou maculopapular, sendo INCORRETO\nque:","options":{"A":"Acomete cerca de metade dos doentes e, em geral.","B":"Afeta, principalmente, o tronco e as extremidades (incluindo palmas das mãos e plantas dos\npés), podendo atingir a face.","C":"Surge do 2° ao 5° dia após o final da febre.","D":"O prurido está presente em 25% dos pacientes e pode ser generalizado, ou apenas localizado\nna região palmo-plantar."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216333","number":"216333","sourceNumber":"216333","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Na fase subaguda dos pacientes com chikungunya (CHIKV), normalmente, a febre\ndesaparece, mas existem relatos de recorrência. Marque, apenas, o item que NÃO está correto.","options":{"A":"Pode haver persistência ou agravamento da artralgia.","B":"Poliartrite distal, exacerbação da dor articular nas regiões previamente acometidas na primeira\nfase.","C":"Tenossinovite hipertrófica subaguda nas mãos, mais raramente nas falanges e punhos, e nos\ntornozelos.","D":"Síndrome do túnel do carpo pode ocorrer como consequência da tenossinovite hipertrófica."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215558","number":"215558","sourceNumber":"215558","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A poliartralgia tem sido descrita em mais de 90% dos pacientes com Chikungunya na\nfase aguda. Outras manifestações cutâneas\ntambém têm sido relatadas nessa fase, indique o item\ncom conceito ERRADO.","options":{"A":"Dermatite esfoliativa, lesões vesico-bolhosas, hiperpigmentação, fotossensibilidade, lesões\nsimulando eritema nodoso e úlceras orais.","B":"Outros sinais e sintomas descritos na fase aguda de Chikungunya são dor retro-ocular, sem\ncalafrios, conjuntivite com secreção, faringite, náusea, vômitos, diarreia, dor abdominal e\nneurite.","C":"As manifestações do trato gastrointestinal são mais presentes nas crianças.","D":"Pode haver linfadenomegalias cervical, retroauricular ou inguinal associadas."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216228","number":"216228","sourceNumber":"216228","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Para os neonatos de mães infectadas com chikungunya (CHIKV), há o risco de\ntransmissão vertical de aproximadamente 50% no\nperíodo intraparto. Apenas, marque o item que\napresenta conceito ERRADO.","options":{"A":"O recém-nascido é assintomático nos primeiros dias.","B":"Surgimento de sintomas a partir do quarto dia (3 a 7 dias), incluindo presença de febre, síndrome\nálgica, recusa da mamada, exantemas, descamação, hiperpigmentação cutânea e edema de\nextremidades.","C":"As formas graves são raras nos recém-nascidos, como o surgimento de complicações\nneurológicas, hemorrágicas e acometimento miocárdico\n(miocardiopatia hipertrófica, disfunção\nventricular, pericardite).","D":"Os quadros neurológicos, também reconhecidos como sinal de gravidade nessa faixa etária,\nincluem meningoencefalites, edema cerebral, hemorragia intracraniana, convulsões e\nencefalopatias."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216262","number":"216262","sourceNumber":"216262","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O sintoma mais comum na fase crônica em pacientes com chikungunya (CHIKV) é o\nacometimento articular nas atingidas durante a fase aguda, caracterizado por diversos itens.\n\nIndique o INADEQUADO.","options":{"A":"Normalmente, o acometimento é poliarticular e assimétrico, embora possa ser assimétrico e\nmonoarticular.","B":"Também há relatos de dores nas regiões sacroilíaca, lombossacra e cervical.","C":"Ocasionalmente, articulações incomuns, como têmporo mandibulares esterno claviculares, são\nafetadas.","D":"Com frequência razoável, são observadas manifestações decorrentes da síndrome do túnel do\ncarpo, tais como dormência e formigamento das áreas inervadas pelo nervo mediano."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216303","number":"216303","sourceNumber":"216303","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As formas graves da infecção pelo chikungunya (CHIKV) acometem, com maior\nfrequência, pacientes com comorbidades com história de convulsão febril, diabetes, asma,\nalcoolismo, doenças reumatológicas, anemia falciforme, talassemia e hipertensão arterial\nsistêmica),estando FORA do contexto, apenas,","options":{"A":"crianças.","B":"pacientes com idade acima de 65 anos.","C":"uso de alguns fármacos (aspirina, anti-inflamatórios e paracetamol em altas doses).","D":"todo paciente que apresentar sinais clínicos e/ou laboratoriais que indiquem a necessidade de\ninternação em unidade de terapia intensiva, ou risco de morte, não deve ser considerado como\nforma grave da doença."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215296","number":"215296","sourceNumber":"215296","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A vacinação contra febre amarela (VFA ? atenuada) é a medida mais importante e\neficaz para prevenção e controle da doença,\na vacina usada no Brasil é produzida pelo Instituto de\nTecnologia em Imunobiológicos (Bio-Manguinhos) da Fundação Oswaldo Cruz (Fiocruz) e, quanto a\nela, podemos considerar inadequado que:","options":{"A":"A vacina consiste de vírus vivos atenuados da subcepa 17DD.","B":"A vacina consiste de vírus vivos cultivados em embrião de galinha.","C":"É um imunobiológico seguro e altamente eficaz na proteção contra a doença, com\nimunogenicidade de 90% a 98% de proteção.","D":"Os anticorpos protetores aparecem entre o terceiro e o décimo dia após a aplicação da vacina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216314","number":"216314","sourceNumber":"216314","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em regiões onde ocorrem epidemias por outros arbovírus, com sinais e sintomas\nsemelhantes aos apresentados durante a infecção\npelo vírus chikungunya, o diagnóstico específico\né importante. Nesse contexto, podemos CONCORDAR que,","options":{"A":"assim como para os casos em pacientes maiores de 65 anos e naqueles em que a conduta\nterapêutica deve ser diferenciada.","B":"nunca para os casos em pacientes maiores de 65 anos e naqueles em que a conduta\nterapêutica deve ser diferenciada.","C":"assim como para os casos em pacientes maiores de 25 anos e naqueles em que a conduta\nterapêutica deve ser diferenciada.","D":"assim como para os casos em pacientes maiores de 65 anos e naqueles em que a conduta\nterapêutica não deve ser diferenciada."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216328","number":"216328","sourceNumber":"216328","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O diagnóstico diferencial de chikungunya (CHIKV) é feito com outras doenças febris\nagudas associadas à artralgia. O clínico deve\nestar atento para causas potencialmente fatais e que\nexijam conduta medicamentosa específica imediata, como artrite séptica. Somente está\nconceitualmente ERRADO o item:","options":{"A":"Malária: história de exposição em áreas de transmissão, periodicidade da febre, paroxismos,\ninsuficiência renal, icterícia, alteração do nível de consciência, hepato ou esplenomegalia.","B":"Artrite séptica: leucocitose, derrame articular, acometimento de grandes articulações e história\nde trauma exclui o diagnóstico.","C":"Leptospirose: mialgia intensa em panturrilhas, sufusão ocular, icterícia rubínica, oligúria,\nhemorragia subconjuntival. Considerar história de exposição a águas contaminadas.","D":"Febre reumática: poliartrite migratória de grandes articulações, história de infecção de\ngarganta.\n\nConsiderar os critérios de Jones para a febre reumática e evidência de infecção prévia pelo\nStreptococos."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216345","number":"216345","sourceNumber":"216345","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Dentro das definições de caso suspeito de infecção pelo chikungunya (CHIKV),\ndevemos CONCORDAR que","options":{"A":"paciente com febre de início súbito maior que 36,5ºC e artralgia ou artrite intensa de início\nagudo, não explicado por outras condições,\nsendo residente ou tendo visitado áreas endêmicas ou\nepidêmicas até duas semanas antes do início dos sintomas, ou que tenha vínculo epidemiológico\ncom caso importado confirmado.","B":"paciente com febre de início insidioso maior que 38,5ºC e artralgia ou artrite intensa de início\nagudo, não explicado por outras condições,\nsendo residente ou tendo visitado áreas endêmicas ou\nepidêmicas até duas semanas antes do início dos sintomas, ou que tenha vínculo epidemiológico\ncom caso importado confirmado.","C":"paciente com febre de início súbito maior que 38,5ºC e artralgia ou artrite intensa de início\nagudo, não explicado por outras condições,\nsendo residente ou tendo visitado áreas endêmicas ou\nepidêmicas até duas semanas antes do início dos sintomas, ou que tenha vínculo epidemiológico\ncom caso importado confirmado.","D":"paciente com febre de início súbito maior que 38,5ºC e artralgia ou artrite intensa de início\nagudo, não explicado por outras condições,\nsendo residente ou tendo visitado áreas endêmicas ou\nepidêmicas até dois dias antes do início dos sintomas, ou que tenha vínculo epidemiológico com\ncaso importado confirmado."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183066","number":"183066","sourceNumber":"183066","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A hantavirose se manifesta sob diferentes formas, desde doença febril aguda\ninespecífica, até quadros pulmonares e\ncardiovasculares mais severos e característicos, podendo\nevoluir para a síndrome da angústia respiratória (SARA). Sendo INADEQUADO o seguinte:","options":{"A":"na América do Sul, foi observado importante comprometimento cardíaco, passando a ser\ndenominada de síndrome cardiopulmonar por hantavírus (SCPH).","B":"vírus do gênero Hantavírus, da família Bunyaviridae, sendo o único buniavírus que não é um\narbovírus.","C":"a infecção humana ocorre mais frequentemente pela inalação de aerossóis, formados a partir da\nurina, fezes e saliva de roedores infectados.","D":"cardiopulmonar é caracterizada pelo início da tosse, que em geral é produtiva, acompanhada de\nbradicardia, taquidispneia e hipoxemia"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183642","number":"183642","sourceNumber":"183642","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a infecção pelo vírus da Chikungunya, assinale a alternativa INCORRETA.","options":{"A":"A viremia persiste entre dois e sete dias após o surgimento das manifestações clínicas.","B":"As dores nas articulações são geralmente simétricas e ocorrem mais comumente em punhos,\ncotovelos, dedos, joelhos e tornozelos, mas\ntambém podem afetar as articulações mais proximais.","C":"O edema de intensidade variável, localizado nas mãos e nos pés, é também um achado\nfrequente nos latentes no primeiro ano de vida.","D":"O prurido está presente em 25% dos pacientes e pode ser generalizado ou apenas localizado na\nregião palmoplantar."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-187864","number":"187864","sourceNumber":"187864","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Adolescente, sexo feminino, 11 anos de idade, previamente saudável, apresenta há\ntrês dias quadro de febre elevada (39ºC),\nacompanhada de artralgia e exantema, O exame físico\nobjetivo mostra certa prostração, ausência de petéquias e rash cutâneo. Hidratado, pulsos\nperiféricos palpados. PA = 120 X 65mmHg. Fígado e baço não palpados. Restante do exame sem\nalterações. O hemograma revela Hb: 11,5 g/dl; Htc: 34%, Hem: 4.250.000/mm³, Leucócitos:\n2.800/mm³; bastonete:0; segmentados: 32%; linfócitos: 60%; linfócitos atípicos: 8%. Plaquetas:\n90.000/mm³. Dentre o diagnóstico diferencial das arboviroses, a MAIS PROVÁVEL é:","options":{"A":"Chikungunya","B":"Dengue","C":"Febre amarela","D":"Zika"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-181406","number":"181406","sourceNumber":"181406","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No caso de suspeita de Dengue com dor abdominal, vômitos persistentes e\nhepatomegalia, qual é a melhor conduta?","options":{"A":"Manter sob observação até estabilização do quadro.","B":"Iniciar terapia de reidratação oral antes mesmo de colher exames.","C":"Solicitar hemograma, função hepática, isolamento viral e sorologias.","D":"Notificar e encaminhar, imediatamente, para Unidade de Referência.","E":"Iniciar hidratação venosa, assegurar bom acesso venoso, vias aéreas pérvias e monitorar."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-131379","number":"131379","sourceNumber":"131379","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual a droga de escolha para o tratamento da meningoencefalite meningocócica?","options":{"A":"Ampicilina + gentamicina.","B":"Ampicilina.","C":"Ceftriaxona.","D":"Cefepime.","E":"NDA."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134827","number":"134827","sourceNumber":"134827","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em uma unidade básica de saúde a equipe responsável pela vigilância epidemiológica\nrecebeu uma notificação de um caso suspeito\nde meningite bacteriana em uma criança com dois\nanos matriculada em uma creche da região. Qual é o procedimento correto a ser realizado após a\ninvestigação inicial?","options":{"A":"Se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia com rifampicina em\ncontatos íntimos no prazo de 48h da exposição.","B":"Se o agente isolado for Haemophilus influenzae não há necessidade de realização de\nquimioprofilaxia em contatos íntimos.","C":"Se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia em contatos com\nabordagem ampliada com o uso de ceftriaxona no prazo de 96h da exposição.","D":"Independentemente do agente etiológico, realizar quimioprofilaxia em contatos com\nabordagem ampliada com uso de ceftriaxona no prazo de 96h da exposição."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134338","number":"134338","sourceNumber":"134338","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Tem-se observado que a classificação clínica da OMS para dengue tem alta\nsensibilidade e baixa especificidade. Por outro\nlado, um dos testes rápidos em estudo ? o NS1 ?\nmostra baixa sensibilidade e alta especificidade (Chateri et al., 2011). Portanto, na abordagem\ndiagnóstica de pacientes febris com suspeita de dengue:","options":{"A":"O teste NS1 tem baixo valor preditivo positivo e a classificação da OMS, alto valor preditivo\nnegativo.","B":"A classificação da OMS pode ser usada para excluir a doença e o teste NS1 para confirmá-la.","C":"A classificação da OMS resultará em poucos falso-negativos, enquanto o teste NS1 em muitos\nfalso-positivos.","D":"O teste NS1 deve ser usado como teste de rastreamento, enquanto a classificação da OMS\ndeve ser usada na etapa posterior da\n\ninvestigação."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-109728","number":"109728","sourceNumber":"109728","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, 68 anos, com antecedente de diabetes mellitus tipo 2, é\ninternada por pielonefrite. Urinocultura positiva para Escherichia Coli sensível à ceftriaxona.\nIniciado\ntratamento com ceftriaxona 2 g/dia. Após cinco dias de tratamento, a paciente mantém febre,\nleucocitúria e leucocitose com desvio. Assinale abaixo a conduta MAIS apropriada para o caso\ncitado:","options":{"A":"Trocar antibiótico para norfloxacino, pois sua ação é superior ao ceftriaxona em infecções do\ntrato urinário.","B":"Associar azitromicina e metronidazol, para aumentar espectro para germes atípicos e\nanaeróbios.","C":"Realizar ultrassonografia de abdome, para afastar fatores complicantes que requerem\nintervenção urológica.","D":"Manter antibioticoterapia, pois é normal a manutenção de febre em quadros de pielonefrite até o\noitavo dia de tratamento."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-110013","number":"110013","sourceNumber":"110013","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um menino de 9 anos com uma válvula aórtica bicúspede desenvolve endocardite\nbacteriana após extração de um dente. O\norganismo mais provável de ter causado endocardite\nnesse paciente é","options":{"A":"Candida albicans.","B":"Escherichia coli.","C":"Staphylococcus aureus.","D":"Staphylococcus mitis."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-86872","number":"86872","sourceNumber":"86872","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Lucas, 2 anos, veio acompanhado da mãe com quadro de cefaleia, vômitos e\nrebaixamento do nível de consciência. Como\nantecedente, a mãe refere que o menor estava\ngripado há 3 dias, com febre, tosse e coriza e usou acido acetilsalicílico. Assinale a alternativa\nque\ncontém a conduta correta para o caso.","options":{"A":"O caso deve ser conduzido na USF com a administração de dipirona e metoclopramida\nendovenosos e posterior observação;","B":"O médico deve encaminhar o menor imediatamente ao pronto-socorro em uma Unidade de\nSuporte Avançado do SAMU;","C":"O menor deve ser encaminhado à UPA para uma avaliação com pediatra;","D":"Deve ser realizada a antibioticoterapia ainda na USF e posterior encaminhamento ao hospital\nmunicipal;","E":"A conduta deve ser hidratação endovenosa com fase rápida de soro fisiológico."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-86805","number":"86805","sourceNumber":"86805","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual das classes de antibióticos abaixo é a primeira escolha para tratamento da\npielonefrite em adultos?","options":{"A":"Nitrofurantoin;","B":"Betalactâmicos;","C":"Aminoglicosídeos;","D":"Sulfas;","E":"Fluoroquinolonas."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-49615","number":"49615","sourceNumber":"49615","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente com história de dois dias de febre alta e cefaleia intensa. Ao exame,\napresenta rigidez de nuca. O liquor apresenta-se\nturvo e na bacterioscopia visualizam-se cocos\nGram-negativos. Baseado nesses achados, o tratamento inicial será dirigido para:","options":{"A":"Streptococcus pneumoniae.","B":"Staphylococcus aureus.","C":"Staphylococcus epidermidis.","D":"Haemophilus influenzae.","E":"Neisseria meningitidis."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-49628","number":"49628","sourceNumber":"49628","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa correta em relação aos fatores de risco para o desenvolvimento\nde infecção urinária na mulher:","options":{"A":"Uso de diafragmas e espermicidas.","B":"Hipoestrogenismo.","C":"Gravidez.","D":"Prolapso genital.","E":"Todas as respostas anteriores."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-13148","number":"13148","sourceNumber":"13148","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à meningite, é correto afirmar que (melhor resposta):","options":{"A":"A meningite tuberculosa é a causa mais frequente de meningite aguda.","B":"Empiema subdural é uma complicação que pode ocorrer na meningite bacteriana.","C":"O Streptococcus pneumoniae é o agente etiológico mais comum de meningite bacteriana aguda,\nno recém-nascido.","D":"O exame de Liquor (LCR) é o exame de escolha para confirmar o diagnóstico de meningite.","E":"As afirmativas B e D estão corretas."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-362479","number":"362479","sourceNumber":"362479","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Alternativas que NÃO corresponde ao uso do antimalárico tafenoquina?","options":{"A":"Pode ser usada para prevenção de recídiva de Plasmodium vivax ou ovale.","B":"Assim como a primaquina, pode levar a metemoglobinemia.","C":"Pode-se usar o referido fármaco mesmo na deficiência de G6PD (glicose-6-fosfato\ndesidrogenase).","D":"Pode ser usada para prevenção de malária vivax e falciparum antes e durante a viagem para\náreas endêmicas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-362444","number":"362444","sourceNumber":"362444","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Jaime, 57 anos, morador de cidade com epidemia de dengue, procura a UBS com\nquadro de febre de até 39 °C há 3 dias\nassociado à dor retro orbital de forte intensidade e mialgia.\nSem quaisquer outras queixas. Apresenta diabetes mellitus em uso de metformina 850mg/dia -\núltima hemoglobina glicada: 7,2%. Nega outras doenças. No exame físico, bom estado geral,\nhidratado, corado, eupneico. Temperatura axilar: 38,2 °C, frequência cardíaca: 104 bpm, pressão\narterial: 128/80 mmHg, frequência respiratória: 18 mrpm. Ausculta cardíaca e pulmonar normais.\nAbdômen com dor discreta à palpação difusamente, sem dor à descompressão súbita. Ausência de\nvisceromegalias. Conjuntiva normal. Ausência de lesões de pele. Prova do laço negativa. Depois da\navaliação, Jaime é notificado como caso suspeito de dengue. Seguindo o fluxograma mais recente\nde classificação de risco para dengue do Ministério da Saúde, a conduta mais adequada é iniciar:","options":{"A":"Hidratação oral, prescrever paracetamol, conforme sintomas, e liberar paciente para ser\nreavaliado quando cessar a febre (período em\nque costumam ocorrer as complicações) ou antes se\nsinais de alerta.","B":"Hidratação oral, solicitar hemograma com plaquetas (conforme fluxo local) e prescrever\nparacetamol, conforme sintomas. Liberar o paciente\npara ser reavaliado o mais breve possível,\nassim que o exame esteja pronto ou antes se sinais de alerta.","C":"Hidratação venosa, imediatamente, e sintomáticos conforme necessidade. Encaminhar para o\nhospital para realização de exames laboratoriais. Orientar que, caso seja liberado depois da\navaliação inicial no hospital, deve retornar em 48 horas ou antes se sinais de alerta.","D":"Hidratação oral e prescrever paracetamol, conforme sintomas. Se disponível no local, solicitar\nhemograma com plaquetas e liberar paciente apenas se exame normal e depois de reavaliação\nclínica, com orientação de retorno em 48 horas ou antes se sinais de alerta."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-327227","number":"327227","sourceNumber":"327227","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a classificação de Risco e Manejo do paciente com dengue, marque a alternativa\nCORRETA:","options":{"A":"Para o grupo B, a hidratação oral é a mesma conforme recomendada para o grupo A. Se\npacientes apresentarem hemoconcentração com\nHematócrito aumentado em mais de 10%, ou em\ncrianças > 38%, mulheres > 44% e homens > 50%, ficam dispensados de serem mantidos em leitos\nde observação para tratamento com hidratação oral supervisionada ou parenteral.","B":"O grupo C é constituído por pacientes que podem ser acompanhados em leito de internação por\nperíodo mínimo de 48h e não apresentam sinal de alarme.","C":"O grupo A é constituído por pacientes com ausência de sangramentos, sem sinal de alarme,\nsem risco social e sem comorbidades. Neste grupo, a Hidratação venosa é preferencial à\nhidratação oral.","D":"O grupo D é constituído por pacientes que apresentam sinais de choque."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-327287","number":"327287","sourceNumber":"327287","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Referente a Febre Hemorrágica da Dengue (FHD), qual é o fator determinante para o\nquadro da doença:","options":{"A":"Extravasamento capilar","B":"Trombocitopenia","C":"TAP prolongado","D":"Tempo de sangramento anormal"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-298196","number":"298196","sourceNumber":"298196","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O tratamento da malária grave complicada se dá preferencialmente com o uso de?","options":{"A":"Artemeter + Lumefantrina","B":"Cloroquina + primaquina","C":"Mefloquina","D":"Artesunate IV ou artemether IM"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-298262","number":"298262","sourceNumber":"298262","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"HJS, 4 anos mora na área urbana de Manaus. Há 55 dias foi tomar banho de igarapé\nem área sabidamente endêmica para malária.\nDepois de 12 dias iniciou febre, cefaleia intensa e\ndores no corpo. Foi diagnosticado com malária vivax e recebeu tratamento adequadamente\nadministrado com primaquina e cloroquina por 7 dias, de acordo com o Guia de Tratamento de\nMalária do Ministério da Saúde. Há 2 dias voltou a ter febre e cefaleia intensa. A família nega ter\nido novamente à área de risco para malária. Entretanto, no exame de gota espessa, veio positivo\n2+. O pediatra de plantão refere que provavelmente trata-se de recaída e que agora o tratamento\ndeve ser diferente do primeiro episódio. O paciente não tem deficiência de G6PD. Qual esquema\nterapêutico deve ser prescrito de acordo com o Guia de Tratamento de Malária do Ministério da\nSaúde?","options":{"A":"Cloroquina semanal por 6 semanas.","B":"Artemeter + lumefantrina por 3 dias e primaquina por 14 dias.","C":"Clindamicina + Cloroquina por 7 dias.","D":"Artesunato + mefloquina por 10 dias."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-176013","number":"176013","sourceNumber":"176013","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Gestante de 11 semanas foi diagnosticada com malária por P. vivax. Qual a droga de\nescolha para tratar a paciente?","options":{"A":"Cloroquina.","B":"Quinina associada à clindamicina.","C":"Artemeter associada à lumefantrina.","D":"Primaquina."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151864","number":"151864","sourceNumber":"151864","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Arteméter e lumefantrina são tratamentos de escolha para malária por:","options":{"A":"Plasmodium vivax formas graves.","B":"Plasmodium falciparum e P. vivax.","C":"Plasmodium ovale e P. vivax.","D":"Plasmodium falciparum."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151884","number":"151884","sourceNumber":"151884","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 23 anos. Poliartrite simétrica de pequenas e grandes articulações de início\nsúbito evoluindo há 7 dias, acompanhada de febre\nde 39 graus Celsius e erupção cutânea\nmorbiliforme envolvendo tronco e membros com leve prurido. É vendedora ambulante na feira\nManaus Moderna, G1P1A0. Ao exame físico, bom estado geral deambulando, eupneica, corada,\ntórax e abdome sem anormalidades. Há aumento de volume, dor, rubor e calor em interfalangeanas\nproximais, metacarpofalangeanas, punhos, joelhos e tornozelos. Qual é a hipótese diagnóstica\ninicial para a paciente?","options":{"A":"Chikungunya.","B":"Artrite reumatoide.","C":"Poliangeite granulomatosa.","D":"Lúpus eritematoso sistêmico."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151917","number":"151917","sourceNumber":"151917","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Escolar de 8 anos, há 3 dias atendida com quadro sugestivo de dengue, retorna ao\nserviço de saúde. É diagnosticada com síndrome do choque da dengue. Os elementos\nclinicolaboratoriais que sugerem este diagnóstico são:","options":{"A":"Leucocitose, plaquetose, hemoconcentração e vômito.","B":"Leucocitose, plaquetopenia, anemia, náuseas e vômitos.","C":"Leucopenia, plaquetopenia, hepatomegalia dolorosa e hemodiluição.","D":"Leucopenia, plaquetopenia, hemoconcentração, hipotensão e dor abdominal."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151938","number":"151938","sourceNumber":"151938","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O vírus Zika foi isolado pela primeira vez em primatas não humanos em Uganda. No\nBrasil, a transmissão autóctone deste vírus começou a ocorrer em abril de 2015. Em relação a este\nagravo, podemos afirmar:","options":{"A":"O diagnóstico laboratorial é feito pela detecção do RNA viral até 10 dias após o início dos\nsintomas.","B":"Se caracteriza como doença viral subaguda com tendência a cronificação, sendo transmitida por\nmosquitos como Aedes aegyptis.","C":"Clinicamente, apresenta exantema maculo-papular pruriginoso, hiperemia conjuntival, febre\nintermitente, artralgia, mialgia.","D":"Clinicamente, apresenta exantema maculo-papular pruriginoso, hiperemia conjuntival purulenta\npruriginosa, febre artralgia intensa, hemorragias."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-139098","number":"139098","sourceNumber":"139098","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A pielonefrite aguda é melhor diagnosticada por:","options":{"A":"Bacteriúria e piúria.","B":"Calafrios, febre e dor no flanco.","C":"Escara renal.","D":"Prejuízo da função renal."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-129720","number":"129720","sourceNumber":"129720","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem com 52 anos continua a ter picos febris, apesar da cateterização\nsuprapúbica da bexiga e 36 horas de\ntratamento com antibióticos intravenosos de amplo espectro.\nA ultrassonografia transretal confirma um grande abscesso prostático. Qual é o melhor passo a\nseguir?","options":{"A":"Drenagem transretal.","B":"Drenagem transuretral.","C":"Aspiração com agulha percutânea.","D":"Aspiração com agulha transretal."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-107590","number":"107590","sourceNumber":"107590","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A respeito das doenças infecciosas que cursam com febre hemorrágica, marque a\nalternativa INCORRETA:","options":{"A":"Dentre os sintomas causados pela infecção pelo vírus Ebola, estão: quadro súbito de febre,\ncefaleia, faringite, mialgias e astenia.","B":"Embora a febre hemorrágica associada à dengue possa ocorrer na dengue primária, a maioria\ndos casos está associada à infecção de\nhospedeiros anteriormente sensibilizados pela infecção\nprévia por outro sorotipo.","C":"Muitos dos casos de febre amarela são abruptos, breves e autolimitados. Infecções inaparentes\nsão comuns e a doença sintomática costuma ser\nrelativamente branda.","D":"A febre Chikungunya é caracterizada por início súbito de febre e artralgia grave. Sintomas\nconstitucionais, calafrios, cefaleia, fotofobia, dor retro-orbitária, mialgias e faringite são\nincomuns."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-103797","number":"103797","sourceNumber":"103797","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Infecção que se dissemina através da fáscia de Buck, ao longo dos planos fasciais,\ndartos, escroto, estendendo-se para a fáscia de\nColles do períneo, podendo atingir a fáscia de\nScarpa:","options":{"A":"Síndrome de Fournier.","B":"Gangrena de Meleney.","C":"Abscesso isquiorretal.","D":"Miosite clostrídica."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-103863","number":"103863","sourceNumber":"103863","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Adolescente de 15 anos, sexo masculino, procurou o Pronto atendimento apresentando\nuretrite (síndrome uretral aguda). Relata vida\nsexual ativa com parceira fixa, sem uso de\npreservativo. Qual o agente etiológico provável?","options":{"A":"Haemophilus ducreyi","B":"Chlamydia trachomatis","C":"Cândida Albicans","D":"Herpes vírus"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-81924","number":"81924","sourceNumber":"81924","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O método de imagem mais sensível para o diagnóstico do abscesso renal é:","options":{"A":"A cintilografia com índio","B":"A cintilografia com gálio","C":"A urografia excretora","D":"A ultrassonografia","E":"A tomografia computadorizada"},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-34181","number":"34181","sourceNumber":"34181","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual a causa de meningite no período neonatal (0 a 28 dias de vida)?","options":{"A":"Streptococcus pneumoniae.","B":"Streptococcus do grupo B.","C":"Neisseria meningitidis.","D":"Haemophylus influenzae tipo B.","E":"Fungo."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-7443","number":"7443","sourceNumber":"7443","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção ascendente é a via de contaminação mais comum nos casos de pielonefrite\naguda. Nesses casos o agente etiológico em\nmais de 85% dos casos é:","options":{"A":"Proteus.","B":"Escherichia coli.","C":"Pseudomonas.","D":"Estafilococos aureus.","E":"Cândida albicans."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-7520","number":"7520","sourceNumber":"7520","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Você está de plantão no pronto-socorro e recebe um homem, 49 anos, com história de\nfebre alta (até 40°C) contínua, há quatro dias, acompanhada de tosse produtiva e grande queda de\nestado geral. Há um dia tornou-se dispneico e há cerca de 12 horas, encontra-se sonolento e\nconfuso. Ao exame físico de entrada, obtêm-se os seguintes dados:T=39,7°, FR=32/min, com\nestridores crepitantes em ½ inferior do hemitórax direito e 1/3 inferior do hemitórax esquerdo.\n\nAusculta cardíaca normal com FC:120bpm. Nota-se ainda um ferimento em região dorsal do pé\nesquerdo, drenando material purulento em grande\nquantidade e bolhas disseminadas em membros\ninferiores. Qual seria sua hipótese diagnóstica e principais medidas terapêuticas iniciais?","options":{"A":"endocardite por Staphylococcus viridans-antibioticoterapia sistêmica com penicilina cristalina e\ngentamicina; drogas vasoativas e heparinização.","B":"tétano-soro antitetânico (SAT); benzodizepínicos em dose elevadas; desbridamento do ferimento\ne antibioticoterapia sistêmica com clidamicina.","C":"septicemia por Staphylococcus viridans, antibioticoterapia sistêmica com penicilina cristalina;\nimunoglobulina hiperimune contra tétano (TIG) e desbridamento extenso do ferimento.","D":"endocardite por Staphylococcus coagulase-negativo-antibioticoterapia sistêmica com\ncefalosporina de primeira geração e drogas vasoativas.","E":"septicemia por Staphylococcus aureus - antibioticoterapia sistêmica com oxacilina, cuidados de\nsuporte, desbridamento do ferimento; profilaxia antitetânica de acordo com o passado vacinal do\npaciente."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-7417","number":"7417","sourceNumber":"7417","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No Brasil, os trabalhos têm mostrado que o principal agente responsável pelos casos\nde Endocardite Infecciosa é:","options":{"A":"Enterococos.","B":"Cândida albicans.","C":"Staphylococcus aureus.","D":"Proteus.","E":"Streptococcus viridans."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-13274","number":"13274","sourceNumber":"13274","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção microbiana da superfície endotelial do coração resulta em síndrome da\nendocardite infecciosa. Com muita frequência, nos usuários de drogas injetáveis, a valva tricúspide\né acometida. Nesta situação, qual o agente infeccioso mais comumente isolado?","options":{"A":"Staphylococcus aureus.","B":"Haemophilus.","C":"Staphylococcus epidermidis.","D":"Estreptococos do grupo varidans.","E":"Mieloma múltiplo."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-13277","number":"13277","sourceNumber":"13277","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Existem determinados achados que, especialmente quando surgem associados,\npermitem estabelecer com mais convicção o diagnóstico\ndiferencial entre uma infecção do trato\nurinário baixo e uma pielonefrite aguda. Assinale a opção que os apresenta:","options":{"A":"Mais de 100 piócitos por campo, hematuria e febre.","B":"Bacteriúna maciça hematúria e dor lombar.","C":"Dor lombar, cilindros leucocitários e febre.","D":"Mais de 100 hemácias por campo, disúria e bacteriúria maciça.","E":"Piúria, bacteriúria e hematúria."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-9981","number":"9981","sourceNumber":"9981","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O fator de predisposição mais comum para infecções do trato urinário adquiridas no\nhospital é:","options":{"A":"Procedimento cirúrgico.","B":"Utilização de antibióticos.","C":"Idade.","D":"Sondagem vesical.","E":"Diabetes Mellitus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-49364","number":"49364","sourceNumber":"49364","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher, 23 anos de idade, com história de febre reumática desde os 18 anos de idade,\nda qual resultou regurgitação mitral leve.\nEm uso de penicilina benzatina, a cada três semanas, há\ncinco anos, deverá fazer tratamento odontológico simples com remoção de tártaro. Não teve\nrecidivas reumáticas e se queixa do uso das injeções mensais, perguntando se pode\n\ninterrompê-las. A orientação, com base em evidências científicas, é:","options":{"A":"Continuar a penicilina benzatina por, no mínimo, mais cinco anos para profilaxia de recidiva\nreumática e informar que não há indicação para profilaxia antibiótica antes do procedimento\ndentário;","B":"Continuar a penicilina benzatina por, no mínimo, mais cinco anos, fazer amoxacilina 2 gramas,\nvia oral, 1 hora após o procedimento\ndentário;","C":"Suspender a penicilina benzatina, fazer apenas amoxacilina 2 gramas, via oral, 1 hora antes do\nprocedimento dentário;","D":"Suspender a penicilina benzatina, considerando que já é adulta, e informar que não há indicação\npara profilaxia antibiótica antes do\nprocedimento dentário;","E":"Manter a penicilina benzatina até os 25 anos de idade e fazer profilaxia com amoxicilina 2\ngramas, via oral, 1 hora após o procedimento dentário."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-49466","number":"49466","sourceNumber":"49466","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Dentre os pacientes relacionados a seguir, o que tem indicação para tratamento de\ninfecção do trato urinário é:","options":{"A":"Homem, 35 anos de idade, com traumatismo raquimedular em uso de cateter de permanência,\nassintomático, com urocultura 3,4 x 10 (elevado a 5) UFC/ml para Proteus mirabilis.","B":"Homem, 75 anos de idade, com indicação de ressecção transuretral por hipertrofia prostática e\nurocultura 1,2 x 10 (elevado a 5) UFC/ml para E. coli.","C":"Mulher, 65 anos de idade, diabética, sem sintomas urinários ou febre com urocultura 2,2 x 10\n(elevado a 5) UFC/ml para E. coli.","D":"Mulher, 23 anos de idade, com febre sem disúria e urocultura 4,5 x 10² UFC/ml para E. coli, sem\npiúria em amostra única coletada por jato médio.","E":"Mulher, 55 anos de idade, com desconforto à micção, sem febre, com 25 piócitos/campo, em\nsumário de urina, urocultura \"menor que\" 10 (elevado a 5) UFC/ml, em duas amostras por coleta de\njato médio."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-11141","number":"11141","sourceNumber":"11141","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher, 75 anos de idade, com doença de Alzheimer, em ambiente asilar, com\nincontinência esfincteriana prévia, vem há dois\ndias com agitação psicomotora intercalada por\nperíodos de sonolência. Não teve diarreia e a temperatura medida pela cuidadora foi de 37,8°C. Ao\nexame físico, apresenta- se sem rigidez nucal, sem sinais de localização, PR: 108 bpm, FR: 21 ipm,\nausculta cardiorrespiratória evidenciando discretos crépitos inspiratórios e expiratórios em base,\nsem variação com a tosse. Abdome flácido, indolor. A investigação deve começar por:","options":{"A":"tomografia computadorizada de crânio.","B":"Rx de tórax em PA e perfil, gram e ziehl do escarro.","C":"ecocardiograma bidimensional.","D":"sumário de urina e uroculturas.","E":"punção liquórica."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-11165","number":"11165","sourceNumber":"11165","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, 10 anos de idade, sexo masculino, vem apresentando há 2 semanas, após\nextração dentária, queda progressiva do estado geral, febre persistente, palidez, sudorese. Nos\nantecedentes, é portador de insuficiência da válvula mitral de grau leve, faz uso de penicilina\nbenzatina de 21 em 21 dias, há 2 anos. O exame físico: dispneia com SS em foco da ponta,\npresença de 3ª bulha. Hemograma com leucocitose e desvio à esquerda. Ecocardiograma mostra\nmassa cardíaca oscilante em valva mitral. O diagnóstico mais provável é:","options":{"A":"cardite reumática.","B":"septicemia.","C":"endocardite infecciosa.","D":"pneumonia estafilocócica.","E":"fibroelastose."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-358778","number":"358778","sourceNumber":"358778","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nos primórdios da circulação do vírus da dengue no Brasil, sua epidemiologia se\ncaracterizava pelo acometimento de grupos populacionais de adultos jovens. Mais recentemente,\num novo cenário foi detectado, com um deslocamento na faixa etária dos acometidos, com pelo\nmenos 25% de indivíduos notificados e hospitalizados apresentando 15 anos de idade ou menos.\nSobre a Dengue, assinale a alternativa correta.","options":{"A":"É causada por um vírus RNA, cujos vetores são mosquitos do gênero Anopheles.","B":"O isolamento viral deve ser feito idealmente após o sétimo dia de início da febre.","C":"Pulso rápido e fino, vômitos persistentes e PA divergente são alguns sinais de alerta da dengue\nhemorrágica.","D":"A principal característica fisiopatológica associada ao grau de severidade da Febre Hemorrágica\ndo Dengue (FHD) é o extravasamento do plasma.","E":"Sarampo e rubéola não são diagnósticos diferenciais para o quadro de dengue clássico."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-314286","number":"314286","sourceNumber":"314286","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a Leptospirose, é correto afirmar que","options":{"A":"a mortalidade é elevada em pacientes anictéricos.","B":"a fase septicêmica ocorre entre o 6° e o 12° dia da doença.","C":"na fase septicêmica, esplenomegalia e hepatomegalia são achados comuns.","D":"na fase imune, iridociclite, neurite óptica e neuropatia periférica são achados comuns.","E":"a leptospirose ictérica é uma forma grave da doença, com icterícia causada por hemólise\nintravascular."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-283848","number":"283848","sourceNumber":"283848","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O paciente com dengue grave exige manejo específico dado seu potencial de desfecho\ndesfavorável. Considere um homem adulto, diagnosticado com dengue, atualmente no 3º dia de\ninício dos sintomas. A alternativa que contém um achado que sugere dengue grave é:","options":{"A":"Oligúria.","B":"Hematócrito 40%.","C":"Cefaleia persistente.","D":"Plaquetas 118.000 mm³.","E":"Idade maior que 65 anos."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215618","number":"215618","sourceNumber":"215618","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Até o momento, não há tratamento antiviral específico para a febre de chikungunya\n(CHIKV). A terapia utilizada é analgesia e de\nsuporte às de compensações clínicas causadas pela\ndoença. É necessário estimular a hidratação oral dos pacientes. NÃO podemos, apenas, concordar\nque:","options":{"A":"Os anti-inflamatórios não esteroides (ibuprofeno, naproxeno, ácido acetilsalicílico) devem ser\nutilizados na fase aguda da doença, devido à possibilidade do diagnóstico ser na realidade dengue,\nbem como à possibilidade da coexistência das duas doenças.","B":"Os esteroides, igualmente, estão contraindicados na fase aguda, pelo risco do efeito rebote.","C":"A escolha das drogas deve ser feita após avaliação do paciente com aplicação de escalas de\ndor apropriadas para cada faixa etária e fase da doença.","D":"O ácido acetilsalicílico também é contraindicado na fase aguda, pelo risco de síndrome de Reye\ne de sangramento."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-181185","number":"181185","sourceNumber":"181185","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"De acordo com os critérios de Duke modificado para endocardite infecciosa, são\nconsiderados critérios maiores, EXCETO:","options":{"A":"Hemocultura positiva.","B":"Ecocardiograma positivo.","C":"Lesões de Janeway.","D":"Evidência de envolvimento endocárdico."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157606","number":"157606","sourceNumber":"157606","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Considere estas afirmações sobre a Meningoencefalite. I. A meningoencefalite é\ndisseminada de pessoa para pessoa.; II. A meningoencefalite tem período de incubação de 4 a 6\ndias.; III. A meningoencefalite é mais comum no inverno. Estão CORRETAS as afirmações contidas\nem:","options":{"A":"I e II, apenas.","B":"I e III, apenas.","C":"II e III, apenas.","D":"I, II e III."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157608","number":"157608","sourceNumber":"157608","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à meningite, assinale a alternativa INCORRETA:","options":{"A":"O estreptococo B e D, o bacilo gram negativo entérico e a Listeria monocytogenes são germes\nque comumente causam doenças em recém-nascidos.","B":"Crianças com menos de 5 anos têm mais alta taxa de infecção meningocócica, seguida de um\nsegundo pico entre 15 e 24 anos.","C":"Crianças a partir de 1 ano de idade e adultos entre 50 e 60 anos são os mais vulneráveis.","D":"O período de incubação é de 2 a 10 dias."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157660","number":"157660","sourceNumber":"157660","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Otite Externa Maligna (OEM) é uma infecção muito grave que acomete o canal\nauditivo externo e a base do crânio. Em nossa\natualidade se trata de uma infecção rara, mas tem\nalta morbidade e potencialmente fatal. Sobre essa situação clínica, indique a alternativa\nconsiderada INADEQUADA.","options":{"A":"Acomete principalmente pacientes idosos com DM e é causada por Pseudomonas aeruginosa.","B":"Isso, possivelmente, se deve a uma microangiopatia no canal auditivo.","C":"Isso, possivelmente, se deve a diminuição do pH no cerume de diabéticos.","D":"Suscetibilidade à otite externa maligna não tem sido correlacionada ao grau de intolerância à\nglicose."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157665","number":"157665","sourceNumber":"157665","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Otite Externa Maligna (OEM) é uma infecção grave que se relaciona com a DM,\nacomete o canal auditivo externo e a base do crânio, podendo apresentar importante\nmorbimortalidade. Diante de tal caso, aponte a alternativa CORRETA.","options":{"A":"A OEM geralmente não cursa com dor intensa, sendo responsiva às medicações tópicas usadas\nna otite externa aguda.","B":"Ao exame físico, o tecido de granulação é frequentemente visível na parte inferior do canal\nauditivo externo, na junção cartilagem-osso.","C":"Complicações do sistema nervoso central são muito comuns.","D":"Ocorrendo o avanço da infecção, mesmo ocorrendo osteomielite, a base do crânio é poupada."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157647","number":"157647","sourceNumber":"157647","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Jovem primigesta, 23 anos de idade, procurou o hospital com quadro de estrangúria e\nfebre. A obstetrícia pediu seu parecer clínico. Durante avaliação, você encontrou uma dor lombar e\npélvica, e solicitou USG de vias urinárias, que foi normal, e um exame de urina, que demonstrou\npiúria. Qual das medicações abaixo listadas, apesar de adequada ao tratamento de pielonefrite,\ndeve ser contraindicada por risco de lesão óssea fetal?","options":{"A":"Ceftriaxona.","B":"Ciprofloxacino.","C":"Cloranfenicol.","D":"Amicacina."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134737","number":"134737","sourceNumber":"134737","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Para tratamento de infecções em sistema nervoso central, apresenta importância, o\nconhecimento de antimicrobianos que seriam capazes de atingir concentração após passagem pela\nbarreira hematoencefálica. Qual dos abaixo, NÃO possui essa capacidade?","options":{"A":"Cefepime.","B":"Cefuroxima.","C":"Ceftazidime.","D":"Cefaclor."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-139741","number":"139741","sourceNumber":"139741","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual é o agente etiológico da Sífilis?","options":{"A":"Protossifiloma.","B":"Treponema pallidum.","C":"Herpes vírus.","D":"Haemophilus Ducreyi."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134771","number":"134771","sourceNumber":"134771","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Durante consulta ambulatorial, foi feita suspeita clínica de uma Infecção Urinária Baixa,\nprovavelmente uma Cistite não complicada em mulher jovem. Como não se tratava de quadro\ngrave, foi soliticitado colheita de urocultura, e, logo após, uso de antibiótico empírico. Ocorreu\nque a\npaciente se curou clinicamente da ITU, mas seu resultado de urocultura revelou que o antibiótico\nprescrito não tinha perfil adequado, portanto, a bactéria não foi sensível ao mesmo. Essa\nsituação pode ser explicada, assim, de maneira adequada, como:","options":{"A":"Erro laboratorial provavelmente.","B":"Má qualidade da amostra de urina.","C":"Excreção via urinária, assim maior concentração que a sérica avaliada pela cultura.","D":"Reagentes inadequados."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134708","number":"134708","sourceNumber":"134708","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O exame padrão-ouro para diagnóstico de ITU é:","options":{"A":"Ultrassonografia de rins e vias urinárias.","B":"Hemocultura.","C":"Urina tipo 1 colhida por sondagem vesical.","D":"Urinocultura."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-111857","number":"111857","sourceNumber":"111857","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Usuários de drogas injetáveis podem apresentar diversas complicações, das mais\ndiversas possíveis, entre elas a infecção e o aparecimento das ditas Vegetações nas Válvulas\nCardíacas. Qual das alternativas seguintes MELHOR caracteriza essa situação?","options":{"A":"Estreptococo.","B":"Estafilococo.","C":"Enterococo.","D":"Moraxela."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-111931","number":"111931","sourceNumber":"111931","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em uma Unidade Básica de Saúde, a equipe responsável pela vigilância\nepidemiológica recebeu uma notificação de um caso\nsuspeito de meningite bacteriana em uma\ncriança com dois anos, matriculada em uma creche da região. O procedimento CORRETO a ser\nrealizado, após a investigação inicial, é:","options":{"A":"se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia com rifampicina em\ncontatos íntimos no prazo de 48 h da exposição.","B":"se o agente isolado for Haemophilus influenzae não há necessidade de realização de\nquimioprofilaxia em contatos íntimos.","C":"se o agente isolado for Neisseria meningitidis realizar quimioprofilaxia em contatos com\nabordagem ampliada com o uso de ceftriaxone no prazo de 96 h da exposição.","D":"independentemente de o agente etiológico realizar quimioprofilaxia em contatos, com\nabordagem ampliada, com uso de ceftriaxone no prazo de 96 h da exposição."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-350892","number":"350892","sourceNumber":"350892","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem de 45 anos iniciou quadro de febre alta, cefaleia, dor retrorbitária, prostração e\nmialgia difusa, há 4 dias. Até 18 horas atrás, parecia estar começando a melhorar, entretanto, nas\núltimas 6 horas voltou a ter febre associada a petéquias difusas pelo corpo e epistaxe leve. Sinais\nvitais encontram-se normais. Neste contexto, qual a conduta mais adequada para o paciente?","options":{"A":"Prescrever soro de reidratação oral.","B":"Realizar expansão volêmica com cristaloide.","C":"Orientar conduta expectante e voltar à emergência se sinais de alarme.","D":"Solicitar exames laboratoriais, internar o paciente e iniciar hidratação venosa."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-350885","number":"350885","sourceNumber":"350885","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Menino, de 4 anos, levado à emergência apresentando petéquias em tronco, face,\nmembros inferiores, sonolência, fala desconexa,\nmucosas pálidas, taquicardia, tempo de\nenchimento capilar de 4 segundos e redução da diurese. Segundo sua mãe, os sintomas iniciaram\nhá 5 dias com febre (38°C), cefaleia (+++/4+), mialgia e ?manchas avermelhadas? que se iniciaram\nno tronco e se disseminaram para as extremidades acometendo até palma das mãos e a planta dos\npés. Exames coletados na emergência mostram Hematócrito: 45%, linfócitos: 4000/mm³ e\nPlaquetas: 53.000/mm³ . Pelos achados descritos mais provavelmente estamos diante de infecção\npor:","options":{"A":"Herpes simples com encefalite.","B":"Chikungunya com choque.","C":"Zika vírus com choque.","D":"Dengue com choque."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-321309","number":"321309","sourceNumber":"321309","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 70 anos, hipertensa e diabética, iniciou febre, mialgia difusa, poliartralgia,\ncefaleia e dor retrorbitária há 5 dias. No\nterceiro dia de sintomas, realizou pesquisa do antígeno\nNS1, que veio positiva, e apresentou melhora parcial do quadro. Procura atendimento em unidade\nde emergência hoje, entretanto, por conta de recrudescência da febre e aparecimento de rash\nmacular. Nega outros sintomas. Exame físico: FC 90bpm / FR 18irpm / PA 130x80mmHg / Tmax\n37,8C / SpO2 96% em ar ambiente. Qual a conduta mais adequada nessa situação?","options":{"A":"Mantê-la em observação com hidratação oral na emergência até resultado dos exames.","B":"Solicitar exames laboratoriais para seguimento ambulatorial e hidratação via oral.","C":"Admitir a paciente em Unidade de Terapia Intensiva e iniciar hidratação venosa.","D":"Internar a paciente em leito de enfermaria e hidratação venosa."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-292816","number":"292816","sourceNumber":"292816","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 50 anos, moradora de Fortaleza, sem comorbidades, procura pronto-socorro\nreferindo quadro iniciado há 5 dias de febre\nalta, cefaleia, mialgia e dor retro-orbitária. Embora a\nfebre tenha desaparecido após o terceiro dia de doença, desde esta manhã relata exantema difuso\ne pruriginoso, e dor abdominal mal definida, que não cede com analgésicos comuns. Ao exame,\nestado geral regular; peso: 75 kg; pele: exantema maculopapular difuso com ?ilhas\" de pele normal;\npressão arterial: deitada = 130 x 80 mmHg, sentada = 118 x 76 mmHg; prova do laço: positiva;\nabdome: semigloboso, flácido, moderadamente doloroso à palpação profunda em epigastro,\nmesogastro e hipocôndrio direito. Ruídos hidroaéreos presentes. Extremidades: boa perfusão\nperiférica, sem edemas. Considerando a principal hipótese diagnóstica para o caso, que conduta\nterapêutica imediata deve ser tomada?","options":{"A":"Soro fisiológico a 0,9% 750 ml, endovenoso, em 1 hora.","B":"Soro fisiológico a 0,9% 1.500 ml, endovenoso, em 20 minutos.","C":"Soro de reidratação oral 1.500 ml + líquidos diversos 3.000 ml, por via oral, em 24 horas.","D":"Soro glicosado a 5% 3.000 ml + soro fisiológico a 0,9% 1.500 ml, endovenoso, em 24 horas."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-292829","number":"292829","sourceNumber":"292829","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A fase crítica da infecção pelo vírus da dengue pode se seguir à fase febril, em alguns\npacientes, que podem evoluir para as formas graves. O aparecimento dos sinais de alarme deve\nser rotineiramente pesquisados nos casos suspeitos. Dentre os principais sinais de alarme,\ndestacam-se: dor abdominal intensa (referida ou à palpação) e contínua; vômitos persistentes;\nacúmulo de líquidos (ascite, derrame pleural, derrame pericárdico); hipotensão postural e/ou\nlipotimia; hepatomegalia > 2 cm abaixo do rebordo costal; sangramento de mucosa; letargia e/ou\nirritabilidade; aumento progressivo do hematócrito. O que traduzem esses sinais de alarme?","options":{"A":"Esses sinais podem traduzir o aumento da pneumonia causada pelo vírus, edema agudo de\npulmão e evolução para o agravamento clínico do paciente com derrame pleural.","B":"Esses sinais podem traduzir a instalação de insuficiência cardíaca e hipertensão arterial,\npermitindo a evolução para o agravamento clínico do paciente com o potencial de choque ou\nderrame pericárdico.","C":"Esses sinais podem traduzir o aumento da permeabilidade vascular acarretando hipertensão\narterial, o agravamento clínico do paciente para\no choque ou derrames cavitários pelo\nextravasamento plasmático.","D":"Esses sinais podem traduzir o aumento da permeabilidade vascular e evolução para o\nagravamento clínico do paciente, com o\npotencial de evoluir para o choque ou derrames cavitários\npelo extravasamento plasmático."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-259722","number":"259722","sourceNumber":"259722","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem de 40 anos, sem comorbidades, recebe diagnóstico de leishmaniose visceral e\né tratado com antimonial pentavalente com\nexcelente resposta clinicolaboratorial. Após oito meses\ndo tratamento inicial retorna com febre intermitente, astenia, anorexia e palidez. Ao exame\nabdominal, esplenomegalia discreta é percebida. Traz os seguintes exames: hemoglobina = 10,0\ng/dl; hematócrito = 30%; leucócitos = 4.500/mm³ (40% segmentados, 50% linfócitos, 10%\nmonócitos); plaquetas = 135.000/mm³; anti-rK39 reagente; anti-HIV não reagente. Diante do\nexposto, qual a conduta recomendada?","options":{"A":"Repetir anti-rK39.","B":"Solicitar mielograma.","C":"Iniciar anfotericina B lipossomal.","D":"Iniciar antimoniato de N-metil-glucamina."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-259729","number":"259729","sourceNumber":"259729","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança, 5 anos, é trazida ao posto de saúde com história de febre mensurada há 5\ndias, diarreia aquosa (cerca de 4 episódios ao dia), cefaleia e mialgia. A mãe procurou assistência\npor diminuição da diurese e dor abdominal difusa. Ao exame físico, apresentava irritabilidade,\ndesidratação, hepatomegalia dolorosa (cerca de 4 cm do rebordo costal direito), sem sinais de\nperitonite. Pulsos palpáveis. Paciente normotenso. Assinale a conduta inicial imediata mais\nadequada.","options":{"A":"Tentar transferência para Unidade de Referência para avaliar início de hidratação venosa e\ncoleta de exames laboratoriais na urgência.","B":"Iniciar imediatamente hidratação venosa 20 ml/kg . Tentar transferência para unidade de\nreferência. Coletar exames laboratoriais assim que possível.","C":"Orientar hidratação via oral em casa. Oferecer cerca de 1/3 na forma de soro de reidratação oral\n(SRO) e o restante através de oferta de sucos, água e chás. Reavaliar em 24 a 48 h.","D":"Manter paciente em observação no posto de saúde. Iniciar hidratação via oral, cerca de 50 a 100\nml por kg em 4 horas. Manter jejum durante administração SRO e reavaliar após."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-199659","number":"199659","sourceNumber":"199659","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Menina de 6 anos recebeu diagnóstico de dengue há 3 dias e retorna para reavaliação.\nIniciou quadro de febre há 5 dias, dores de\ncabeça, articulares e musculares, tendo recebido\norientação de repouso, boa hidratação e analgésico. Os pais referem que, embora a febre tenha\ndiminuído, a filha está mais sonolenta e prostrada, com dor abdominal contínua, intensa e vômitos.\nEm que grupo do fluxograma do Ministério da Saúde se encaixa esse caso?","options":{"A":"Grupo A ? dengue sem sinais de alarme, sem condição especial, sem risco social e sem\ncomorbidades. Acompanhamento ambulatorial.","B":"Grupo B ? dengue sem sinais de alarme, com condição especial ou com risco social e com\ncomorbidades. Acompanhamento em leito de observação até resultado de exames e reavaliação\nclínica.","C":"Grupo C ? sinais de alarme presentes e sinais de gravidade ausentes. Acompanhamento em\nleito de internação até estabilização.","D":"Grupo D ? dengue grave. Acompanhamento em leito de emergência."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-173027","number":"173027","sourceNumber":"173027","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 4 anos é referida ao ambulatório de pediatria por apresentar quadro de\nfebre intermitente e emagrecimento. Durante o\nexame físico, o médico constata\nhepatoesplenomegalia, com predomínio do baço. O hemograma do paciente exibiu pancitopenia.\nQual das opções apresenta o diagnóstico mais plausível para esse paciente?","options":{"A":"Anemia falciforme.","B":"Leishmaniose visceral.","C":"Mononucleose infecciosa.","D":"Lúpus eritematoso sistêmico."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-172946","number":"172946","sourceNumber":"172946","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 45 anos comparece à unidade de atenção primária à saúde, em Fortaleza,\ncom queixa de febre de 39ºC há 2 dias,\nassociada a cefaleia, exantema e artralgia intensa em\nmãos, joelhos e pés. A dor articular é bilateral e simétrica. Apresenta dificuldade de deambular e\nde\nsegurar objetos com as mãos. O exantema é maculopapular e acomete tronco e membros\ninferiores. Para avaliar melhor a dor articular, foi aplicada a escala analógica visual com\nresultado\nigual a 7 (de 0 a 10). Nega alergias a medicamentos e tem peso igual a 70 kg. Está em uso de\ndipirona 1 g de 6 em 6 horas. Para o manejo adequado da dor, qual medicamento deve ser\nassociado?","options":{"A":"Hidroxicloroquina.","B":"Ibuprofeno.","C":"Prednisona.","D":"Tramadol."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150891","number":"150891","sourceNumber":"150891","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 10 anos é trazida pela 3ª vez à Unidade de Pronto-Atendimento com\nprovável diagnóstico de dengue. Relata\naparecimento de náuseas, vômitos e cansaço. No exame\nfísico, o médico constata borda hepática a 4 cm do rebordo costal direito. Qual das condutas abaixo\nfaz parte das medidas preconizadas pelo Ministério da Saúde para o grupo classificatório em que\nela se encaixa?","options":{"A":"Permanecer em observação e hidratação oral, novos exames laboratoriais.","B":"Hidratação oral, novos exames laboratoriais e ultrassonografia abdominal.","C":"Reposição volêmica, permanência em leito de observação até estabilização (mínimo de 48\nhoras) e realização de exames laboratoriais e de imagem.","D":"Permanência em leito de Unidade de Tratamento Intensivo até estabilização, iniciar fase de\nexpansão rápida e colher novos exames\nlaboratoriais e de imagem."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150805","number":"150805","sourceNumber":"150805","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 6 anos comparece à Unidade Básica de Saúde por apresentar febre baixa\nseguida de exantema pruriginoso e dores articulares leves. À inspeção, apresenta os olhos\nvermelhos e irritados. Sua mãe acha que se trata de dengue porque várias pessoas do bairro \"já\npegaram\". Quais os sinais ou sintomas que facilitam o diagnóstico diferencial entre as arboviroses\nque ajudam nesse caso?","options":{"A":"Dengue: febre, em geral, baixa e prolongada, ausência de dores nas articulações e dores\n\nretro-orbitárias e musculares. Chikungunya: febre, em geral, baixa e de início imediato, dores leves\nnas articulações e pode estar presente intensa cefaleia. Zika: febre alta com calafrios, dores\nintensas nas articulações, vermelhidão nos olhos e ausência de exantema.","B":"Dengue: febre, em geral, alta e de início imediato, dores moderadas nas articulações e dores\nretro-orbitárias. Chikungunya: febre, em geral, alta e de início imediato, dores intensas nas\narticulações e pode estar presente exantema pruriginoso. Zika: febre baixa ou ausente, dores leves\nnas articulações, vermelhidão nos olhos e exantema pruriginoso.","C":"Dengue: febre, em geral, alta e de início tardio, ausência de dores nas articulações e dores\n\nretro-orbitárias. Chikungunya: febre, em geral, alta e de início imediato, dores leves nas\narticulações\ne não apresenta exantema pruriginoso. Zika:\nfebre baixa ou ausente, dores leves nas articulações,\nvermelhidão nos olhos e exantema pruriginoso.","D":"Dengue: febre, em geral, alta e fugaz, dores nas articulações, dores musculares e conjuntivite.\n\nChikungunya: febre, em geral, baixa e prolongada, dores intensas nas articulações e pode estar\npresente exantema pruriginoso. Zika: febre baixa ou ausente, dores leves nas articulações,\nvermelhidão nos olhos e exantema sem prurido."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150872","number":"150872","sourceNumber":"150872","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Gestante de 29 anos, parda, casada, procedente do bairro Aldeota, em Fortaleza,\niniciou o pré-natal com 8 semanas de\ngestação, logo que descobriu a gravidez. Na consulta de 20\nsemanas, relatou ter apresentado febre há 4 dias, acompanhada de manchas na pele com prurido,\ndor leve e edema nas articulações de quirodáctilos e pododáctilos. Ao realizar o exame clínico,\nestava consciente e orientada, temperatura axilar de 37 °C, pulso de 80 ppm e PA deitada de 110 x\n70 mmHg. Quais os procedimentos mais adequados para o seguimento inicial do caso?","options":{"A":"Solicitar sorologia para dengue, zika e chikungunya, notificar a vigilância epidemiológica\nmunicipal, após resultado dos exames.","B":"Solicitar sorologia para zika, dengue, chikungunya, USG obstétrica e encaminhar a gestante\npara pré-natal de alto risco na maternidade de\nreferência.","C":"Solicitar sorologia para zika no soro e na urina, USG morfológico em torno da 22 semana e\nnotificação de caso suspeito para a vigilância epidemiológica.","D":"Solicitar exames específicos para zika, dengue, chikungunya e STORCH e notificar o caso como\nsuspeito para vigilância epidemiológica municipal."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-102161","number":"102161","sourceNumber":"102161","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A sedimentoscopia urinária mostrada abaixo foi realizada em um paciente de 55 anos,\nestado geral regular, que apresentava, entre outros sintomas, febre e disúria. A conduta mais\nindicada e diagnóstico mais provável são: (VER IMAGEM)","options":{"A":"Solicitação da uroanálise e urinocultura, e tratar com sulfametoxazol + trimetoprima via oral\ndurante sete\n\ndias; cistite aguda complicada.","B":"Solicitação prévia da uroanálise e urinocultura é dispensável, e tratar com ciprofloxacino via\noral\ndurante trinta dias; prostatite aguda.","C":"Solicitação da uroanálise, urinocultura e hemocultura, e tratar com ciprofloxacino via oral\ndurante quatorze dias; pielonefrite aguda.","D":"Solicitação prévia de uroanálise e urinocultura é dispensável, e tratar com ceftriaxona\nendovenosa durante sete dias; pielonefrite aguda."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":["question_bank/media/medcurso/medcurso-infectologia-inf-3/102161.png"],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-81298","number":"81298","sourceNumber":"81298","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente feminina, 66 anos, em quimioterapia para leucemia mieloide aguda. No 10º dia\nde tratamento, evolui com febre, vômitos e dor lombar. Ao exame, encontra-se taquicárdica,\ntaquipneica, hipotensa e agitada. O sinal de Giordano é positivo à esquerda. O leucograma revela\n900 leucócitos/mm³ com 50% de neutrófilos. Após coleta de urinocultura, na condição de\nmonoterapia, o esquema terapêutico mais apropriado, dentre as opções abaixo, seria:","options":{"A":"Amicacina.","B":"Aztreonam.","C":"Ciprofloxacina.","D":"Piperacilina-tazobactam."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-65737","number":"65737","sourceNumber":"65737","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo masculino, 20 anos de idade, portador de insuficiência mitral, vem\napresentando febre (até 40°C) de longa duração. Ao exame físico, observa-se palidez (++/4+) e\npetéquias conjuntivais. A ausculta cardíaca revela ritmo regular, 2 tempos, bulhas normofonéticas e\nsopro sistólico (++/4+) em foco mitral. O abdome está flácido, indolor à palpação, sem\nvisceromegalias, espaço de Traube ocupado. O ecocardiograma mostra massa cardíaca oscilante\naderida ao folheto anterior da valva mitral compatível com vegetação. O diagnóstico de endocardite\nneste caso foi feito baseado em:","options":{"A":"Um critério maior + 3 critérios menores.","B":"Um critério maior + 4 critérios menores.","C":"Nenhum critério maior + 5 critérios menores.","D":"Nenhum critério maior + 3 critérios menores.","E":"Três critérios maiores + nenhum critério menor."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-65715","number":"65715","sourceNumber":"65715","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 12 anos, internada com quadro de edema, eritema e dor na região\nperiorbitária do olho esquerdo, refere que,\nnos últimos dias, de modo estranho, não consegue\nmovimentar o olho esquerdo, preferindo mantê-lo fechado, evitando com isso ver duas imagens.\nQuando examinado, o paciente encontra-se com as pupilas centradas, e a diplopia piora ao olhar\npara a direita ou para a esquerda; demonstra também deficiência na abdução do olho esquerdo.\nDiante do descrito, qual o diagnóstico clínico, a causa da complicação observada e a\nantibioticoterapia indicada?","options":{"A":"Celulite orbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-positivas.","B":"Celulite periorbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-negativas.","C":"Celulite periorbital; paralisia do III par craniano por extensão do processo; cobertura para\ncepas\nGram-positivas e Gram-negativas.","D":"Celulite orbital; paralisia do III par craniano por extensão do processo; cobertura para cepas\nGram-positivas, Gram-negativas e anaeróbias.","E":"Celulite orbital; paralisia do VI par craniano por extensão do processo; cobertura para cepas\nGram-positivas, Gram-negativas e anaeróbias."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-51172","number":"51172","sourceNumber":"51172","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Lactente é trazido ao Posto de Saúde por sua mãe, que relata o surgimento de lesões\nde pele na região do queixo e narinas, as\nquais se disseminam em pouco tempo para as mãos e\ntronco, com vermelhidão e pus. Refere que há 48 horas a criança vem apresentando febre e\n\"íngua\". Quais os agentes etiológicos e o tratamento deste caso?","options":{"A":"Candida albicans ? nistatina oral por 7 dias, compressas de permanganato de potássio a\n1:40.000 e pomada de nistatina nas lesões.","B":"Escherichia coli e Klebsiella pneumoniae ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de nistatina nas lesões.","C":"Escherichia coli e Staphylococcus aureus ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de nistatina ou miconazol nas lesões.","D":"Streptococcus do grupo A e Staphylococcus ? antibiótico oral por 7-10 dias, compressas de\npermanganato de potássio a 1:40.000 e pomada de neomicina, mupirocin ou ácido fusídico nas\nlesões."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-51293","number":"51293","sourceNumber":"51293","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 34 anos, trabalhador da construção civil, deu entrada na emergência com\nhistória de febre, calafrios, mialgia e cefaleia há aproximadamente 5 dias. Na admissão estava\nafebril, ictérico, hipotenso, cefaleico e apresentava hemoptise. Os exames mostravam ureia: 182\nmg/dl; creatinina: 3,1 mg/dl; potássio: 3,0 mEq/L; Hb: 12 g/dl; Ht: 38%; leucócitos: 10.200/mm³;\nplaquetas: 40.000/mm³; TGO: 62 UI/L; TGP: 56 UI/L; bilirrubina direta: 12 mg/dl. Qual a conduta\nmais adequada visando aumentar as chances de sobrevida desse paciente?","options":{"A":"Fazer expansão volêmica evitando sobrecarga hídrica, antibioticoterapia e iniciar hemodiálise\nprecoce.","B":"Fazer expansão com sobrecarga hídrica, iniciar antibioticoterapia e aguardar 48h para observar\nevolução da função antes de indicar hemodiálise.","C":"Iniciar rapidamente pulso de corticoide para hemorragia alveolar, reposição volêmica adequada\ne antibioticoterapia. Observar resposta antes de\nindicar hemodiálise.","D":"Fazer reposição volêmica, iniciar a dopamina (dose de 3 µg/kg/min) caso a hipotensão não\nresponda ao volume e antibioticoterapia. Observar resposta para indicar hemodiálise."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-141588","number":"141588","sourceNumber":"141588","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual das opções abaixo consiste em indicação de intervenção cirúrgica emergente (no\nmesmo dia) em pacientes com endocardite?","options":{"A":"Próteses instáveis.","B":"Endocardite fúngica.","C":"Perfuração de septo.","D":"Ruptura para o saco pericárdico."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-45377","number":"45377","sourceNumber":"45377","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A avaliação de um paciente com sinais de irritação meníngea resultou em punção\nliquórica com o seguinte resultado: celularidade\n= 80 céls (predominantemente linfócitos);\nproteínas = 110 mg/dl (normal < 60); pressão de abertura = 35 cmH2O (normal = 7-18); glicose =\n70 mg/dl. Qual a etiologia mais provável da meningite deste paciente?","options":{"A":"Fúngica.","B":"Viral.","C":"Neoplásica.","D":"Bacteriana.","E":"Tuberculosa."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-45383","number":"45383","sourceNumber":"45383","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Considerando-se as meningites bacterianas na infância, é CORRETO afirmar:","options":{"A":"Crianças em tratamento, com quadro clínico estável e evolução favorável, a persistência da\nfebre indica mau prognóstico.","B":"Em lactentes, os sinais de irritação meníngea podem ser pouco evidentes e, em geral, são mais\ntardios nessa faixa etária.","C":"A quimioprofilaxia deve ser realizada em profissionais de saúde e contactantes de crianças com\nmeningites meningocócica e pneumocócica.","D":"Ao exame do fundo de olho, detecta-se frequentemente papiledema decorrente da hipertensão\nintracraniana.","E":"A coleção subdural ocorre na metade das crianças com meningite e é mais frequente na\nmeningite meningocócica."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-37595","number":"37595","sourceNumber":"37595","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No tratamento de abscessos de partes moles, são indicações de uso de\nantibioticoterapia sistêmica, exceto:","options":{"A":"presença de febre, linfangite ou linfadenite.","B":"presença de múltiplos abscessos.","C":"em pacientes com diabetes.","D":"localização em face, couro cabeludo, região\ncervical, mãos, pés, genitais e/ou tronco."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-32509","number":"32509","sourceNumber":"32509","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um menino de 8 anos de idade, previamente hígido, apresenta uma história de três\nsemanas de febre de origem indeterminada,\nfadiga, perda de peso, mialgia e suores noturnos. Há 5\ndias, associou ao quadro clínico pequenos nódulos nas pontas dos dedos, sopro cardíaco,\npetéquias e esplenomegalia moderada. O diagnóstico mais provável é:","options":{"A":"Febre reumática.","B":"Leucemia aguda.","C":"Endocardite infecciosa.","D":"Tuberculose.","E":"Doença de Kawasaki."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-30893","number":"30893","sourceNumber":"30893","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente 82 anos, há 4 dias com cefaleia, febre e alterações do estado mental. No\nexame físico há discreta rigidez de nuca e\ndesidratação. O exame de bacterioscopia do liquor\nmostrou bastonetes gram-positivos. Qual das bactérias abaixo é o provável agente etiológico?","options":{"A":"Listeria monocytogenes.","B":"Staphylococcus aureus.","C":"Haemophilus influenzae.","D":"Neisseria meningitidis.","E":"Streptococcus pneumoniae."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-29445","number":"29445","sourceNumber":"29445","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação às infecções urinárias em crianças (ITU), marque a opção INCORRETA:","options":{"A":"Estão associadas à septicemia, com maior frequência, no período neonatal;","B":"Em mais de 90% dos casos a E.coli é o agente causador da infecção;","C":"A Cefalexina não está indicada para o tratamento da ITU em crianças menores de três anos;","D":"Em crianças que urinam sob comando, a coleta através do jato médio em recipiente esterilizado\né uma boa opção;"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-24383","number":"24383","sourceNumber":"24383","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Afonso, 18 anos, portador de cardiopatia congênita, necessita realizar a extração\ndentária dos terceiros molares (sisos). Seu\ndentista solicitou antibioticoprofilaxia pelo risco de\nendocardite infecciosa. No caso de Afonso, o esquema pode ter sido realizado à base de:","options":{"A":"Amoxicilina","B":"Sulfametoxazol + trimetoprim","C":"Gentamicina","D":"Amicacina"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-9054","number":"9054","sourceNumber":"9054","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 23 anos, usuária de cocaína IV, chega à emergência sonolenta,\ndesorientada, taquipneica, com febre alta, dor\npleurítica bilateral e tosse produtiva com\nexpectoração sanguino-purulenta há 3 dias. Qual dos seguintes diagnósticos pode justificar o\nquadro acima?","options":{"A":"Endocardite por S. aureus","B":"Pneumonia por Mycoplasma","C":"Pneumonia por fungos associada ao HIV","D":"Sepse estreptocócica"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-7290","number":"7290","sourceNumber":"7290","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 4 anos de idade, com diagnóstico de meningite por Hemophilus influenzae\nem tratamento com ceftriaxona na dose de 100\nmg/kg/dia EV. Após melhora inicial, no quarto dia\nde tratamento, passa a apresentar sonolência e crises convulsivas caracterizadas por abalos na\nmetade da face e membros superior e inferior direitos. O diagnóstico mais provável dessa situação\né:","options":{"A":"erro terapêutico.","B":"hidrocefalia.","C":"vasculite cerebral.","D":"flebite periférica.","E":"efusão subdural."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8880","number":"8880","sourceNumber":"8880","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente masculino, 18 anos, com história de 2 dias de febre alta, cefaleia intensa,\nassociada a sinais de irritação meníngea e\nliquor com 900 células, 90% de polimorfonucleares, 120\nmg% de proteínas e 32 mg% de glicose. Qual o agente etiológico mais provavelmente responsável\npor esse quadro?","options":{"A":"Haemophylus influenzae.","B":"Streptococcus pneumoniae.","C":"Mycobacterium tuberculosis.","D":"Cryptococcus neoformans.","E":"Staphylococcus aureus."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-9043","number":"9043","sourceNumber":"9043","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Liliana, 12 anos, apresentou um quadro súbito de febre, cefaleia intensa, vômitos e\nrigidez de nuca. Na emergência do IJF, a pediatra solicitou exame do LCR (Líquido\n\nCéfalo-Raquidiano) e iniciou tratamento para meningite meningocócica. Qual desses achados\npoderia ter sido encontrado que sugerisse essa etiologia?","options":{"A":"LCR límpido e cristalino como água de rocha.","B":"Bacterioscopia evidenciando diplococos Gram-negativos.","C":"Aumento do número de leucócitos com predomínio de linfócitos.","D":"Proteínas diminuídas e elevação da glicose."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-13400","number":"13400","sourceNumber":"13400","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um universitário de 21 anos foi encontrado pouco responsivo em seu quarto. Relato de\ncefaleia há 4 dias refratária a analgésicos e anti-inflamatórios. Levado para a emergência, ao\nexame clínico e físico apresentou os seguintes sinais vitais: temperatura de 39,50ºC PA= 145x100\nmmHg; frequência cardíaca de 112/min e frequência respiratória de 18/min. Respondia\nparcialmente aos comandos verbais. Presença de rigidez de nuca, hiper-reflexia simétrica e\nresposta plantar flexora.\n\nAssinale a alternativa CORRETA com relação a etiologia:","options":{"A":"Provável meningite adquirida na comunidade e neste grupo etário por Neisseria meningitidis e herp\nes simples.","B":"Provável abscesso cerebral e ou empiema subdural pelo nível de consciência alterado.","C":"Provável ruptura de aneurisma com hemorragia subaracnoidea.","D":"Nesta faixa etária a intoxicação por drogas e as encefalopatias tóxico-\nmetabólicas são mais prováveis.","E":"A hipótese de meningite carcinomatosa é provável nesta faixa etária."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-6939","number":"6939","sourceNumber":"6939","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Lactente, 10 meses, previamente hígido foi internado com meningite. Liquor: diplococo\ngram-positivo. É mais provável que na cultura do liquor seja identificado:","options":{"A":"Neisseria meningitidis.","B":"Haemophilus influenzae do tipo b.","C":"Listeria monocytogenes.","D":"Streptococcus pneumoniae.","E":"Escherichia coli."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-6981","number":"6981","sourceNumber":"6981","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Você se depara no trabalho de rotina de sua equipe com um caso suspeito de doença\nmeningocócica em um bairro do Município de Fortaleza durante uma avaliação clínica. Em relação\nàs condutas a serem adotadas frente a essa situação, pode-se afirmar que:","options":{"A":"Todos os membros da equipe de saúde que prestaram algum tipo de atendimento ao caso com\nmeningite devem realizar profilaxia com rifampicina durante dois dias.","B":"Deve-se indicar vacinação sorogrupo-específica contra a Neisseria meningitidis (sorogrupos A e","C":"O tratamento com penicilina cristalina deve ser realizado durante 7 a 10 dias e iniciado após\nconfirmação laboratorial por avaliação liquórica (exame direto e cultura).","D":"A transmissão depende de contato pessoa a pessoa por meio de gotículas das secreções da\nnasofaringe, sendo que o principal transmissor é o portador assintomático.","E":"O período de transmissibilidade dura enquanto houver o agente na nasofaringe, sendo que em\ngeral após 72 horas do tratamento específico, o meningococo já desaparece da orofaringe."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-6990","number":"6990","sourceNumber":"6990","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O cirurgião que trabalha como referência de sua equipe de saúde da família te procura\nbuscando informações sobre a utilização de\nantibiótico profilático para procedimento periodontal e\nde limpeza profilática de dentes ou implantes, uma vez que prevê, pelas condições do paciente,\nque ocorrerá sangramento. Em relação às questões colocadas por ele, pode-se dizer que:","options":{"A":"As condições cardíacas em que a profilaxia da endocardite bacteriana não está indicada\nincluem: prolapso da valva mitral, miocardite\nhipertrófica e cirurgia de revascularização miocárdica\nprévia.","B":"Para as pessoas alérgicas à penicilina que têm a indicação de profilaxia está indicado o uso de\nciprofloxacina ou de claritromicina 1 hora antes do procedimento a ser realizado.","C":"O esquema padrão para profilaxia é baseado no uso de amoxilina 1 hora antes do\nprocedimento, mantida até 48 horas após.","D":"Presença de valva protética e episódio prévio de endocardite infecciosa representam condições\ncardíacas em que o uso da profilaxia para endocardite bacteriana está indicado.","E":"Tratamento endodôntico intracanal, odontologia restauradora e colocação de próteses\nremovíveis representam outros procedimentos dentários\nem que a profilaxia da endocardite\ninfecciosa é indicada."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-365636","number":"365636","sourceNumber":"365636","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 23 anos de idade, sem comorbidades, residente em área de alta\nincidência de arboviroses, procurou o\npronto-socorro com queixa de febre com calafrios há três\ndias, associada a poliartralgia importante e cefaleia. Ao exame físico, apresentou FC = 102 bpm,\nPA = 123 mmHg x 85 mmHg, FR = 17 irpm, SatO2 = 97% em ar ambiente, temperatura axilar = 39\n\n°C e tempo de enchimento capilar = 1,5 segundo. Foram realizadas sorologias com diagnóstico de\nChikungunya. Acerca desse caso, assinale a alternativa que apresenta o manejo indicado.","options":{"A":"Internação para monitorização e tratamento antiviral","B":"Uso de oseltamivir domiciliar e recomendação acerca de sinais de alarme","C":"Internação para tratamento sintomático e realização de exames de imagem","D":"Prescrição de sintomáticos para uso domiciliar e recomendações relacionadas aos sinais de\nalarme"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-365658","number":"365658","sourceNumber":"365658","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma paciente de 57 anos de idade, com miocardiopatia chagásica, insuficiência\ncardíaca de fração de ejeção reduzida em\nseguimento com cardiologia, procurou o pronto-socorro\nqueixando-se de febre, mialgia e dor retro-orbitária há três dias. Foi realizada sorologia para\ndengue com NSI positivo. Ao exame físico, mostrou-se sem alterações de sinais vitais, com prova\ndo laço negativa. Com base nesse caso clínico, é correto afirmar que se trata de um caso de\ndengue do grupo","options":{"A":"A.","B":"B.","C":"C.","D":"D."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-349703","number":"349703","sourceNumber":"349703","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um jovem de 25 anos, apresentou-se ao pronto-socorro com febre, mialgia, artralgia e\nrash com lesões maculopapulares. Refere que os sintomas começaram há 48h e que esteve em\nregião de mata virgem no norte de Minas Gerais na semana que antecedeu o início dos sintomas,\nnão tendo observado carrapatos em seu corpo nesse período de viagem. O jovem está vacinado\nadequadamente para febre amarela. Ao exame clínico, apresenta dados vitais normais e não\napresenta sinais sugestivos de gravidade. A médica responsável pelo atendimento preocupou-se\ncom a possibilidade de febre maculosa. Considerando essa possibilidade, qual seria a conduta\nmais adequada da profissional diante do aspecto clínico e considerando a notificação da febre\nmaculosa como agravo?","options":{"A":"Solicitar sorologias, prescrever sintomáticos e notificar o município, pois trata-se de doença de\nnotificação compulsória.","B":"Prescrever doxiciclina empírica e notificar o município, a secretaria estadual e o ministério da\nsaúde, pois trata-se de doença de notificação compulsória.","C":"Solicitar sorologias, prescrever sintomáticos e notificar o município, a secretaria estadual e o\nministério da saúde, pois trata-se de doença de notificação compulsória.","D":"Prescrever doxiciclina empírica e notificar o município, pois trata-se de doença de notificação\ncompulsória.","E":"Prescrever doxiciclina empírica e notificar o município e a secretaria estadual, pois trata-se de\ndoença de notificação compulsória."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-322210","number":"322210","sourceNumber":"322210","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Jovem de 22 anos apresenta quadro de dores no corpo, febre alta e astenia há 3 dias e\nseu exame confirma o diagnóstico de dengue. O\nmédico da UBS, mantendo uma boa comunicação\ncom o paciente, deve orientá-lo sobre sinais de alerta para dengue hemorrágica. Assinale a\nalternativa que contempla tais sinais.","options":{"A":"Cefaleia, prostração e exantema.","B":"Contagem de plaquetas > 150.000, cefaleia e mialgia.","C":"Mialgia, febre alta e \"\"rash\"\" cutâneo.","D":"Elevação de pressão arterial, dor retro-orbital e náuseas.","E":"Dor abdominal, hipotensão postural e letargia."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-262440","number":"262440","sourceNumber":"262440","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ndiagnóstico da paciente é cistite não complicada, e os antibióticos recomendados para cistite não\ncomplicada em mulheres são fosfomicina trometamol (3 g por via oral, em dose única) e\nnitrofurantoína (100 mg por via oral, a cada seis horas, por cinco dias). Essas drogas têm\nmecanismos de ação únicos e baixas taxas de resistência. Também apresentam altas\nconcentrações urinárias e são ativos contra bactérias produtoras de betalacmase de espectro\nestendido (ESBL).","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-262441","number":"262441","sourceNumber":"262441","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\npadrão-ouro para o diagnóstico de infecção do trato urinário (ITU) é uma cultura de urina positiva,\napesar de, no caso da paciente, não ser indicado coleta de material para cultura. A cultura de urina\ne o teste de sensibilidade aos antimicrobianos devem ser realizados em gestantes, mulheres com\nsuspeita de pielonefrite aguda e em infecções recorrentes, em razão do maior risco de resistência\nbacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-262442","number":"262442","sourceNumber":"262442","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. A\nITU recorrente é definida como a repetição de pelo menos três ITUs em seis meses. Em cada\nepisódio, o paciente deve apresentar sintomas agudos de início e bacteriúria ? 10 2 UFC/mL no\nexame de urina (EAS).","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-262443","number":"262443","sourceNumber":"262443","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Certa paciente de 18 anos de idade, acompanhada pela irmã, deu entrada no\nambulatório para consulta médica com queixa\nde disúria, polaciúria e nictúria. Nega febre e dor\nlombar. Nega episódios anteriores e corrimento vaginal. Tem vida sexual ativa e usa DIU de cobre.\nAo exame físico, mostrou-se em BEG, corada, hidratada, anictérica, acianótica e orientada, com\nabdome plano, flácido, mas doroloso na região suprapúbica e com ruídos hidroaéreos (RHA)\npresentes. Observaram-se AR = MVF sem ruídos adventícios; ACV = RCR 2T BNF sem sopros; PA\n\n= 120 mmHg x 80 mmHg; FC = 90 bpm; FR = 18 irpm; e T = 37,1 °C. A irmã da paciente, então,\naproveitou a consulta para mostrar ao\nmédico alguns exames de rotina que ela tinha feito, pois\nestava preocupada por estar com infecção na urina. Apresentava-se totalmente assintomática, e o\nexame físico dela era normal. Ela não estava gestante e já teve infecção de urina há seis meses,\nquando foi tratada com antimicrobianos. O exame alterado era uma urocultura com Escherichia coli\nresistente a sulfas, ciprofloxacino, cefalosporina de primeira, segunda e quarta geração e sensível\na\nnitrofurantoína, cefaloporina de terceira geração, carbapenêmicos e aminoglicosídeos. Acerca\ndesse caso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ndiagnóstico da irmã da paciente é de bacteriúria assintomática e não deve ser indicado tratamento\nantimicrobiano para ela. Atualmente, a indicação de tratamento de bacteriúria assintomática é\nconsenso apenas em duas situações: no caso de gestantes e antes de procedimento urológico\ninvasivo.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-284357","number":"284357","sourceNumber":"284357","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. Ao se comparar a frequência das características clínicas e laboratoriais, constata-se que\na\nchikungunya apresenta quadro de febre, artralgia e linfopenia, enquanto a dengue apresenta\nmialgia, leucopenia e trombocitopenia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-284359","number":"284359","sourceNumber":"284359","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. As medidas de prevenção da chikungunya devem ser medidas de proteção contra o vetor,\nmesmo para as pessoas que já estejam infectadas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-284360","number":"284360","sourceNumber":"284360","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à prevenção, à epidemiologia e à história natural das doenças, julgue o item\na seguir. Na leishmaniose visceral, títulos variáveis dos exames sorológicos podem persistir\npositivos por longo período, devendo ser instituída a terapêutica somente na presença de\nmanifestações clínicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-255759","number":"255759","sourceNumber":"255759","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Determinada primigesta de 20 anos de idade, sem parceiros sexuais fixos, com oito\nepisódios anuais de infecção urinária do trato inferior, buscou atendimento após um período de\ntempo, depois de sofrer estupro. Na consulta, refere desejo de abortar. Além disso, a paciente\napresenta lupus eritematoso sistêmico, com anti-RO positivo. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, julgue o item a seguir. No caso de infecções urinárias de\nrepetição, conforme a quantidade, deve-se realizar profilaxia, além de orientações específicas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-214342","number":"214342","sourceNumber":"214342","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 58 anos de idade, negro, chega à emergência levado pela esposa por\nestar sonolento, queixando-se de cefaleia de\nforte intensidade, fadiga e episódios de náuseas\nseguidos de vômito de forte intensidade. A esposa relata que os sintomas se iniciaram no dia e vêm\napresentando piora progressiva. Nega queixas de dor torácica e (ou) precordial, e também nega\nqueixas álgicas abdominais. O paciente refere quadro prévio de hipertensão arterial e está em uso\nde anti-hipertensivos. A esposa relata que ele se queixa de episódios frequentes de cefaleia no\núltimo ano e que tem estado \"muito estranho\" nos últimos três meses, apresentando ações\ninconsequentes até nas pequenas decisões diárias. Ao exame, apresenta-se em estado geral\nregular, acordado e conversando, porém com aspecto sonolento, ventilando espontaneamente em\nar ambiente. Apresenta ausculta cardíaca e pulmonar sem particularidades. Sinais vitais: FC = 58\nbpm; FR = 22 irpm; PA = 190 mmHg x 125 mmHg; SatO? = 97%; e temperatura axilar (Tax) = 38,6\n\n°C. Acerca desse caso clínico e com base nos conhecimentos médicos correlatos, julgue o item a\nseguir. Uma punção liquórica com hipoglicorraquia, hiperproteinorraquia e alta celulariedade com\npredomínio de neutrófilos falaria a favor de uma meningite de origem bacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-179170","number":"179170","sourceNumber":"179170","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nos exames laboratoriais inespecíficos da febre hemorrágica da dengue, observa-se","options":{"A":"aumento importante dos testes de função hepática.","B":"linfopenia com atipia linfocitária como um achado comum.","C":"anemia devido ao choque.","D":"aumento da albumina no sangue.","E":"hemoconcentração devido a aumento do hematócrito."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-179194","number":"179194","sourceNumber":"179194","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A doença febril aguda de curta duração (no máximo doze dias) e gravidade variável,\nque se apresenta como infecção subclínica\ne(ou) leve, ou até uma forma grave e fatal, cujo quadro\ntípico tem evolução bifásica (período de infecção e de intoxicação), com início abrupto, febre alta\ne\npulso lento em relação à temperatura, calafrios, cefaleia intensa, mialgias, prostração, náuseas e\nvômitos, durante cerca de três dias, após os quais se observa remissão da febre e melhora dos\nsintomas, o que pode durar algumas horas ou, no máximo, dois dias, sendo que o caso pode\nevoluir para cura ou para a forma grave (período de intoxicação), caracterizada por aumento da\nfebre, diarreia, reaparecimento de vômitos com aspecto de borra de café, instalação de\ninsuficiência hepática e renal, surgindo também icterícia, manifestações hemorrágicas\n(hematêmese, melena, epistaxe, hematúria, sangramento vestibular e da cavidade oral, entre\noutras), oliguria, albuminuria e prostração intensa, além de comprometimento do sensório, que se\nexpressa mediante obnubilação mental e torpor com evolução para coma, é a","options":{"A":"dengue grave.","B":"febre amarela.","C":"malária.","D":"leptospirose.","E":"hepatite fulminante."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-131852","number":"131852","sourceNumber":"131852","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Menino de dois anos de idade, residente em área rural na Bahia, é levado ao pronto\natendimento com queixa de febre há duas semanas, palidez, hipoatividade e aumento de volume\nabdominal. Ao exame inicial, apresenta-se com palidez cutâneo-mucosa, hepatoesplenomegalia,\nlinfadenopatia cervical e aspecto emagrecido. Nos exames laboratoriais, foram observados:\nanemia; leucopenia com predomínio de células linfomonocitárias; trombocitopenia; VHS = 100\nmm/1h e inversão da relação albumina/globulina. Quanto ao diagnóstico e ao tratamento de\nleishmaniose sistêmica (calazar), assinale a alternativa CORRETA:","options":{"A":"A intradermorreação de Montenegro é sempre positiva durante o período de estado da doença.","B":"Os exames sorológicos Imunofluorescência Indireta (IFI) e ensaio imunoenzimático (ELISA) são\ninvariavelmente reativos e a Intradermorreação de Montenegro (IDRM) negativa, quando\nconsiderado quadro agudo da doença.","C":"O aspirado de medula óssea e do baço geralmente mostram presença de formas promastigotas\ndo parasita.","D":"A droga de escolha para o tratamento é a N-metil-glucamina, na dose de 20 mg/kg/dia por\naproximadamente 60 dias.","E":"A anfotericina B e as respectivas formas lipossomais podem ser utilizadas como tratamento\nalternativo e devem ser administradas, alternadamente, por 60 dias."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-134969","number":"134969","sourceNumber":"134969","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Considerando que uma paciente de vinte anos de idade tenha procurado um\nambulatório de clínica médica para avaliar tratamento antimicrobiano realizado para quadro de\ninfecção do trato urinário, que se encerrou há quarenta e oito horas, julgue o item seguinte. A\nrealização de cultura de urina da paciente, nesse caso, deve ser solicitada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-88647","number":"88647","sourceNumber":"88647","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Acerca de doenças crônicas, julgue o item subsequente. As complicações\nintracranianas mais comuns da otite média crônica são meningite e abscesso cerebral.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-82088","number":"82088","sourceNumber":"82088","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Acerca do uso terapêutico e profilático de antibiótico em pediatria, julgue o item\nsubsequente. A profilaxia com antibióticos está indicada em contatos familiares de crianças com\nmeningite por hemófilo e por meningococo.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-64644","number":"64644","sourceNumber":"64644","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente com 15 anos de idade recebeu atendimento médico em unidade de\nemergência devido à cefaleia intensa,\nassociada à febre que se iniciou há 2 dias. Durante exame\nfísico, foram identificados sinais meníngeos, sem sinais focais. Foi realizada punção para avaliação\ndo liquor, que evidenciou aspecto claro, com pleocitose, predomínio de polimorfonucleares,\nhiperproteinorraquia, de glicose diminuída. Com base nas informações acima, assinale a alternativa\nque apresenta o provável agente etiológico da meningite:","options":{"A":"Vírus.","B":"Fungo.","C":"Bactéria.","D":"Tuberculose.","E":"Doença de depósito."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-45762","number":"45762","sourceNumber":"45762","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma criança de quatro anos é levada ao pronto-socorro por apresentar febre alta e\nvômitos há 12 horas. O exame físico revela criança irritada ao manuseio, febril (tax.: 39,8°C),\nlevemente desidratada e com rigidez de nuca. Feita punção lombar, observaram-se os seguintes\nresultados: 600 células (95% polimorfonucleares), proteína (55 mg/dl) e glicose (70 mg/dl). A\nrespeito desse caso, assinale a alternativa CORRETA.","options":{"A":"A introdução das vacinas conjugadas contra Haemophylus influenzae B e pneumococo não\ninterferiram na incidência da doença por esses germes.","B":"A quimioprofilaxia dos contactantes está indicada somente na suspeita de meningococo.","C":"Há indicação de se prescrever anticonvulsivante profilático.","D":"O tratamento de escolha nesse caso é a prescrição de ceftriaxona, na dosagem adequada, de\n24/24 horas.","E":"É rotina repetir a punção lombar após 24 horas para avaliar a eficácia do tratamento."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-32179","number":"32179","sourceNumber":"32179","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 65 anos de idade foi atendido no pronto-socorro, história de início\nabrupto de febre havia 48 horas, evoluindo com\ncefaleia holocraniana e vômitos. No exame físico,\nencontrava-se com nível de consciência rebaixado e apresentava rigidez de nuca. A TC de crânio\nera normal. A melhor conduta, nesse caso, é:","options":{"A":"iniciar ampicilina e dexametasona imediatamente.","B":"realizar punção lombar e iniciar ceftriaxone com ampicilina.","C":"colher hemoculturas e iniciar ceftriaxone.","D":"iniciar ceftriaxone imediatamente.","E":"realizar punção lombar e aguardar resultado do exame do liquor para iniciar o tratamento."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-27539","number":"27539","sourceNumber":"27539","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O agente etiológico mais comum na infecção urinária da criança é:","options":{"A":"Enterobactéria.","B":"Klebsiella","C":"Serratia.","D":"Staphylococcus saprophyticus.","E":"Pseudomonas."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-307110","number":"307110","sourceNumber":"307110","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Acerca da malária na infância, assinale a alternativa correta. Alternativas:","options":{"A":"Consiste em doença parasitária, causada por protozoários, com transmissão pelo mosquito\nCulex.","B":"Deve-se fazer diagnóstico diferencial com dengue clássica e febre amarela.","C":"O Plasmodium falciparum é o mais prevalente e cursa com casos de menor gravidade.","D":"O quadro clínico da malária independe da espécie do parasito ou da sua quantidade circulante\nno sangue.","E":"O exame da gota espessa pode ajudar no diagnóstico, mas não confirma a doença."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-273355","number":"273355","sourceNumber":"273355","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Vinte participantes recentes de uma comitiva norte-americana no Brasil procuram o\ndepartamento de emergência com queixa de falta de ar, febre e mal-estar. Radiografias de tórax\nmostram alargamento do mediastino em vários desses pacientes, alertando para o risco de antraz\npor inalação como resultado de um ataque bioterrorista. Os antibióticos são iniciados e os órgãos\nresponsáveis são notificados. Qual forma de isolamento deve ser instituída para esses pacientes no\nhospital?","options":{"A":"Aerosol","B":"Contato","C":"Gotículas","D":"Nenhum tipo de isolamento"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-263384","number":"263384","sourceNumber":"263384","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma pré-escolar com 4 anos de idade é atendida no pronto-socorro com história de\nfebre alta (40 °C) há 3 dias, indisposição\ne dores no corpo, vômitos e diarréia. No momento,\nqueixa-se de dor abdominal intensa e contínua. Em seu exame físico, os resultados foram os\nseguintes: FC = 120 bpm, FR = 25 irpm, temperatura axilar = 37,5 °C, mucosas úmidas, coradas,\nanictéricas; ausculta cardíaca e respiratória normais, abdome levemente distendido, doloroso\ndifusamente à palpação, sem sinais de irritação peritoneal, fígado palpável a 3 cm do rebordo\ncostal direito. Há petéquias esparsas e exantema máculo-papular em face, tronco, membros\nsuperiores e inferiores, incluindo palmas das mãos. Suas extremidades estão aquecidas e bem\nperfundidas. Foi realizado hemograma que apresentou os seguintes valores: Ht = 45 % (valor de\nreferência: 37 a 40 %); Hb = 15,2 g/dL (valor de referência: 12,6 ± 1,5 g/dL), leucócitos totais = 3\n500/mm³ (valor de referência: 5 000 a 12 000/mm³, bastões = 2 %, segmentados = 50 %, linfócitos\n\n= 30 %, monócitos = 10 %, eosinófilos = 8 %, plaquetas = 50 000/mm³ (valor de referência: 150 000\na 450 000/mm³). Quais são, respectivamente,\no diagnóstico e a conduta médica inicial adequados?","options":{"A":"Chikungunya; observação e a hidratação parenteral com soro fisiológico 0,9 %.","B":"Zika; internação hospitalar e hidratação parenteral com soro fisiológico 0,9 %.","C":"Dengue grupo B; observação e hidratação oral com a reavaliação clínico-laboratorial.","D":"Dengue grupo C; internação hospitalar e hidratação parenteral com soro fisiológico 0,9 %."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-291518","number":"291518","sourceNumber":"291518","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Numa Unidade Básica de Saúde, localizada em cidade de grande porte, são atendidos,\nno intervalo de 2 semanas, 3 casos de\nleptospirose em trabalhadores de limpeza e desentupimento\nde esgotos. No que se refere à vigilância ambiental, são ações previstas pelo Ministério da Saúde\ndurante a investigação dos casos e após identificação do local provável de infecção","options":{"A":"antirratização; desratização; e informação, educação e comunicação em saúde.","B":"desratização; mutirão de limpeza; controle de comunicantes.","C":"informação, educação e comunicação em saúde; busca ativa de casos; vacinação de bloqueio.","D":"drenagem de coleções hídricas; sorologia nos comunicantes; quimioprofilaxia."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-291530","number":"291530","sourceNumber":"291530","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um escolar de 7 anos de idade, de sexo masculino, é admitido no pronto atendimento\ncom queixa de febre há 5 dias, acompanhada de\ncefaleia, dor retro-orbital, mialgia, prostração e\nanorexia. Hoje, houve aparecimento de exantema maculopapular pruriginoso por todo corpo. Foi\nrealizada Prova do Laço com presença de 15 petéquias no local examinado. Pesquisa do antígeno\nNS1 com resultado reagente. Com base no quadro apresentado, esse paciente apresenta dengue\ncom qual classificação?","options":{"A":"Grupo A: acompanhar ambulatorialmente com orientação de reidratação oral e sintomáticos.","B":"Grupo A: solicitar hemograma e orientar retorno em 24 horas para checagem do resultado.","C":"Grupo B: solicitar hemograma e manter em observação até obtenção do resultado do exame.","D":"Grupo B: solicitar hemograma e manter em leito de internação por pelo menos 48 horas."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-244471","number":"244471","sourceNumber":"244471","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 31 anos de idade, cuja profissão é pedreiro, procurou o pronto-socorro\ncom história de febre com calafrios, cefaleia\nholocraniana associada a náusea e mialgias difusas\ncom evolução de três dias. Nas últimas 24 horas, alega diminuição do volume urinário e urina\nescura, com início de tosse produtiva com escarro hemoptoico. Refere contato com água de\nenchente há 15 dias do início do quadro. Ao exame físico, constatam-se FC = 119 bpm, TAX = 38,5\nºC. Está ictérico, com hiperemia conjuntival, ausculta pulmonar com crepitações finas em bases\npulmonares, avaliação abdominal sem evidências de hepatoesplenomegalia, Murphy negativo, RHA\ndiminuído difusamente, Blumberg negativo, artralgias dos quadris, joelhos e tornozelos, mas sem\nderrames. Exames laboratoriais demonstram leucócitos = 18.000/mm3 (VR = 4.000-12.000) com\npredominância de neutrófilos (83%), contagem de plaquetas = 42.000/mm3 (VR = 140-450.000), Na\n\n= 132 mEq/L(VR = 135-154), K = 3,0 mEq/L (VR = 3,4-4,5), acidose respiratória, alcalose\nmetabólica e ânion amplo acidose de gap,\ncreatinina = 4,4 mg/dL (VR = 0,8-1,5), CPK = 1162\nUl/mL. (VR = 20-100), TGP = 239 mEq/L (VR = 20-32), TGO = 210 (VR = 24-42) mEq/L, bilirrubina\n\ntotal = 13,0 mEq/L com bilirrubina direta = 9,9 mEq/L. A tomografia computadorizada (TC) do tórax\nrevelou espessamento peribrônquico difuso bilateral e consolidação com extensas opacidades\nnodulares difusas. A ultrassonografia abdominal foi realizada e não demonstrou inflamação da\nvesícula biliar, dilatação do ducto biliar comum ou evidência de cálculos biliares. No que se\nrefere a\nesse caso clínico e aos conhecimentos médicos relacionados à leptospirose, assinale a alternativa\ncorreta.","options":{"A":"A hemocultura é um método diagnóstico com sensibilidade em torno de 90% para o isolamento\ndo organismo, sendo indicado coleta antes do início\ndo tratamento antibiótico para o paciente.","B":"A síndrome de Jarisch-Herxheimer pode ocorrerem determinadas formas graves da leptospirose,\ne é caracterizada clinicamente por\ninsuficiência renal e hemorragia alveolar difusa.","C":"A lesão pulmonar do paciente, induzida por êmbolos sépticos, geralmente se apresenta com\nhemorragia, e tem sido relacionada à ativação do receptor toll-like (TLR) das lipoproteínas de\nleptospira.","D":"A insuficiência renal aguda do paciente deve-se a desidratação e à rabdomiólise induzida\nespiroqueta com risco de evolução para fasceíte necrotizante.","E":"A hiponatremia se deve a uma proteína da membrana externa de leptospira, que inibe a\natividade de cotransportador Na + -K + -Cl- no\nramo ascendente da alça de Henle, resultando em\ndistúrbio do NA e potássio."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-230571","number":"230571","sourceNumber":"230571","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação às características clínicas das arboviroses, assinale a alternativa\nCORRETA:","options":{"A":"A febre aparece em cerca de 90% dos casos na infecção pelo Zika Vírus.","B":"A mialgia é mais frequente no Zika Vírus do que na dengue.","C":"O exantema é um sinal clínico de alta prevalência entre as arboviroses.","D":"A cefaleia é mais frequente na doença de chikungunya."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-227452","number":"227452","sourceNumber":"227452","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação às demandas de saúde na atenção primária à saúde (APS), relacionadas\nàs doenças infecciosas e transmissíveis, julgue\no item que se segue. Situação hipotética: Homem\nde cinquenta anos de idade compareceu a UBS com quadro de febre, mialgia, artralgia, mal-estar\ngeral, sangramento de mucosas e hipotensão postural. Devido a esses sintomas, estava ausente\ndo trabalho havia dois dias. Assertiva: De acordo com o MFC, o quadro desse paciente deve ser\nclassificado como dengue grupo B, haja vista a ausência de sinais de alarme, e o caso deve ser\nnotificado à secretaria de saúde local. O paciente deve permanecer em observação até o resultado\ndo hemograma, com prescrição de hidratação e analgesia, conforme evolução do quadro.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183915","number":"183915","sourceNumber":"183915","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação ao tratamento das doenças infecciosas e parasitárias, julgue o item que se\nsegue. Situação hipotética: Um paciente de trinta e um anos de idade foi atendido no hospital com\no seguinte quadro clínico: diagnóstico clínico e laboratorial de leishmaniose visceral,\nimunocompetente, com edema de membros inferiores e icterícia - clínica e laboratorial. Os exames\nmostraram níveis séricos de TGO 30 U/L, leucócitos totais iguais a 5.000 células/mm³, o número de\nplaquetas por mm³ foi de 95.000, níveis séricos de ureia e creatinina normais e eletrocardiograma\ndentro da normalidade para a sua idade. Assertiva: O tratamento de primeira escolha recomendado\npelo Ministério da Saúde (Brasil) para esse paciente hipotético é a anfotericina B lipossomal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-175108","number":"175108","sourceNumber":"175108","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Segundo o Ministério Da Saúde em: Dengue Diagnóstico e Manejo Clínico de 2016,\nsão sinais de alarme na dengue, EXCETO:","options":{"A":"Crise convulsiva","B":"Dor abdominal intensa e contínua.","C":"Sangramento de mucosa.","D":"Letargia ou irritabilidade."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-175109","number":"175109","sourceNumber":"175109","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Lourdes, 10 anos, 25 kg, com hipótese diagnóstica de dengue, sem sinais de alarme,\nsem comorbidades, não faz parte de grupos de risco ou condições clínicas especiais. Ela deve\nreceber:","options":{"A":"40 ml/kg dia de volume hídrico, sendo 1/3 com solução salina e os 2/3 restantes, por ingestão de\nlíquidos caseiros.","B":"80 ml/kg dia de volume hídrico, sendo 1/3 na forma de soro de reidratação oral e o restante\natravés da oferta de água, sucos e chás.","C":"30 ml/kg dia de volume hídrico, sendo 1/3 com solução salina e os 2/3 restantes, por ingestão de\nlíquidos caseiros.","D":"130 ml/kg dia de volume hídrico, sendo 1/3 na forma de soro de reidratação oral e o restante\natravés da oferta de água, sucos e chás."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183961","number":"183961","sourceNumber":"183961","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A respeito das doenças infecciosas e parasitárias, julgue o item subsequente. De\nacordo com o critério de classificação de\nfebre hemorrágica da dengue definido pela Organização\nMundial de Saúde (OMS), o grau II corresponde ao quadro de febre acompanhada de sintomas\ninespecíficos, em que a única manifestação hemorrágica é a prova do laço positiva.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-183911","number":"183911","sourceNumber":"183911","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A respeito de doenças infecciosas e transmisssíveis, julgue o item seguinte. As\nmanifestações clínicas da dengue, quando presentes, podem variar de sintomas discretos, como\nfebre e adinamia, até sintomas mais graves, com evolução para choque em sete dias, na grande\nmaioria dos casos","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-154477","number":"154477","sourceNumber":"154477","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"(M) Homem, 50 anos de idade, procedente do interior de Pernambuco, com queixa de\n\"febre que vem e passa\" diariamente há 6 meses. Há cerca de 3 meses, vem notando também\nemagrecimento, falta de apetite, cansaço e \"aumento da barriga\". Durante o exame físico,\napresenta-se febril (38ºC), com palidez cutaneomucosa, baço palpável a 6 cm do rebordo costal\nesquerdo, sem outras alterações dignas de nota. Hemograma: Hemoglobina 8 g/dL, Volume\nCorpuscular Médio 82 fL; Leucócitos 2100 /mm³; Plaquetas: 65000 /mm³; Mielograma: formas\namastigotas livres e intramacrofágicas. Diante do quadro descrito, qual a principal hipótese\ndiagnóstica?","options":{"A":"Malária quartã.","B":"Linfoma.","C":"Mieloma múltiplo.","D":"Tuberculose.","E":"Calazar."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-168441","number":"168441","sourceNumber":"168441","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma mulher com 32 anos de idade procura unidade básica de saúde com queixa de\ndores intensas nas articulações das mãos e dos\npés associadas à rigidez matinal, com duração de\ncerca de 15 minutos e prejuízo funcional. Relata que os sintomas começaram há 3 meses, quando,\nao passar as férias de verão em outro estado, apresentou quadro de febre alta, além de manchas\nvermelhas no rosto, nos braços e no tórax, que persistiram por cerca de 10 dias. Informa que não\nprocurou atendimento médico na ocasião, passando a fazer uso de dipirona para alívio da dor, com\nmelhora não satisfatória. O exame clínico atual da paciente evidencia edema e dor nas articulações\ninterfalangianas distais, bilateralmente, e em tornozelos, não sendo observados no momento,\nlesões de pele mucosas ou nódulos subcutâneos. Os resultados do hemograma completo e do\nexame de urina de rotina revelaram-se normais. Diante desse quadro, qual é o diagnóstico e o\ntratamento adequado?","options":{"A":"Osteoartrose; acetaminofeno.","B":"Artrite reumatoide; metotrexato.","C":"Chikungunya; hidroxicloroquina.","D":"Lúpus eritematoso sistêmico; prednisolona."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-168476","number":"168476","sourceNumber":"168476","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma adolescente com 16 anos de idade é atendida em uma unidade de pronto\natendimento com história de febre de 38,5°C,\ncefaleia, mialgia e dor retro-orbitária há 4 dias. Nega\nvômitos ou sangramentos. Ao exame físico, evidencia-se prova do laço com surgimento de 23\npetéquias na área demarcada; pressão arterial e frequência cardíaca normais. O hemograma\napresenta: hematócrito = 49% (valor de referência: 42 ± 6%), hemoglobina = 16 g/dl (valor de\nreferência: 13,6 ± 2,0 g/dl) e plaquetas = 6.000/ml (valor de referência: 130.000 a 370.000/ml).\n\nConsiderando o quadro clínico apresentado, a conduta adequada é:","options":{"A":"Reposição volêmica endovenosa com 20 ml/kg de soro fisiológico em 20 minutos; repetição do\nexame de hematócrito em 2 horas; internação\nda paciente em leito de terapia intensiva até sua\nestabilização.","B":"Reposição volêmica endovenosa com 10 ml/kg de soro fisiológico na primeira hora; repetição do\nexame de hematócrito em 2 horas;\nacompanhamento da paciente em leito de internação até sua\nestabilização.","C":"Hidratação oral da paciente com 60 ml/kg/dia, sendo 1/3 com solução de reidratação oral e o\nrestante com líquidos caseiros; tratamento da paciente em regime ambulatorial com reavaliação\ndiária do quadro clínico.","D":"Hidratação oral da paciente com 80 ml/kg/dia, sendo 1/3 com solução de reidratação oral e o\nrestante com líquidos caseiros; tratamento da paciente em regime ambulatorial com reavaliação\napós melhora da febre."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-168475","number":"168475","sourceNumber":"168475","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem com 27 anos de idade, sem histórico de doenças prévias, proveniente da zona\nrural, procura atendimento médico por apresentar febre (temperatura axilar = 38 °C) e fraqueza há\n10 dias, associadas à dor abdominal. Ao exame físico, observa-se paciente emagrecido, com\npalidez cutâneo-mucosa, anictérico, com hepatoesplenomegalia e linfonodos cervicais palpáveis.\n\nObserva-se, ainda, ausência de ascite ou circulação colateral e de edema de membros inferiores. O\nresultado do hemograma completo revela pancitopenia. O quadro clínico descrito é indicador de:","options":{"A":"Esquistossomose mansônica.","B":"Leishmaniose visceral.","C":"Doença de Chagas.","D":"Hepatite viral Delta."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-111269","number":"111269","sourceNumber":"111269","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os fenômenos retratados abaixo são manifestações características do seguinte quadro\ninfeccioso: (VER IMAGEM).","options":{"A":"Pneumonia por Pneumococcus.","B":"Diabetes descompensada.","C":"Sífilis.","D":"Endocardite por Staphylococcus aureus.","E":"Osteomielite."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":["question_bank/media/medcurso/medcurso-infectologia-inf-3/111269.png"],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-111303","number":"111303","sourceNumber":"111303","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa correta, com relação à infecção urinária na gravidez.","options":{"A":"A bacteriúria assintomática é diagnosticada quando existe mais de 100 000 leucócitos/ml no\nexame de urina.","B":"A Escherichia coli é o agente etiológico mais comum na gravidez.","C":"Deve-se sempre aguardar a urocultura, para que o tratamento seja mais adequado.","D":"Nos casos graves, a internação da paciente é opcional.","E":"O tratamento da bacteriúria assintomática é desnecessário, já que não representa infecção."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-111349","number":"111349","sourceNumber":"111349","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 3 anos de idade dá entrada no pronto socorro com história de febre alta\nhá 1 dia, acompanhada de vômitos. Ao exame, encontra-se em MEG, obnubilada, com rigidez de\nnuca e lesões de pele compatíveis com vasculite. Enchimento vascular > 3 seg, PA = 40/20mmHg,\nT= 39,5? C. Com base no quadro apresentado, você pode afirmar:","options":{"A":"É certamente um quadro de meningite\n\nmeningocóccica, devendo iniciar Penicilina Cristalina em altas doses e coleta de líquor para\nanálise.\nIniciar profilaxia a familiares e\nprofissionais do PS com Rifampicina. Internamento em isolamento.","B":"O quadro é compatível com meningite bacteriana e choque séptico, devendo ser iniciada\ncefalosporina de 3ª geração, precedida de\ndexametasona e infusão rápida de solução fisiológica EV\n20 a 100 ml/kg/hora. Providenciar vaga em UTIP.","C":"O quadro é de meningite bacteriana e choque\n\nhipovolêmico. Solicita vaga em UTIP enquanto hidrata a criança com Solução Fisiológica 4 ml/kg/h\ne aguarda líquor para definir antibiótico a ser\nutilizado.","D":"É certamente meningite bacteriana com falência de suprarrenal, devendo iniciar Hidrocortisona\nimediatamente e Penicilina Cristalina em altas doses. Internar em isolamento.","E":"O quadro é de CIVD secundária a meningite por meningococo, seguindo a sequência iniciar\nCefalosporina de 3ª geração, colher líquor, fazer volume para choque na forma de plasma fresco,\niniciar corticosteróide EV e solicitar vaga na UTIP."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-80740","number":"80740","sourceNumber":"80740","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Na suspeita de meningite, procede-se com a punção lombar para análise do liquor. A\ncomparação de uma dosagem bioquímica no liquor e no sangue pode auxiliar na diferenciação\nentre a meningite de etiologia bacteriana e a meningite viral. Com base nessas informações,\nassinale a alternativa que apresenta a dosagem bioquímica a ser considerada para a diferenciação\ndas meningites.","options":{"A":"Glicose.","B":"Magnésio.","C":"Potássio.","D":"Amilase.","E":"Sódio."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-97787","number":"97787","sourceNumber":"97787","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Comissão de Controle da Infecção Hospitalar de uma Maternidade identifica aumento\nde infecção cutânea puerperal na enfermaria\nobstétrica para pacientes de baixo risco (sem\ncomorbidades) após remanejamento da equipe dos profissionais de saúde responsáveis pela\nassistência. Não foram verificadas alterações no registro de inspeção da esterilização das caixas\ncirúrgicas. A antibioticoprofilaxia de todas as pacientes foi mantida por 24 horas. As culturas\nobtidas\nde material purulento, colhido de focos de infecção, identificaram uma cepa de estafilococos\nsensível à meticilina. Qual a medida que deve ser proposta para solucionar o problema do aumento\nna incidência de infecçào puerperal nessa Maternidade?","options":{"A":"Ampliar o tempo de antibioticoprofilaxia.","B":"Aumentar o número de caixas cirúrgicas.","C":"lniciar uma campanha para lavagem das mãos.","D":"Escalar duas circulantes em cada sala cirúrgica."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-97814","number":"97814","sourceNumber":"97814","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem com 24 anos de idade, geólogo, irá viajar em expedição na Amazônia Legal\ndaqui a 20 dias, onde deverá passar cerca de dois meses em localidades diferentes, coletando\namostras de solo para sua tese de doutorado. Ele procurou a Unidade Básica de Saúde do seu\nbairro para orientações sobre a profilaxia da malária. Qual é a conduta adequada neste momento\npara garantir a segurança do paciente?","options":{"A":"Solicitar ao paciente o seu itinerário e pedir que ele retorne em dois dias para que seja\ninformado\nacerca da conduta adequada, pois a\nestimativa do risco do viajante adquirir malária no destino deve\nlevar em consideração a Incidência Parasitária Anual (IPA).","B":"Orientar o paciente a vacinar-se pelo menos dez dias antes da viagem, tendo em vista que,\napesar de a malária ser uma doença grave sem\ntratamento específico, possui uma vacina segura e\neficaz. Informar que não é necessário tomar a vacina se ele já foi vacinado nos últimos dez anos e\norientá-lo a levar o cartão de vacinação na bagagem.","C":"Orientar o paciente a tomar as seguintes medidas de proteção contra picadas de mosquitos: uso\nde roupas claras e com manga longa; uso de\nmosquiteiro impregnado com piretroides e uso de\nrepelentes à base de dietilmetaloamida (DEET), principalmente ao amanhecer e ao pôr do sol.","D":"Informar ao paciente que a medida de prevenção mais segura contra a malária é a\nquimioprofilaxia (QPX), que consiste no uso de\ndrogas antimaláricas em doses subterapêuticas. O\nesquema não previne, no entanto, infecção pelo Plasmodium sp ou recaídas por P. vivax ou P.\novale."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-97819","number":"97819","sourceNumber":"97819","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem, com 35 anos de idade, é removido para hospital após dar entrada em\nUnidade de Pronto Atendimento com quadro\nsúbito de calafrios, febre alta, mialgia intensa,\nprincipalmente em panturrilhas e hiperemia conjuntival. Familiares informaram que o paciente\nresidia em área de alagamento, ocorrido recentemente. Ao dar entrada no hospital, foram\nsolicitados hemograma completo, que revelou leucocitose com neutrofilia e desvio para a esquerda,\ne radiografia de tórax, cujo laudo foi de pneumonite intersticial. Foi iniciada antibioticoterapia\nvenosa com amoxicilina + clavulanato de potássio associada à claritromicina. No terceiro dia de\ninternação, o paciente evoluiu com piora do quadro clínico, sem oligúria, aparecimento de icterícia,\nhipocalemia, elevação dos níveis séricos de ureia, creatinina e Creatinofosfoquinase (CPK). O\nexame físico evidenciou hepatomegalia e diátese hemorrágica. O paciente evoluiu com insuficiência\nrespiratória aguda e necessidade de intubação orotraqueal, em que foi visualizado sangramento de\nvias aéreas. Nova radiografia de tórax mostrou áreas de condensação alveolar difusas. Foi\nrealizada ultrassonografia renal que evidenciou rins aumentados de tamanho com ecogenicidade\nnormal. Qual a hipótese diagnóstica?","options":{"A":"Dengue.","B":"Hantavirose.","C":"Leptospirose.","D":"Febre macular."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-75530","number":"75530","sourceNumber":"75530","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma criança com 10 anos de idade é trazida ao hospital de referência, em cidade de\ngrande porte, com quadro que já se arrasta há\nseis meses. Apresenta febre irregular intercalada\ncom períodos de apirexia, anorexia e perda ponderal de 6 kg. A mãe relata, ainda, diarreia\nocasional, sangramento gengival frequente, epistaxe e episódios de pneumonia e otite, tratados\ncom antibióticos nos dois últimos meses, pouco antes da mudança realizada pela família, que saiu\nde uma cidade da zona rural para uma cidade da zona urbana. Ao exame, a criança apresenta-se\nemagrecida, hipodesenvolvida para a idade, cabelos finos e quebradiços, hipocorada 2+/4,\nanictérica, com micropoliadenopatia cervical e axilar bilateral, sopro sistólico 2+/6+, pancardíaco,\nabdome distendido, com fígado palpável a 5 cm do rebordo costal direito, baço palpável a 8 cm do\nrebordo costal esquerdo, edema de membros inferiores 1+/4, frio e com cacifo. Temperatura axilar\n\n= 37,8°C; PA = 100 x 70 mmHg; FC = 104 bpm; FR = 18 irpm. A melhor correlação entre a\nmanifestação clínica apresentada pela criança e seu mecanismo fisiopatológico, nessa endemia\nbrasileira, é:","options":{"A":"a esplenomegalia como efeito da hipertrofia\n\nprogressiva, por aumento da pressão sanguínea no sistema portal intra-hepático e da veia\nesplênica.","B":"as infecções bacterianas como seguimento ao\n\naumento da resposta imunológica TH1 e da produção exagerada de interferon gama e interleucina\n2.","C":"o edema de membros inferiores, frio e com cacifo,\ncomo consequência da insuficiência cardíaca\ncongestiva secundária à miocardiopatia dilatada.","D":"a anemia como resultado da combinação de hemólise, ocupação de medula óssea por\nmacrófagos infectados, hemorragias e sequestro esplênico.","E":"os sangramentos gengivais e epistaxe como efeito da diminuição da produção de fatores de\ncoagulação pela lesão direta e insuficiência hepatocelular."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-75502","number":"75502","sourceNumber":"75502","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem com 29 anos de idade reside em cidade de grande porte da região Sudeste,\nonde trabalha como administrador de empresas.\nNo próximo final de semana, vai viajar para um\nmunicípio da região Norte. Preocupado com as informações sobre a ocorrência de malária na\nregião, procurou a Unidade Básica de Saúde para receber orientações quanto à profilaxia da\nmalária. Na consulta com o médico, não relatou nenhum problema de saúde e informou que iria\npermanecer no município por dez dias. O médico da Unidade Básica de Saúde explicou a ele a\nforma de transmissão da malária, os sintomas da doença e orientou quanto à profilaxia. A\norientação adequada a esse usuário é:","options":{"A":"Não viajar, uma vez que a quimioprofilaxia deve ser\n\niniciada uma semana antes da chegada na zona de transmissão de malária e não haveria tempo\nhábil para que a quimioprofilaxia fosse capaz de oferecer proteção no dia de sua chegada.","B":"Especificar as medidas de proteção individual e\n\nprescrever a quimioprofilaxia com a combinação de atovaquona + proguanil para reduzir o risco de\nefeitos colaterais.","C":"Orientar quanto às medidas de proteção individual e prescrever a quimioprofilaxia com\nmefloquina, 250 mg semanalmente, iniciando imediatamente o uso do medicamento.","D":"Informar sobre as medidas de proteção individual e\n\nprescrever quimioprofilaxia com dois comprimidos de cloroquina por semana durante o período em\nque permanecer na área com transmissão de\nmalária.","E":"Orientar quanto às medidas de proteção individual\ncomo: não se aproximar de áreas de risco após o\n\nentardecer e logo ao nascer do dia; usar roupas claras e de mangas longas; aplicar repelentes nas\npartes do corpo expostas e utilizar mosquiteiro para dormir."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137592","number":"137592","sourceNumber":"137592","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A dengue é considerada a mais importante arbovirose que acomete o homem e,\ndesde 1986, vem se destacando como agravo à saúde prevalente no país, com registro\nconsiderável da forma hemorrágica e de óbitos. Na vigência de episódios epidêmicos de\ndengue, qual a medida adequada de vigilância epidemiológica?","options":{"A":"Aplicar inseticida como aerodispersoide.","B":"Divul gar precocemente o índice de infestação dos domicílios pelo Aedes aegypti.","C":"Observar rigorosamente a responsabilidade médica envolvida no tratamento diferenciado\nimediato.","D":"Adotar protocolos para tratamento da doença, construídos cuidadosamente ao longo do\nepisodio epidêmico.","E":"Capacitar seletivamente os profissionais de saúde a ser em mobilizados na atenção aos\nsuspeitos de dengue."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137606","number":"137606","sourceNumber":"137606","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem de 39 anos de idade é trazido à Unidade de Pronto Atendimento por\nfamiliares, com história de febre há quatro\ndias, que cedeu nas últimas doze horas, bem\ncomo cefaleia, astenia e vômitos. Refere sangramento gengival ao escovar os dentes. Entre os\nexames sol i ci tados, o resultado do hematócrito é 47% (valor de referência: 47 ± 7%) e a prova\ndo laço é positiva. Frente a esse quadro, a conduta mais adequada é","options":{"A":"proceder à hidratação oral vigorosa, pois há fortes indícios de dengue com complicação.","B":"pesquisar sinais de alerta como dor abdominal intensa e contínua, hipotensão postural,\nhipotensão arterial, pressão diferencial < 20 mmHg (P A convergente), hepatomegalia\ndolorosa, extremidades frias, cianose, pulso rápido e fino e, se presente algum, instalar\nhidratação com solução de reidratação oral copiosa supervisionada.","C":"indicar tratamento ambulatorial com hidratação oral, antitérmicos e analgésicos, se\nnecessários, orientar sobre sinais de alerta para o retorno, a fim de repetir exames\nlaboratoriais.","D":"manter o paciente em leito de observação, iniciar hidratação oral supervisionada e repetir\nexames laboratoriais após quatro horas de hidratação.","E":"notificar a Vigilância Epidemiológica e indicar tratamento ambulatorial com hidratação oral,\nantitérmicos e analgésicos, pois se trata de caso grave de febre hemorrágica da dengue."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137613","number":"137613","sourceNumber":"137613","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente do sexo masculino, 30 anos de idade, procedente do Rio de Janeiro, foi\nadmitido na Emergência hospitalar referindo febre, dor de cabeça, diarreia e dor articular ,\niniciados\nhá 6 dias. Informa que a febre cessou há dois dias e, há um dia, passou a apresentar dor\nabdominal contínua de forte intensidade, sem melhora com o uso de paracetamol. O paciente nega\ndoenças prévias. Ao exame físico, apresenta estado geral regular, eupneico, hidratado, corado,\nconsciente e orientado; ausculta respiratória e cardíaca normais; pressão arterial = 120 x 80 mmHg;\nprova do laço negativa; abdome depressível, doloroso à palpação em hipocôndrio direito, sem\nvisceromegalias. Nesse caso, a melhor conduta a ser tomada é","options":{"A":"dar alta após solicitação de hemograma e sorologia viral e orientar o paciente a retornar após\nseis horas para avaliar o resultado do hemograma.","B":"colocar o paciente em observação por 12 horas na unidade de emergência e administrar\nmedicamentos sintomáticos e hidratação oral.","C":"transferir o paciente para unidade de cuidados semi-intensivos para monitorização contínua e\nrealização de exames.","D":"dar alta com orientações para acompanhamento ambulatorial na unidade de atenção primária.","E":"internar o paciente por 48 horas para observação e realização de exames complementares."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-138563","number":"138563","sourceNumber":"138563","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, com 32 anos de idade, hígida anteriormente, deu entrada em serviço de\nurgência municipal com quadro clínico de febre\nalta, mialgia, artralgia, cefaléia, prostração, dor\nretroorbitária e exantema. Apresentava-se lúcida e orientada. Ao exame fisico, constatou-se\ndesidratação, temperatura = 39,5°C, Frequência cardíaca = 102 bpm, Frequência respiratória = 20\nirpm e Pressão arterial = 90 x 60 mmHg. Ausculta cardiopulmonar normal. A avaliação laboratorial\nmostrou: Hematócrito = 35 %; leucócitos totais = 1.900 /mm³; plaquetas = 102.000 /mm³. Diante do\nquadro, neste momento, qual a prioridade no manuseio da paciente?","options":{"A":"Solicitar sorologia para dengue","B":"Prescrever paracetamol para controle da temperatura e analgesia.","C":"Instalar hidratação venosa.","D":"Orientar hidratação vigorosa, em domicílio.","E":"Encaminhar para unidade hospitalar do nível secundário."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-22170","number":"22170","sourceNumber":"22170","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente com 70 anos de idade apresenta há 2 semanas quadro clínico\ncaracterizado por mal-estar geral\nacompanhado de anorexia, náuseas e vômitos. Após uma\nsemana, o paciente apresentou cefaleia e febre remitente de 39°C que não cedia com o uso de\nantipiréticos. Os familiares notaram o surgimento de confusão mental cerca de 24 horas antes da\ninternação do paciente. Por duas ocasiões, procurou assistência médica, tendo recebido tratamento\npara virose. Quando da internação, o exame físico mostrou paciente prostrado e sonolento, que\nrespondia a estímulos verbais, embora de maneira lentificada. Observou-se a presença dos sinais\nde Kerning e Brudzinski. O exame do liquor mostrou líquido límpido hipertenso, com celularidade de\n500/mm³ e predomínio linfocitário, taxa de proteínas de 300 mg% e a glicose de 30 mg%. Não se\nidentificou a presença de bactérias e fungos no citado material biológico. Foram solicitados alguns\nexames complementares prospectivos, tendo sido encontrados micronódulos difusos de distribuição\naleatória na radiografia de tórax. Procedeu-se ao exame de PPD, que se revelou negativo. Com\nbase nesse quadro clínico, julgue o item a seguir. O sinal de Brudzinski é obtido quando se observa\na flexão involuntária da perna sobre a coxa e desta sobre a bacia ao se tentar antefletir a cabeça.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-22172","number":"22172","sourceNumber":"22172","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente com 70 anos de idade apresenta há 2 semanas quadro clínico\ncaracterizado por mal-estar geral\nacompanhado de anorexia, náuseas e vômitos. Após uma\nsemana, o paciente apresentou cefaleia e febre remitente de 39°C que não cedia com o uso de\nantipiréticos. Os familiares notaram o surgimento de confusão mental cerca de 24 horas antes da\ninternação do paciente. Por duas ocasiões, procurou assistência médica, tendo recebido tratamento\npara virose. Quando da internação, o exame físico mostrou paciente prostrado e sonolento, que\nrespondia a estímulos verbais, embora de maneira lentificada. Observou-se a presença dos sinais\nde Kerning e Brudzinski. O exame do liquor mostrou líquido límpido hipertenso, com celularidade de\n500/mm³ e predomínio linfocitário, taxa de proteínas de 300 mg% e a glicose de 30 mg%. Não se\nidentificou a presença de bactérias e fungos no citado material biológico. Foram solicitados alguns\nexames complementares prospectivos, tendo sido encontrados micronódulos difusos de distribuição\naleatória na radiografia de tórax. Procedeu-se ao exame de PPD, que se revelou negativo. Com\nbase nesse quadro clínico, julgue o item a seguir. A prescrição de corticosteroides em situações\nclínicas como descrita tem como justificativa diminuir o edema e o processo inflamatório cerebral.","options":{"A":"certo","B":"errado"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-359209","number":"359209","sourceNumber":"359209","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em uma lagoa de uma pequena cidade mineira, foi localizada uma população de\ncaramujos Biomphalaria glabrata. Na região, não são\nrelatados casos de esquistossomose, mas um\ndos caramujos recolhidos estava negativos para Schistosoma mansoni. É CORRETO afirmar que\nessa área deve, portanto, ser definida como","options":{"A":"área indene com potencial de transmissão.","B":"área indene sem potencial de transmissão.","C":"área vulnerável.","D":"área focal."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-320418","number":"320418","sourceNumber":"320418","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa verdadeira em relação ao modo de transmissão da malária no\nhomem:","options":{"A":"Ingestão de ovos eliminados nas fezes do mosquito em um processo denominado auto-infecção\nexterna.","B":"Inoculação das larvas através da pele e mucosas e consequente disseminação via\nhematogênica.","C":"Através de vetor e inoculação do protozoário sob a forma amastigota na pele de pacientes.","D":"Picada da fêmea do mosquito Anopheles quando infectada pelo Plasmodium spp.","E":"Ocasionalmente transmissão direta de pessoa a pessoa na fase febril da doença."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-320419","number":"320419","sourceNumber":"320419","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A leptospirose é uma doença infecciosa febril de início abrupto, cujo espectro clínico\npode variar desde um processo inaparente até\nformas graves. Em relação à leptospirose, é correto\nafirmar que:","options":{"A":"o principal reservatório é constituído por roedores sinantrópicos, que se infectam, desenvolvem a\ndoença, tornam-se portadores com posterior eliminação urinária.","B":"o agente etiológico apresenta baixo grau de variação antigênica e de capacidade de\nsobrevivência no meio ambiente.","C":"os animais são os reservatórios essenciais para a persistência dos focos da infecção, enquanto\nos seres humanos são apenas hospedeiros\nacidentais, pouco eficientes na sua perpetuação.","D":"a penetração do microrganismo no homem não se dá através da pele íntegra, necessitando de\npele lesada como porta de entrada, exposição de mucosas da boca, narinas e olhos.","E":"a transmissão pessoa a pessoa é frequente, podendo ocorrer pelo contato com urina, sangue,\nsecreções e tecidos de pessoas infectadas."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345707","number":"345707","sourceNumber":"345707","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação ao exame complementar que pode ser utilizado para a confirmação da\nhipótese diagnóstica de Leishmaniose Visceral, assinale a alternativa correta.","options":{"A":"Pesquisa do parasita no mielograma.","B":"Sorologia positiva na titulação superior a 1:20.","C":"Pesquisa negativa do antígeno rK39.","D":"Intradermorreação de Montenegro."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345708","number":"345708","sourceNumber":"345708","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação à indicação para iniciar o tratamento da Leishmaniose Visceral com\nanfotericina B lipossomal, assinale a alternativa correta.","options":{"A":"Menores de 5 anos","B":"Puérperas","C":"Maiores de 40 anos","D":"Coinfecção por HIV"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345709","number":"345709","sourceNumber":"345709","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação à definição de que o paciente em tratamento para Leishmaniose Visceral\nestá evoluindo de forma satisfatória, já que se\ntrata de uma doença de curso bastante arrastado,\nassinale a alternativa correta.","options":{"A":"Melhora da febre na primeira semana.","B":"Retorno do apetite na segunda semana.","C":"Melhora do hemograma na terceira semana.","D":"Regressão do baço e do fígado ao fim do primeiro mês."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-345710","number":"345710","sourceNumber":"345710","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação às complicações infecciosas da Leishmaniose Visceral, assinale a\nalternativa incorreta.","options":{"A":"Otite média aguda.","B":"Piodermites.","C":"Infecções do trato gastrointestinal.","D":"Infecções do trato respiratório."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-321197","number":"321197","sourceNumber":"321197","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os Agentes de Combate a Endemias (ACE) trabalham com a vistoria de residências,\ndepósitos, terrenos baldios e estabelecimentos\ncomerciais para buscar focos endêmicos. Estes\npodem atuar aplicando larvicidas e inseticidas, exercendo atividades fundamentais para prevenir\ndoenças. O controle de focos de mosquitos vetores é importante nas seguintes doenças, EXCETO:","options":{"A":"Leptospirose.","B":"Febre amarela.","C":"Chikungunya.","D":"Leishmaniose."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-337660","number":"337660","sourceNumber":"337660","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a dengue, assinale a alternativa INCORRETA:","options":{"A":"O agente etiológico é um vírus DNA, sendo conhecidos 3 sorotipos.","B":"A transmissão se faz pela picada dos mosquitos A.aegypti (vetor).","C":"A imunidade é permanente para um mesmo sorotipo (homóloga).","D":"O tratamento baseia-se principalmente em hidratação adequada."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-305027","number":"305027","sourceNumber":"305027","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Considere que durante o verão, um homem de 35 anos de idade é atendido no centro\nde saúde de Vila Velha, com relato de febre\nalta termometrada (TAx = 39ºC) há cerca de três dias,\ncefaleia, mialgia e dor retro-orbitária. Hoje observou petéquias. Ao exame está alerta, bem\norientado no tempo e espaço, acianótico. A TAx 38,7ºC, FC = 110 bpm e a PA = 130 x 70 mmHg\nsentado, e 120 x 70 mmHg em pé. A perfusão capilar está preservada e os pulsos periféricos,\namplos. A ausculta respiratória é normal e a FR = 20 irpm. A prova do laço na abordagem desse\npaciente é:","options":{"A":"Dispensável, uma vez que o paciente apresenta sangramento espontâneo.","B":"Dispensável, uma vez que, na vigência de epidemia, bastam os sintomas para a confirmação de\ndengue.","C":"Essencial para a confirmação do diagnóstico de dengue.","D":"Essencial para caracterização de febre hemorrágica da dengue."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-314057","number":"314057","sourceNumber":"314057","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Segundo o Caderno de Atenção Básica nº 21: Vigilância em Saúde, sobre a dengue,\nanalisar os itens abaixo: I. Pode ser de\ncurso benigno ou grave, a depender de sua forma de\napresentação: formas inaparentes, dengue clássica (DC), febre hemorrágica da dengue (FHD) ou\nsíndrome do choque da dengue (SCD), podendo evoluir para o óbito. II. A dengue na criança, na\nmaioria das vezes, apresenta-se como uma síndrome febril com sinais e sintomas inespecíficos:\napatia ou sonolência, recusa da alimentação, vômitos, diarréia ou fezes amolecidas. Nos menores\nde dois anos de idade, os sintomas cefaleia, mialgia, e artralgia podem manifestar-se por choro\npersistente, adinamia e irritabilidade, geralmente com ausência de manifestações respiratórias. III.\nPara ser considerado um caso suspeito da doença, o paciente precisa apresentar febre com\nduração mínima de 14 dias, acompanhada de hemorragias. Além desses sintomas, o paciente deve\nter estado, nos últimos 15 dias, em áreas onde esteja ocorrendo transmissão de dengue. Está(ão)\nCORRETO(S):","options":{"A":"Somente os itens II e III.","B":"Somente os itens I e II.","C":"Somente o item I.","D":"Somente o item II.","E":"Nenhum dos itens."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-260664","number":"260664","sourceNumber":"260664","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Marque a alternativa onde todos os medicamentos são utilizados no tratamento da\nmalária no Brasil:","options":{"A":"Praziquantel, cloroquina, niclosamida.","B":"Sulfadiazina, irimetamina, ácido folínico.","C":"Nitazoxanida, nitrofurantoína, antimonial pentavalente.","D":"Cloroquina, primaquina, lumefantrina.","E":"Mefloquina, praziquantel, primaquina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-260666","number":"260666","sourceNumber":"260666","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Aponte a alternativa onde são utilizadas medidas de prevenção e controle dos agravos\ndecorrentes do contato do homem com a Leptospira interrogans presentes no ambiente:","options":{"A":"Controlar a população de roedores e uso de anti-inflamatórios.","B":"Uso de EPIs e troca diária dos equipamentos.","C":"Saneamento básico e uso de EPIs.","D":"Quimioprofilaxia de todos os contatos adultos.","E":"Cuidado com os alimentos e controle das cepas."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-260672","number":"260672","sourceNumber":"260672","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Durante uma epidemia a confirmação de caso de dengue clássica","options":{"A":"deve ser feita por critério clínico-laboratorial.","B":"depende da identificação do vetor no domicílio.","C":"é confirmada por identificação do vírus em contactantes.","D":"é feita quando não se observarem sangramentos.","E":"é obtida pelo resultado da contagem de plaquetas."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-287332","number":"287332","sourceNumber":"287332","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente feminina, 62 anos, apresentou quadro de febre de 39°C acompanhada de\nexantema que entrou em remissão após 03\ndias em repouso e com uso de analgésicos comuns. No\ninício do quadro apresentava artralgia difusa, que permanece em mãos e pés após quatro\nsemanas, com rigidez articular matinal e limitação de movimentos. Qual a principal hipótese\ndiagnóstica?","options":{"A":"Artrite infecciosa.","B":"Artrite reumatóide.","C":"Chikungunya.","D":"Dengue."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-266369","number":"266369","sourceNumber":"266369","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem de 62 anos apresentou quadro de febre de 39ºC acompanhada de exantema\nque entrou em remissão após 3 dias em repouso\ne com uso de analgésicos comuns. No início do\nquadro apresentava artralgia difusa, que permanece em mãos e pés após quatro semanas, com\nrigidez articular matinal e limitação de movimentos. Assinale a alternativa que corresponde à\nprincipal hipótese diagnóstica para o caso descrito.","options":{"A":"Artrite gonocócica.","B":"Artrite reumatóide.","C":"Artrite reativa.","D":"Chikungunya."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-287336","number":"287336","sourceNumber":"287336","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente jovem, morador de zona urbana, relata que no período das enchentes no\ninterior do estado do Espírito Santo, em\nlocal que há mata atlântica, foi ajudar os moradores em um\ntrabalho voluntário, ficando 10 dias no local. Relata que 02 dias após retornar iniciou febre de\ninício\nabrupto, com cefaléia, mialgia, náuseas e vômitos. Ao exame físico apresenta hiperemia\nconjuntival, com alguns pontos de hemorragia conjuntival, exantema na região pré-tibial, fígado e\nbaço discretamente aumentado. Evoluiu com icterícia, insuficiência renal e hemoptise. Qual a\nprincipal hipótese diagnóstica?","options":{"A":"Hepatite viral.","B":"Leptospirose.","C":"Leishmaniose visceral.","D":"Esquistossomose aguda."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-287855","number":"287855","sourceNumber":"287855","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a Leptospirose, analisar os itens abaixo: I. As formas hepatorrenal e\n\nictero-hemorrágica cursam com icterícia, hemorragia (pulmonar) e insuficiência renal. II. Por haver\nnecrose em musculatura esquelética, a\ncreatinofosfoquinase (CPK) está aumentada e a aspartato\naminotransferase encontra-se mais elevada do que a alanina aminotransferase. III. A hipercalemia\né um achado comum quando ocorre comprometimento renal. Está(ão) CORRETO(S):","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e II.","D":"Somente os itens I e III.","E":"Todos os itens."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-257386","number":"257386","sourceNumber":"257386","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"H.J.K., 33 anos, sexo masculino, procura a Unidade Básica de Saúde (UBS) devido a\nquadro de cefaleia intensa, febre persistente, mialgia e náuseas de início há 5 dias, com início\nhoje\nde sensação de vertigem e manchas pela pele. Durante avaliação, paciente prostrado, PA: 110 x\n60 mmHg com hipotensão postural, dor a palpação abdominal e exantema, sem demais alterações\nao exame físico. Diante do quadro descrito, assinale a alternativa que apresenta a MELHOR\nhipótese diagnóstica e conduta.","options":{"A":"Febre amarela/encaminhar para uma unidade de terapia intensiva.","B":"Dengue/iniciar hidratação venosa e encaminhar para unidade hospitalar.","C":"Doença meningocócica/isolar e encaminhar para o centro especializado.","D":"Leptospirose/iniciar antibioticoterapia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-246723","number":"246723","sourceNumber":"246723","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em áreas de risco elevado de aquisição de leptospirose, o medicamento de escolha\npara profilaxia dessa infecção em humanos é:","options":{"A":"Ciprofloxacina","B":"Vacina específica","C":"Rifampicina","D":"Doxiciclina","E":"Amoxicilina"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-246753","number":"246753","sourceNumber":"246753","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma mulher procedente da Serra/ES, 42 anos, diabética está em atendimento no PS\ndevido relato de febre, artralgia e mialgia generalizadas associadas a cefaleia há 4 dias. Informa\nque hoje iniciou dor abdominal difusa e forte. Normotensa e confortável em ar ambiente durante\nexame. Qual a conduta inicial recomendada:","options":{"A":"Sintomáticos, hidratação oral e retorno se piora","B":"Notificação de dengue com solicitação de sorologia, hemograma, hidratação oral e reavaliação\napós hemograma","C":"Notificação de dengue com solicitação de sorologia, Internação por no mínimo 48h, hidratação\nendovenosa, hemograma, proteína, albumina,\ntipagem sanguínea, gasometria, transaminases e RX\nde tórax","D":"Sintomáticos, hidratação endovenosa, sintomáticos e antibióticos empíricos","E":"Notificação de dengue com solicitação de sorologia, Internação em UTI, hidratação endovenosa,\nhemograma, proteína, albumina, tipagem sanguínea, gasometria, transaminases e RX de tórax"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-255659","number":"255659","sourceNumber":"255659","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual entre os abaixo é um sinal de alarme da dengue? MARQUE A CORRETA:","options":{"A":"Diarréia protraída.","B":"Cefaléia.","C":"Dor abdominal intensa (referida ou à palpação) e contínua.","D":"Defervescência."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-246807","number":"246807","sourceNumber":"246807","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É considerado sinal de alarme em caso de suspeita de dengue:","options":{"A":"mialgia","B":"cefaleia","C":"hepatomegalia dolorosa","D":"febre elevada (39ºC a 40ºC)","E":"dores na região retro-orbital"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-199552","number":"199552","sourceNumber":"199552","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher de 37 anos de idade apresenta febre de 39ºC de início abrupto há quatro dias,\nacompanhada de mialgia leve, poliartralgia intensa, exantema macular disseminado, desde o\nsegundo dia do início dos sintomas. Ao exame físico apresenta-se hidratada, normotensa, com\nprova do laço negativa, dor e edema em articulações dos punhos, mãos, joelhos, tornozelos e pés.\nExames laboratoriais: hemoglobina = 13,2 g/dl, hematócrito = 45%, leucócitos = 3100/mm³,\nneutrófilos = 74%, linfócitos = 13%, plaquetas = 123000/mm³, AST = 39 U/L (valor de referência até\n37 U/L), ALT = 48 U/L (valor de referência até 41 U/L), creatinina = 0,82 mg/dl. Assinale a\nalternativa que representa o diagnóstico mais provável para o quadro clínico acima.","options":{"A":"Artrite séptica.","B":"Chikungunya.","C":"Dengue.","D":"Zica."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-202732","number":"202732","sourceNumber":"202732","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Febre Amarela é uma doença infecciosa febril aguda, imunoprevenível, cujo agente\netiológico é transmitido por artrópodes, e que possui dois ciclos epidemiológicos de transmissão\ndistintos: silvestre e urbano. Qual alternativa apresenta uma assertiva com característica\nepidemiológica verdadeira?","options":{"A":"O ciclo silvestre é endêmico nas regiões tropicais da África, da Ásia e das Américas.","B":"Na população humana, o aparecimento de casos tem sido precedido de epizootias de primatas\nnão humanos.","C":"Apresenta-se sob a forma de epidemia com intervalos de tempo que podem variar de 3 a 7\nmeses, alternados por períodos com menor número de casos.","D":"Em virtude da regularidade no tempo entre os intervalos epidêmicos é possível afirmar que\napresenta um aspecto cíclico.","E":"Desde 1942, não há registro no Brasil do aparecimento de casos em sua forma grave."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-199573","number":"199573","sourceNumber":"199573","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente residente nos Estados Unidos, viajando a passeio no Espírito Santo,\nconheceu a região montanhosa de Pedra Azul,\ne posteriormente dirigiu-se para Conceição da\nBarra. Cerca de 5 dias após o retorno para casa, evoluiu com febre, mialgia, cefaléia holocraniana,\nque foram seguidas de rash cutâneo. Realizadas algumas sorologias, mas o diagnóstico assim\nmesmo ficou confuso. O laboratório consegue afirmar que trata-se de infecção por Flavivírus. Com\nbase nesta informação, quais os possíveis diagnósticos etiológicos?","options":{"A":"Dengue, Zika, Chikungunya.","B":"Dengue, Chikungunya, febre amarela.","C":"Zika, febre amarela, febre do Oropouche.","D":"Dengue, Zika, febre amarela."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-196798","number":"196798","sourceNumber":"196798","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Febre Chikungunya e dengue são causadas por qual grupo de vírus? Marque a\nCORRETA:","options":{"A":"Adenovírus","B":"Picornavirus","C":"Arbovírus","D":"Parvovírus"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-196819","number":"196819","sourceNumber":"196819","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A imunidade adquirida pós-infecção é sorovar-específica, podendo um mesmo indivíduo\napresentar a doença mais de uma vez se o agente etiológico de cada episódio pertencer a um\nsorovar diferente do(s) anterior(es). Marque a CORRETA para doença com estas características:","options":{"A":"Leptospirose","B":"Leishmaniose","C":"Febre do Zika Vírus","D":"Chikungunya"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-174363","number":"174363","sourceNumber":"174363","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É considerado critério para confirmação diagnóstica da febre amarela:","options":{"A":"Caso suspeito de febre amarela que evoluiu para óbito em menos de 10 dias, sem confirmação\nlaboratorial, em período e área compatíveis com surto ou epidemia.","B":"Exame laboratorial negativo, mas desde que comprovado que as amostras foram coletadas em\ntempo oportuno para a técnica laboratorial realizada.","C":"Presença de quadro febril agudo (até 7 dias), de início súbito, acompanhado de icterícia e/ou\nmanifestações hemorrágicas, residente em (ou procedente de) área de risco para febre amarela.","D":"Existência de indivíduo assintomático ou oligossintomático, mas originado de busca ativa, que\nnão tenha sido vacinado, mesmo que não\napresente sorologia (MAC-ELISA) positiva.","E":"Ocorrência de quadro febril em indivíduo residente em área de risco ou próximo a locais com\nocorrência de epizootia confirmada em primatas não humanos nos últimos 15 dias."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-188008","number":"188008","sourceNumber":"188008","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Analisando-se a sensibilidade dos antibióticos, é correto afirmar:","options":{"A":"a ampicilina/sulbactam é pouco ativa contra anaeróbios e enterococcus;","B":"ceftazidima é uma cefalosporina com boa atividade contra gram-negativos, principalmente frente\nà Pseudomonas aeruginosa;","C":"o aztreonam é bem ativo contra gram-negativos e gram-positivos, mas pouco ativo contra\nanaeróbios;","D":"a moxifloxacina é uma quinolona de quarta geração, de espectro estendido, dose única diária,\ncom um diferencial dentro da classe de possuir boa atividade frente ao Staphylococcus aureus\nmeticilina-resistente;","E":"o ertapenem é um carbapenêmico com meia vida mais longa que o imipenem, podendo ser\nadministrado, também, por via intramuscular, porém pouco ativo contra anaeróbicos."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-174385","number":"174385","sourceNumber":"174385","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Pré-escolar de quatro anos de idade, que reside na cidade de Baixo Guandu, noroeste\ndo Espírito Santo, apresenta história de febre\nhá um mês. Exame físico: palidez cutâneo-mucosa\nintensa, emagrecimento, micropoliadenopatia, fígado a 4 cm do rebordo costal direito e baço a 6 cm\ndo rebordo costal esquerdo. Exames complementares: hemograma: pancitopenia; parasitológico de\nfezes: negativo; proteinograma: albumina de 2 g/dl e globulina de 4 g/dl. O diagnóstico clínico mais\nprovável é:","options":{"A":"Mucopolissacaridose.","B":"Leucemia linfoblástica aguda.","C":"Síndrome hemofagocítica.","D":"Esquistossomose hepatoesplênica.","E":"Leishmaniose visceral."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-172531","number":"172531","sourceNumber":"172531","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à Chikungunya é INCORRETO afirmar:","options":{"A":"Também é transmitida pelo Aedes Aegypti.","B":"Apresenta alta letalidade, inclusive superior à dengue, o que pode ser suspeitado pelas altas\ntaxas de mortalidade encontradas na Indonésia.","C":"Já foi identificada no Brasil e outros países das Américas.","D":"É diagnóstico diferencial da dengue.","E":"A artralgia geralmente surge no início dos sintomas, costuma ser intensa, por vezes\ntemporariamente incapacitante e pode ter duração prolongada."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-149132","number":"149132","sourceNumber":"149132","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É CORRETO afirmar:","options":{"A":"Que a análise de dados dos casos recentes de Zika vírus, em especial na Colombia, fornece\nsuporte para se estabelecer uma relação desse\nvírus com síndrome de Guillain-Barré.","B":"O Aedes aegypti é até o momento o único vetor comprovadamente relacionado à transmissão do\nZika vírus, mas outros estão sendo avaliados.","C":"Como Aedes aegypti está restrito a América do Sul e Central, os casos de Zika vírus\nidentificados nos Estados Unidos são apenas\nrelacionados a indivíduos infectados fora do seu\nterritório.","D":"Ainda é necessário busca por evidências da transmissão materno-fetal do Zika, porque apesar\nde bastante provável, elas ainda não existem.","E":"A possibilidade de transmissão do Zika por transfusão sanguínea já foi descartada em recentes\npesquisas."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-148594","number":"148594","sourceNumber":"148594","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A dengue, isoladamente, é uma doença que preocupa os órgãos de saúde do Brasil,\npois está presente em praticamente 100% do\nterritório nacional. Observe as afirmativas a seguir e\nresponda se é Verdadeiro (V) ou Falso (F): 1- Na dengue, o exame mais utilizado para o\ndiagnóstico é o ELISA, que detecta anticorpos IgM específicos contra dengue e tem a vantagem de\npoder ser realizado com 24h do início da doença; 2- A dengue conta hoje com cinco sorotipos virais\njá identificados DEN-1, DEN-2, DEN-3, DEN-4 e DEN-5; 3- Na dengue, após uma infecção por\ndeterminado sorotipo de vírus, a imunidade é vitalícia contra esse sorotipo, oferecendo uma\nproteção parcial e transitória contra a infecção subsequente pelos outros sorotipos; 4- Na dengue, o\nexantema está presente em todos os casos e é predominantemente do tipo maculopapular,\natingindo face, tronco e membros de forma aditiva, não poupando plantas de pés e palmas de\nmãos.","options":{"A":"F ? V ? F ? V.","B":"V ? V ? F ? V.","C":"F ? V ? V ? F.","D":"F ? F ? V ? V.","E":"V ? V ? V ? F."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-155357","number":"155357","sourceNumber":"155357","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A doença causada pela Rickettsia ricketsii e transmitida pelo carrapato denomina-se e\ndeve ser tratada, respectivamente:","options":{"A":"Febre purpúrica; ganciclovir.","B":"Febre purpúrica; cloranfenicol.","C":"Febre purpúrica; penicilina cristalina.","D":"Febre maculosa; doxiciclina.","E":"Febre maculosa; ganciclovir."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-155364","number":"155364","sourceNumber":"155364","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São sinais de alarme na dengue, EXCETO:","options":{"A":"Vômitos persistentes.","B":"Sangramento de mucosa.","C":"Irritabilidade.","D":"Aumento progressivo do hematócrito.","E":"Hipertensão."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137812","number":"137812","sourceNumber":"137812","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A febre maculosa brasileira é uma doença infecciosa febril aguda, de gravidade\nvariável, cuja apresentação clínica pode\nvariar desde as formas leves e atípicas até formas graves.\nQual o agente infeccioso?","options":{"A":"Treponema pallidum.","B":"Amblyomma cajennense.","C":"Haemophilus influenzae.","D":"Hydrochoerus hydrochaeris.","E":"Rickettsia rickettsii."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127213","number":"127213","sourceNumber":"127213","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em qual das viroses a seguir o Aedes aegypti NÃO pode ser o vetor da doença?","options":{"A":"Doença por Zika vírus.","B":"Dengue pelo sorotipo 4.","C":"Febre Chikungunya.","D":"Hantavirose.","E":"Febre amarela."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-131630","number":"131630","sourceNumber":"131630","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As endocardites bacterianas em prótese valvar, que ocorrem entre 2 e 12 meses após\na cirurgia de troca valvar, têm como\nprincipais agentes etiológicos:","options":{"A":"Enterococos.","B":"Bactérias do grupo HACEK.","C":"Bacilos Gram-negativos.","D":"Estafilococos coagulase-negativos.","E":"Estreptococos do grupo A."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-102762","number":"102762","sourceNumber":"102762","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os sinais e sintomas da meningite bacteriana são variáveis e dependem da idade. Em\nrelação ao diagnóstico clínico da meningite bacteriana, assinale a alternativa INCORRETA.","options":{"A":"Os sinais e sintomas podem se desenvolver em poucas horas, indicando alto risco de\nmortalidade.","B":"As convulsões ocorrem em 40% dos recém-nascidos e o abaulamento de fontanela em torno de\n30% dos casos.","C":"As crianças maiores apresentam sinais de irritação meníngea.","D":"Os sinais de rigidez da nuca, Brudzinski e de Kernig são pouco característicos de infecção do\nsistema nervoso central."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-101033","number":"101033","sourceNumber":"101033","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"UL, 45 anos, apresenta quadro de dor abdominal localizada em hipocôndrio esquerdo,\nadinamia e febre. A tomografia computadorizada do abdome diagnostica abscesso esplênico.\n\nQuanto ao abscesso esplênico, qual a afirmativa errada?","options":{"A":"Quando apresenta abscessos múltiplos, a mortalidade pode ser de 80%.","B":"Quando apresenta abscesso único, a mortalidade está em torno de 15%.","C":"Entre as doenças predisponentes temos a endocardite bacteriana e a policitemia vera.","D":"Ocorre, na maioria das vezes, após traumatismo abdominal.","E":"Entre os germes mais frequentes estão os Enterococcus e Staphylococcus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-77364","number":"77364","sourceNumber":"77364","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A médica residente, responsável pelas internações da clínica médica, é chamada pelo\nmédico do pronto-socorro para realizar internação de determinada paciente. Trata-se de uma\nsenhora, 82 anos, diabética, com sequelas leves de AVC prévio que limitam sua deambulação de\nmodo que permanece grande parte do dia acamada. Filha refere vários tratamentos com\nantibióticos diversos para infecções urinárias diagnosticadas por médico de saúde da família (último\ntratamento há menos de 1 mês). Essa mesma residente havia atendido essa senhora 48h antes no\nseu estágio no PS, devido queixa da filha de que a paciente estava desanimada e permanecendo\nmais tempo na cama. Nesse atendimento ela solicitou um EAS e urocultura, sob a justificativa de\ncontrole de tratamento e liberou a senhora para domicílio. Assim que teve acesso ao resultado, a\nfilha retornou com a mãe ao hospital, sem novas queixas, bastante irritada por ter recebido alta 48h\nantes, sendo então indicada internação pelo médico do PS. Os exames que haviam sido solicitados\nmostravam: EAS (urina rotina): 6 piócitos; nitrito negativo; flora bacteriana aumentada.\nUrocultura:\n\nE. coli multirresistente, sensível apenas à gentamicina. Diante desse quadro, o preceptor desta\nmédica residente, durante a corrida de leitos, deve:","options":{"A":"Explicar que esses exames foram realizados desnecessariamente, que a indicação de\ninternação foi equivocada, e dar alta para a paciente sem nenhum tratamento antibiótico.","B":"Colher nova urocultura, colhida através de sondagem vesical de alívio, e iniciar gentamicina até\nresultado da nova cultura solicitada.","C":"Iniciar gentamicina com dose ajustada para o clearance de creatinina.","D":"Colher nova urocultura, colhida através de sondagem vesical de alívio, e somente iniciar\ngentamicina se confirmada a resistência aos outros antibióticos.","E":"Iniciar meropenem, pois não existe E. coli na comunidade resistente ao meropenem, devido ao\nrisco de insuficiência renal com uso de aminoglicosídeos em idosos diabéticos."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-59063","number":"59063","sourceNumber":"59063","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à infecção do trato urinário assinale a alternativa mais adequada:","options":{"A":"Infecções do trato urinário baixo de repetição são comuns em mulheres jovens; nesse caso, a\ncoleta da urocultura é mandatória para avaliar o patógeno em questão.","B":"Pacientes com pielonefrite já com tratamento em curso devem realizar exames de imagem\nabdominal (ultrassonografia ou tomografia\ncomputadorizada) em caso de recorrência da febre, para\navaliar presença de coleções.","C":"No caso de infecção urinária baixa em mulheres, o patógeno mais comum é a Escherichia coli,\nmas o crescimento de Staphylococcus saprophyticus também deve ser valorizado.","D":"Infecções polimicrobianas são comuns em casos de infecção urinária de repetição.","E":"Questões B e C estão corretas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-59435","number":"59435","sourceNumber":"59435","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo masculino, 50 anos, hipertenso e diabético mal controlado, é atendido\nem consultório de urologista com febre, disúria\ne dor forte durante o exame de toque retal. É\nmedicado com ciprofloxacina 500 mg 2x dia e liberado. Após 36 horas do uso do antibiótico,\nmantém febre elevada, com calafrios e queda do estado geral, sendo reavaliado pelo urologista que\nindica internação hospitalar. É medicado pelo médico do pronto-socorro e internado às 17h. Às 23h\ndo mesmo dia, o médico residente de plantão é chamado e detectou: Paciente prostrado, febril,\ntaquicárdico (120 bpm), PA 180 x 80, taquipneia 38 rpm, SatO2 em ar ambiente 96%. Exames\nsolicitados pelo médico do pronto-socorro: leucócitos 25000 com 10% de bastões, Ureia 130,\ncreatinina 2,5, PCR 120. Gasometria colhida às 23h com ph 7,15 PCO2 25 HCO3 12 lactato10.\n\nMarque a alternativa que melhor se relaciona com o caso:","options":{"A":"Sepse grave por provável abscesso de próstata. Medidas de ressuscitação estratégia \"early\ngoal\", ampliar esquema antibiótico incluindo cobertura para anaeróbios, realizar US próstata de\nurgência e drenagem do abscesso via transretal.","B":"Sepse grave por provável pielonefrite em paciente com nefrolitíase. Medidas de ressuscitação\nestratégia \"early goal\", passar ciprofloxacina\nvenosa, realizar US renal de urgência e desobstrução\ncom cateter duplo J.","C":"Choque séptico por provável abscesso de próstata. Medidas de ressuscitação estratégia \"early\ngoal\", ampliar esquema antibiótico incluindo cobertura para anaeróbios, realizar US próstata de\nurgência e drenagem do abscesso via transretal.","D":"Choque séptico por provável pielonefrite em paciente com nefrolitíase. Medidas de ressuscitação\nestratégia \"early goal\", passar\nciprofloxacina venosa, realizar US renal de urgência e desobstrução\ncom cateter duplo J.","E":"Sepse grave devido indicação inapropriada do antibiótico inicial, evoluindo com Síndrome do\nDesconforto Respiratório Agudo e Disfunção de Múltiplos Órgãos. Prescrever Cefepime e iniciar\nmedidas de ressuscitação estratégia \"early goal\"."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-59033","number":"59033","sourceNumber":"59033","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Quanto às meningites na infância, seus agentes etiológicos e os aspectos de vigilância\nepidemiológica envolvidos é correto afirmar que:","options":{"A":"As gestantes que tiveram contato com pacientes com meningite por Haemophilus influenzae B\nou por meningococo não devem receber\nrifampicina devido aos seus possíveis efeitos\nteratogênicos.","B":"Vinte e quatro horas após o início da antibioticoterapia com ceftriaxona, o paciente com\nmeningite meningocócica não é considerado mais infectante.","C":"A indicação de profilaxia com rifampicina para meningococo é restrita aos contatos íntimos\nintradomiciliares com idade inferior ou igual a cinco anos.","D":"A notificação compulsória das meningites agudas às autoridades municipais de saúde limita-se\nàquelas suspeitas de terem etiologia bacteriana.","E":"A vacina conjugada contra Haemophilus influenzae B não está indicada para lactentes que já\ntiveram meningite por este agente infeccioso."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-43328","number":"43328","sourceNumber":"43328","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente 67 anos, sexo feminino, negra, portadora de Miocardiopatia Dilatada\nBiventricular Grave, Insuficiência Renal\nCrônica ainda não dialítica (em acompanhamento com\nnefrologia), portadora de Marca-passo Cardíaco implantado há cerca de 4 meses em virtude de\nBloqueio Átrio Ventricular Total. Dá entrada no hospital Evangélico após ter recebido alta há cerca\nde 48 horas, de internação cardiológica com duração de 1 semana (poucos dados disponíveis\ndesta internação no prontuário, tanto de história como de exames). Apresenta o seguinte quadro:\nFebre diária, não termometrada, que segundo acompanhantes já havia iniciado mesmo antes da\nprimeira internação, acompanhada de hiporexia progressiva, prostração e adinamia. Nas últimas 24\nhoras apresentou piora clínica com rebaixamento do nível de consciência sendo trazida de volta ao\nhospital. Exame clínico: Febre (38,5°), abertura ocular ao estímulo, movendo os quatro membros,\nporém sem atender comandos, verbalizando poucas palavras incompreensíveis. Rigidez de nuca.\n\nRCR 3t (B3) FC 100 bpm. Ictus desviado para esquerda e para baixo. SSR 3/6 em foco mitral e\ntricúspide. PA 100 x 60 mmHg. Abdome livre. Exames realizados: ECG: átrios em ritmo sinusal e\nventrículos comandados por marca-passo; RX tórax com opacidades nodulares difusas distribuídas\npor ambos os pulmões e de tamanhos diferentes; Laboratório: Hb 9,5 Leucócitos 20.000 (bastões\n15 segmentados 70), plaquetas 65.000, Ureia 300, creatinina 8,0, PCR 120; TC Crânio alterações\ncompatíveis com a idade; Liquor turvo, hipercelular, com predomínio de polimorfonucleares, glicose\nbaixa, proteína elevada. Cultura positiva para estafilococos sensível à oxacilina; Hemocultura (03\namostras) positiva para estafilococos sensível à oxacilina. Quais os exames e condutas principais?","options":{"A":"Avaliação da hematologia e realização de plasmaférese.","B":"lntubação, coleta de aspirado traqueal e vancomicina.","C":"Ecocardiograma transtorácico, retirada do cabo de marca-passo e oxacilina.","D":"Início precoce de oxacilina e coleta de nova amostra de liquor conforme evolução do quadro.","E":"Ecocardiograma Transesofágico e Vancomicina."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-43334","number":"43334","sourceNumber":"43334","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a prevenção da endocardite infecciosa (EI), marque a alternativa INCORRETA:","options":{"A":"Estes são alguns exemplos de pacientes considerados como alto risco de adquirir EI: portadores\nde prótese cardíaca valvar, portadores de\ncardiopatias congênitas, como as do tipo comunicação\ninterventricular (CIV) e comunicação interatrial (CIA) e pacientes com história prévia de\nendocardite.","B":"Devem receber profilaxia antibiótica pacientes de risco elevado para EI e que realizarão\nprocedimentos odontológicos que envolvem a manipulação do tecido gengival.","C":"Não há indicação de profilaxia para procedimentos sem risco de bacteremia.","D":"Deve-se usar o esquema de Ampicilina + gentamicina para pacientes de risco elevado de EI nas\ncirurgias gastrointestinais e geniturinárias.","E":"Não há indicação de profilaxia para pacientes com prolapso mitral sem regurgitação, mesmo\npara cirurgias gastrointestinais e\ngeniturinárias."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-43978","number":"43978","sourceNumber":"43978","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação às infecções bacterianas do sistema nervoso central podemos afirmar,\nexceto:","options":{"A":"No período neonatal, os principais agentes etiológicos responsáveis pelas meningites\nbacterianas são: E. coli, estreptococo do grupo B e Listeria monocytogenes.","B":"No Brasil, a N. meningitidis é o principal agente etiológico das meningites bacterianas fora do\nperíodo neonatal.","C":"Os achados de morfologia do liquor em pacientes com meningite bacteriana incluem\nclassicamente aumento de celularidade com predomínio de polimorfonuclear.","D":"A glicorraquia está diminuída e o seu nível deve ser comparado ao da glicose sanguínea.\n\nGeralmente esse nível é menor que dois terços da concentração da glicose no sangue periférico,\nem condições de normalidade.","E":"A proteinorraquia está geralmente elevada, sendo o valor normal até 40 mg/dl."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-32431","number":"32431","sourceNumber":"32431","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma paciente de 45 anos foi admitida no Pronto-Socorro por rebaixamento de\nconsciência e convulsão. A mesma era\npreviamente hígida até 04 dias antes da admissão; quando\nreferiu cefaleia holocraniana leve, anorexia e adinamia. No dia seguinte, apresentou febre\n(temperatura axilar de 38°C), piora da cefaleia e transtorno de comportamento, caracterizado por\nagressividade e agitação psicomotora. No dia da internação, a paciente despertou muito confusa, e,\nlogo em seguida, apresentou uma crise convulsiva inédita. A mesma manteve-se inconsciente\ndurante a remoção até Pronto-Socorro (cerca de 30 minutos). À admissão, a paciente\n\nencontrava-se torporosa, febril e com hemiparesia direita incompleta. Submetida à tomografia\ncomputadorizada de crânio que revelou\nedema frontotemporal esquerdo com presença de pequena\nhemorragia de permeio. Em seguida, realizou-se punção liquórica, estando o liquor com\ngotejamento rápido e de aspecto levemente hemorrágico e incolor. A análise liquórica revelou 120\ncélulas, 95% linfócitos e 5% de neutrófilos, 2.000 hemácias, proteinorraquia de 80 mg/dl e\nglicorraquia de 55 mg/dl. Diante destes dados, qual o diagnóstico mais provável para este caso?","options":{"A":"Neuro-Behçet.","B":"Meningite tuberculosa.","C":"Aneurisma roto da artéria comunicante anterior.","D":"Meningoencefalite herpética.","E":"Meningite por Listeria."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-32488","number":"32488","sourceNumber":"32488","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É INCORRETO afirmar sobre a Infecção do Trato Urinário (ITU) nas mulheres:","options":{"A":"O risco relativo de ITU aguda aumenta durante as 48 horas após atividade sexual.","B":"O risco de desenvolver segunda ITU é maior que o da primeira, com pelo menos 20% de\nrecorrência em 6 meses de seguimento.","C":"O estriol reduz o tônus muscular e a peristalse ureteral, aumentando o risco de ITU na gestação.","D":"Mulheres com diabetes insulino-dependente têm incidência de ITU de 2 a 4 vezes maior.","E":"Nas mulheres idosas o risco de ITU aumenta substancialmente."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-23120","number":"23120","sourceNumber":"23120","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São fatores de risco para a Infecção de Trato Urinário (ITU) em mulheres, exceto:","options":{"A":"atividade sexual","B":"diabetes mellitus","C":"gestação","D":"uso de sondas vesicais","E":"terapia hormonal"},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8070","number":"8070","sourceNumber":"8070","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nQual o diagnóstico etiológico da síndrome febril?","options":{"A":"Virose.","B":"Insuficiência venosa crônica.","C":"Trombose venosa profunda.","D":"Erisipela verdadeira.","E":"Eritema nodoso."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8071","number":"8071","sourceNumber":"8071","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nNo caso clínico anterior, que fator pode ser considerado determinante para o aparecimento do\nquadro clínico febril?","options":{"A":"Obesidade.","B":"Pernas que incham cronicamente.","C":"Hipertensão arterial.","D":"Problema linfático.","E":"Nenhum item acima."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8072","number":"8072","sourceNumber":"8072","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente obeso, hipertenso controlado com vasodilatadores, alcoolista, não\ndiabético, trabalha 16 horas por dia como\nvendedor em um bar da periferia. Refere ter no final do\ndia pernas que incham e pela manhã estão livres do edema. Há 4 dias, pela tarde, iniciou mal-estar\ngeral caracterizado por dor no corpo, principalmente lombar, associando a dor na cabeça. Algumas\nhoras depois apresentava febre alta e calafrios sendo necessário o agasalhamento. Esta situação\nse seguiu de dor em queimação intensa na perna esquerda, precedida de prurido, e o local se\ntornou avermelhado, em uma grande placa circinada que envolvia a região desde o pé até próximo\ndo joelho. Houve aumento do volume da perna. Refere que surgiram adenopatias inguinais e se\nformaram bolhas, sem sangue, na região eritematosa.\n\nNo caso clínico anterior, o melhor tratamento para a condição diagnosticada é:","options":{"A":"Anorexígenos, caminhadas e abstenção do álcool.","B":"Acrescentar diuréticos à medicação anti-hipertensiva.","C":"Prescrever linfagogos e linfocinéticos.","D":"Penicilina benzatina ou cristalina sob internação.","E":"Nenhum item acima."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8087","number":"8087","sourceNumber":"8087","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São procedimentos considerados de alto risco na recomendação de profilaxia da\nendorcardite infecciosa, exceto:","options":{"A":"próteses valvares cardíacas.","B":"revascularização miocárdica.","C":"cardiopatia congênita cianótica.","D":"shunts sistêmicos pulmonares construídos cirurgicamente.","E":"endocardite bacteriana prévia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8088","number":"8088","sourceNumber":"8088","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A respeito da quimioprofilaxia em casos de meningite bacteriana, é correto afirmar:","options":{"A":"Assegura efeito protetor absoluto e prolongado e, por isso, tem sido adotada como medida\neficaz na prevenção de casos secundários.","B":"Está indicado para qualquer contato de casos de doença meningocócica ou de meningite por\nHaemophilus influenzae.","C":"Também está indicada para o paciente no momento da alta, exceto em casos em que a droga\nutilizada tenha sido a ceftriaxona.","D":"A droga de escolha é a minociclina, que deve ser administrada para todos os contatos\nsimultâneamente.","E":"Para ambas as etiologias, o tempo adequado de utilização da droga é de 48 horas contadas a\npartir do diagnóstico do caso."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-9422","number":"9422","sourceNumber":"9422","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É uma característica do líquor típico na neurotuberculose:","options":{"A":"Pleocitose discreta a moderada e hipoproteinorraquia.","B":"Predomínio linfomocitário e hiperglicorraquia.","C":"Pleocitose aumentada e hipoproteinorraquia.","D":"Hiperglicorraquia e hiperproteinorraquia.","E":"Predomínio linfocitário e hiperproteinorraquia."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8111","number":"8111","sourceNumber":"8111","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente apresentando lesão localizada em uma das coxas, que se caracteriza por ter\neritema, edema, calor local, dor, ser limitada, com febre inferior a 38ºC, traduz:","options":{"A":"Erisipela.","B":"Impetigo.","C":"Foliculite.","D":"Celulite.","E":"Ectima."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-355624","number":"355624","sourceNumber":"355624","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente masculino, 32 anos, é encaminhado ao serviço de emergência com história\naguda de febre alta, mialgias e icterícia. As\ndosagens séricas de ureia e creatinina encontram-se\naumentadas e o médico que o atende suspeita de leptospirose icterohemorrágica. Assinale a opção\nque indica o achado plasmático que apoia o diagnóstico desta hipótese diagnóstica:","options":{"A":"hipercalcemia","B":"hiponatremia","C":"hipernatremia","D":"hipocalemia","E":"hipercalemia"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-363903","number":"363903","sourceNumber":"363903","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Leia o caso clínico a seguir. Paciente, sexo feminino, 38 anos, portadora de diabetes,\nprocurou a urgência do Hospital X,\nrelatando que há 2 dias iniciou com quadro de febre alta, dor no\ncorpo, prostração, artralgia, mialgia, fezes amolecidas e cefaleia holocraniana. Além da hidratação,\na melhor conduta nesse caso é","options":{"A":"pedir hemograma e avaliar no dia seguinte.","B":"solicitar hemograma para avaliação no mesmo dia.","C":"pedir sorologias para Chickungunya, Zika e Dengue.","D":"requisitar exames parasitológicos de fezes."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-353814","number":"353814","sourceNumber":"353814","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"H.M.M, 26 anos, chega em UBS com queixa de dor no corpo, febre e calafrios há 4\ndias. Obtém exame positivo para dengue. O médico que o atendeu explicou sobre os sinais de\nalerta para dengue hemorrágica. A afirmativa que contém esses sinais é:","options":{"A":"Febre alta, mialgia intensa e dor retro-orbital.","B":"Febre alta, elevação da pressão, letargia.","C":"Dor retro-orbital, mialgia e dor abdominal.","D":"Letargia, dor abdominal e hipotensão postural."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-334104","number":"334104","sourceNumber":"334104","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O exame histopatológico convencional com Hematoxilina-Eosina (HE) também é útil na\ndetecção das formas amastigotas Leishmania nos tecidos.","options":{"A":"Possui singular importância para descartar, mas não confirmar outras doenças que fazem parte\ndo diagnóstico diferencial.","B":"Possui singular importância para descartar ou confirmar outras doenças que fazem parte do\ndiagnóstico diferencial.","C":"Não possui singular importância para descartar ou confirmar outras doenças que fazem parte do\ndiagnóstico diferencial.","D":"Possui singular importância para descartar ou confirmar outras doenças que não fazem parte do\ndiagnósticos diferencial."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-334781","number":"334781","sourceNumber":"334781","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, sexo feminino, 38 anos de idade, refere dor e edema em punhos, segundas\nmetacarpofalangeanas, joelhos e tornozelos há 2 meses. Relata que o quadro iniciou com febre de\n38ºC, mialgia, artralgia, fraqueza e mal estar geral que durou 1 semana com regressão desses\nsintomas sendo seguidos do quadro articular. Nega xerostomia, xeroftalmia, fotossensibilidade,\nqueixas respiratórias, cardiovasculares e urinárias. Foi realizado pesquisa de fator reumatoide,\nanticorpos contra antígenos nucleares e sorologia para dengue negativos. De acordo com a\nprincipal hipótese diagnóstica, qual é a conduta a ser adotada?","options":{"A":"Solicitar anti Ro e iniciar hidroxicloroquina e leflunomida.","B":"Solicitar anti CCP e iniciar metrotrexato e anti TNF.","C":"Solicitar sorologia para Chikungynya e iniciar prednisona e hidroxicloroquina.","D":"Solicitar anti DNA e iniciar hidroxicloroquina e ciclofosfamida."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-334113","number":"334113","sourceNumber":"334113","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No caso da Leishmania Visceral (LV), não deve ser realizado o teste de Montenegro\npara fins de diagnóstico, pois:","options":{"A":"na doença ativa o resultado é sempre positivo, independente se há ou não associação com\ncoinfecção LV e síndrome da imunodeficiência adquirida.","B":"na doença ativa o resultado é sempre negativo, dependente se há ou não associação com\ncoinfecção LV e síndrome da imunodeficiência adquirida.","C":"na doença inativa o resultado é sempre negativo, independente se há ou não associação com\ncoinfecção LV e síndrome da imunodeficiência adquirida.","D":"na doença ativa o resultado é sempre negativo, independente se há ou não associação com\ncoinfecção LV e síndrome da imunodeficiência adquirida."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-346443","number":"346443","sourceNumber":"346443","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 07 anos, com história de dor abdominal, vômitos, hematêmese e ausência\nde diurese há 01 dia. Relato de exantema\nmaculopapular difuso, mialgia e febre de 39°C há 05\ndias. À admissão no pronto socorro, criança se apresenta hipoativa, FR 40ipm, SatO? 89%, em ar\nambiente, dispnéia com estertores crepitantes em bases de AHT (ambos hemitórax), PA\n70x30mmHg, FC 165bpm, tempo de enchimento capilar de 05 segundos e hepatomegalia dolorosa\na 3cm abaixo do rebordo costal direito. Quais os diagnósticos mais adequados?","options":{"A":"Dengue e Choque Cardiogênico;","B":"Zika e Choque Cardiogênico;","C":"Dengue e Choque Hipovolêmico/Hemorrágico;","D":"Zika e Choque Hipovolêmico/Hemorrágico."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-302877","number":"302877","sourceNumber":"302877","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O surgimento das doenças emergentes está relacionado a adaptações dos agentes\npatogênicos aos seus hospedeiros e a mudanças nas relações entre eles. Sobre esses aspectos,\nassinale a alternativa correta:","options":{"A":"Os vírus que têm DNA como um médio em sua sequência de replicação não têm polimerase, o\nque os torna mais sujeitos a mutações.","B":"Rearranjo entre poliovírus vacinal atenuado e outros enterovírus circulantes foi responsável por\nalguns surtos de poliomielite.","C":"Recombinação com vírus de animais foi responsável pela pandemia de influenza de 1918.","D":"O Mudanças ecológicas e ambientais aumentaram o contato com o roedor hospedeiro e\nprecipitaram o surgimento da infecção pelo Hantavírus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-294303","number":"294303","sourceNumber":"294303","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O tratamento da malária visa atingir o Plasmodium em pontos-chave de seu ciclo\nevolutivo. Nas infecções por P. vivax, as 8-aminoquinoleínas (primaquina ou tafenoquina) são\nutilizadas para prevenir recaídas devido à sua ação contra o","options":{"A":"esporozoíto.","B":"hipnozoíto.","C":"merozoíto.","D":"trofozoíto."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-308279","number":"308279","sourceNumber":"308279","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O termo leishimaniose engloba múltiplas síndromes clinicas. As mais notáveis são\nvisceral, cutânea e mucosa, que resulta de\ninfecção de macrófagos pelo sistema reticuloendotelial,\nna derme e na mucosa nasofaríngea, respectivamente. Sobre a leishimaniose, responda as\nquestões abaixo: Sobre a doença é verdadeiro afirmar:","options":{"A":"A doença é transmitida por vetor ligado a um protozoário intracelular obrigatório.","B":"É uma doença endêmica em áreas focais de mais de 90 países tropicais e subtropicais.","C":"Por volta de 20 espécies de leishimanias causam doenças em humanos.","D":"Todas as alternativas estão corretas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-308280","number":"308280","sourceNumber":"308280","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O termo leishimaniose engloba múltiplas síndromes clinicas. As mais notáveis são\nvisceral, cutânea e mucosa, que resulta de\ninfecção de macrófagos pelo sistema reticuloendotelial,\nna derme e na mucosa nasofaríngea, respectivamente. Sobre a leishimaniose, responda as\nquestões abaixo: Sobre as manifestações clínicas da doença é verdadeiro afirmar:","options":{"A":"O termo visceral engloba diversos sintomas podendo ser agudos, crônicos e com tempos\ndiversos de manifestação.","B":"A manifestação clássica da doença prolongada é a febre e caquexia.","C":"A manifestação inicial da lesão nasal se dá por sintomas atípicos como epistaxe com eritema e\nedema de mucosa.","D":"Todas as alternativas estão corretas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-315840","number":"315840","sourceNumber":"315840","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As manifestações pouco usuais ocorrem em de indivíduos coinfectados pela\nleishmaniose e pelo HIV. Aproximadamente,\n10% a 16% dos casos, mas a maioria delas é\nconhecida há décadas em pacientes imunocompetentes. Sobre isso, podemos indicar como correto\nque:","options":{"A":"Achados não usuais não podem ser observados nos pacientes coinfectados, como o encontro\nde Leishmania spp. em pele íntegra e sobrepondo\nlesão de sarcoma de Kaposi ou em lesões de\nHerpes simplex e Herpes-zóster.","B":"Achados não usuais podem ser observados nos pacientes coinfectados, como o encontro de\nLeishmania spp. em pele íntegra e sobrepondo lesão de sarcoma de Kaposi ou em lesões de\nHerpes simplex e Herpes-zóster.","C":"Achados não usuais podem ser observados nos pacientes coinfectados, como o encontro de\nLeishmania spp. em pele íntegra e sobrepondo lesão de sarcoma de Kaposi, nunca em lesões de\nHerpes simplex e Herpes-zóster.","D":"Achados não usuais podem ser observados nos pacientes coinfectados, como o encontro de\nLeishmania spp. em pele íntegra e não sobrepondo lesão de sarcoma de Kaposi ou em lesões de\nHerpes simplex e Herpes-zóster."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-318003","number":"318003","sourceNumber":"318003","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A maior parte dos casos graves de dengue em pediatria ocorre pelo extravasamento\nplasmático, sendo imprescindível no tratamento uma\nreposição volêmica criteriosa. Em relação ao\ntratamento de dengue em pediatria:","options":{"A":"Para os casos classificados no grupo A, é orientado hidratação oral em ambiente hospitalar. O\nvolume total a ser oferecido é baseado na regra de Holliday-Segar acrescido de reposição de\npossíveis perdas de 3%.","B":"Para os casos classificados no grupo A, 1/3 da hidratação oral prescrita, deve ser oferecida na\nforma de soro de reidratação oral e 2/3 na forma de água, sucos e chás.","C":"Para os casos classificados no grupo C, deve ser realizado uma reposição volêmica endovenosa\nimediata, com 20 ml/kg de soro fisiológico na primeira hora.","D":"Para os casos classificados no grupo D, deve-se iniciar imediatamente fase rápida de expansão\nparenteral com solução salina isotônica no volume de 10 ml/kg em 20 minutos, podendo ser\nrepetida por até 3 vezes, dependendo da avaliação clínica."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-311973","number":"311973","sourceNumber":"311973","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Escolar de oito anos apresentou, há sete dias, quadro de febre elevada (T.ax: 39ºC),\ncefaleia, hiperemia conjuntival e mialgia, tendo sido levado à emergência. Exame físico naquela\ndata: T.ax: 38,9ºC, FR: 48 irpm. EC: 110bpm, PA: 110 x 75 mmHg. Exames laboratoriais: Hb 12,5\ng/dl, Ht: 34%, leucócitos 7.700/mm³, linfócitos 35% e plaquetas: 190.000/mm³. Foi liberado com\nprescrição de hidratação oral e antitérmicos. Três dias depois, retornou à emergência, afebril,\nprostrado, com vômitos persistentes e dor abdominal. Exame físico T.ax 36,2ºC, FR 52 irpm,\nFC:120 bpm, PA: 85 x 55mmHg. Exames laboratoriais: Hb 12g/dl, Ht: 36, leucócitos 4.200/mm³,\nlinfócitos 30% e plaquetas: 110.000/mm³. Considerando a hipótese diagnóstica de dengue, o dado\ndentre os descritos, que indica internação imediata deste paciente, é:","options":{"A":"Hipotermia.","B":"Dor abdominal.","C":"Leucopenia.","D":"Plaquetopenia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-277406","number":"277406","sourceNumber":"277406","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 26 anos de idade procurou o pronto-socorro por quadro de febre alta,\nnáuseas e dores pelo corpo há seis dias. Referia viagem em março de 2018 ao interior de São\nPaulo para realização de trilhas e visitas a cachoeiras. Ao exame, encontrava-se corado, hidratado,\nictérico ++++/4, febril (38,0 ºC), com frequência cardíaca de 65 bpm, PA de 100 x 60 mmHg e FR\nde 22 ipm. Assinale a alternativa que apresenta o diagnóstico provável:","options":{"A":"leptospirose","B":"febre amarela","C":"hepatite A","D":"dengue"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-258207","number":"258207","sourceNumber":"258207","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Quanto ao diagnóstico laboratorial de dengue:","options":{"A":"O teste NS1 permite a identificação do sorotipo viral.","B":"O isolamento viral deve ser realizado a partir do sexto dia de doença.","C":"A sorologia deve ser solicitada até o quinto dia da doença.","D":"O anticorpo IgG pode ser detectado precocemente na infecção secundária."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-257758","number":"257758","sourceNumber":"257758","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A malária é uma protozoose que representa um grave problema de saúde pública no\nmundo. Sobre os aspectos clínicos e epidemiológicos que implicam no seu desenvolvimento:","options":{"A":"A doença não confere imunidade esterilizante.","B":"O período de paroxismos deve-se ao ciclo esporogônico do plasmódio na hemácia.","C":"O quadro clínico independe do plasmódio infectante.","D":"A doença é causada pela picada da fêmea anofelina contendo gametócitos na saliva."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-254226","number":"254226","sourceNumber":"254226","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"\"Ao menos 38 macacos morreram por febre amarela de julho de 2019 a 8 de janeiro\ndeste ano e mais de 1 mil mortes suspeitas\nde primatas foram investigadas, de acordo com um\nboletim epidemiológico divulgado nesta quarta-feira (15) pelo Ministério da Saúde.\" (PORTAL G1,\n15 de janeiro de 2020). A respeito da febre amarela, é CORRETO afirmar:","options":{"A":"O acometimento hepático leva, tipicamente, a aumento de enzimas canaliculares, com\ntransaminases normais.","B":"Tem como sinal patognomônico o sinal de Faget ou dissociação pulso-temperatura.","C":"Tem como diagnóstico diferencial importante a síndrome de Weil.","D":"Sua vacina é segura mesmo em indivíduos imunodeprimidos."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-234358","number":"234358","sourceNumber":"234358","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"De acordo com o Guia de Vigilância em Saúde (2019), paciente com quadro febril\n(acima de 38ºC), mialgia, cefaleia, sinais\ne sintomas de insuficiência respiratória aguda, de etiologia\nnão determinada, na primeira semana da doença, ou paciente com enfermidade aguda,\napresentando quadro de insuficiência respiratória aguda, com evolução para óbito na primeira\nsemana da doença. Esses são critérios estabelecidos para a definição de caso suspeito de:","options":{"A":"Síndrome cardiopulmonar por hantavírus.","B":"Síndrome gripal aguda.","C":"Endocardite infecciosa.","D":"Estafilococcia."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-232291","number":"232291","sourceNumber":"232291","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A leishmaniose visceral ocupa o segundo e o quarto lugar em mortalidade e morbidade,\nrespectivamente, dentre as doenças tropicais. É uma zoonose muito presente em nosso meio. Essa\ndoença:","options":{"A":"Acomete principalmente crianças menores de 10 anos de idade e do sexo masculino.","B":"Tem os mosquitos como a principal fonte de infecção (\"reservatórios\") na área urbana.","C":"Apresenta, com frequência, hepatoesplenomegalia, febre contínua e ganho de peso acima do\nnormal.","D":"Tem achados laboratoriais característicos: leucocitose, neutrofilia, hipoalbuminemia e\ntrombofilia."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-232292","number":"232292","sourceNumber":"232292","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Entre os anos de 2003 e 2014, os casos de malária entre crianças e adolescentes, no\nBrasil, representaram cerca de 47% do total registrado. Qual é a espécie que tem maior prevalência\nno Brasil?","options":{"A":"Plasmodium vivax.","B":"Plasmodium falciparum.","C":"Plasmodium malariae.","D":"Plasmodium ovale."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-232301","number":"232301","sourceNumber":"232301","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Leia o caso clínico a seguir. Criança escolar com febre intensa há quatro dias, com\nrelato de exantema inespecífico, prurido,\ncom dor e edema nas articulações. Nesse caso, qual é o\ndiagnóstico desta criança?","options":{"A":"Dengue.","B":"Chikungunya.","C":"Zika vírus.","D":"Vírus influenza."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-210544","number":"210544","sourceNumber":"210544","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A Febre Amarela é uma doença endêmica nas áreas de florestas tropicais da América\ndo Sul e da África e pode ocorrer sob a\nforma de surtos e epidemias com impacto na Saúde\nPública. Sobre a enfermidade, assinale a alternativa correta.","options":{"A":"O quadro clínico é assintomático ou oligossintomático em aproximadamente 50% dos casos.","B":"Na forma moderada, após 5 a 6 dias de período de incubação, surgem a febre alta e o sinal de\nFaget.","C":"Na forma maligna, ocorre toxemia abrupta, icterícia, hemorragia e encefalopatia, com involução\ndos sintomas na terceira semana.","D":"O diagnóstico pode ser confirmado por detecção de antígenos virais e do DNA viral.","E":"Não é recomendada a vacinação de pessoas vivendo fora de áreas endêmicas, uma vez que o\nrisco da vacina suplanta seus benefícios."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-217032","number":"217032","sourceNumber":"217032","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação à infecção pelo vírus Zika, assinale a alternativa correta.","options":{"A":"A febre, quando presente, é de pequena intensidade e de curta duração.","B":"A conjuntivite é infrequente nesses pacientes.","C":"Manifestações neurológicas são típicas somente na transmissão vertical.","D":"Edema articular é comum e incapacitante.","E":"O exantema é de padrão craniocaudal não pruriginoso."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-210567","number":"210567","sourceNumber":"210567","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Acerca da doença de Chikungunya, assinale a alternativa correta.","options":{"A":"As gestantes apresentam pior prognóstico e há alto risco de transmissão vertical pré-parto.","B":"A dor articular é geralmente assimétrica e acomete preferencialmente as extremidades.","C":"Complicações hemorrágicas são frequentes, mas a mortalidade é baixa.","D":"A fase crônica caracteriza-se por persistência da dor articular por mais de 3 meses.","E":"O isolamento viral é o método diagnóstico padrão-ouro, podendo ser detectado até 4 dias de\ninfecção."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-217000","number":"217000","sourceNumber":"217000","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Ocasionalmente, a insuficiência renal aguda pode evoluir com hipocalemia, refletindo\nlesão específica das células do túbulo fino\nascendente da alça de Henle, o que pode ser observado\nem qual das seguintes patologias?","options":{"A":"Febre amarela.","B":"Bexiga neurogênica.","C":"Leptospirose.","D":"Síndrome da lise tumoral.","E":"Síndrome hemolítica-urêmica."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-205604","number":"205604","sourceNumber":"205604","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nos últimos 50 anos, a incidência de dengue aumentou 30 vezes, expandindo-se sobre\na geografia de novos países, e na presente\ndécada, para pequenas cidades e áreas rurais. Três\nfases clínicas podem ocorrer: febril, crítica e de recuperação. Sobre isso, assinale a alternativa\nINCORRETA:","options":{"A":"A infecção pelo vírus da dengue pode ser assintomática ou sintomática. Quando sintomática,\ncausa uma doença sistêmica e dinâmica, de amplo\nespectro clínico, variando desde formas\noligossintomáticas até quadros graves, possíveis de evoluir a óbito.","B":"Na fase febril, a primeira manifestação é a febre com duração de dois a sete dias, geralmente\nalta (39° a 40°C), de início abrupto, associada\nà cefaleia, astenia, mialgia, artralgia e dor\nretroorbitária.","C":"O exantema, presente em 50% dos casos, é predominantemente do tipo máculo-papular,\natingindo face, tronco e membros de forma\naditiva, não poupando plantas dos pés e palmas das\nmãos, podendo se apresentar sob outras formas, com ou sem prurido, frequentemente no\ndesaparecimento da febre.","D":"A fase crítica pode se apresentar em alguns pacientes, podendo evoluir para as formas graves,\nrazão porque medidas diferenciadas de manejo\nclínico e observação devem ser adotadas\nimediatamente. Esta fase tem início com o aumento da febre, entre o primeiro e o sétimo dia do\ninício da doença, acompanhada do surgimento dos sinais de alarme e/ou gravidade."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-205615","number":"205615","sourceNumber":"205615","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção pelo vírus da dengue pode ser assintomática ou sintomática, mas os casos\ngraves são caracterizados por sangramento\ngrave, disfunção grave de órgãos ou extravasamento\ngrave de plasma. Após as 24-48 horas da fase crítica, uma reabsorção gradual do que se havia\nextravasado para o compartimento extravascular ocorrerá nas 48-72 horas seguintes. Sendo\napenas INCORRETO o seguinte:","options":{"A":"O choque ocorre quando um volume crítico de plasma é perdido pelo extravasamento, o que\ncostuma ocorrer entre o 4° e o 5° dia, no intervalo de 3 a 7 dias de doença, geralmente precedido\npor sinais de alarme.","B":"São sinais de choque: pulso lento e fraco; diminuição da pressão arterial; extremidades frias;\ndemora no enchimento capilar; pele seca e agitação. Alguns pacientes ainda podem apresentar\nmanifestações neurológicas, como convulsões e irritabilidade.","C":"O choque é de curta duração e pode levar ao óbito em um intervalo de 12 a 24 horas; ou à\nrecuperação rápida, após terapia antichoque apropriada.","D":"O choque prolongado e a consequente hipoperfusão de órgãos resultam no comprometimento\nprogressivo destes, bem como em acidose\nmetabólica e coagulação intravascular disseminada.\nIsto, por sua vez, leva a hemorragias graves, causando diminuição de hematócrito em choque\ngrave."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-214932","number":"214932","sourceNumber":"214932","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os elementos clínicos laboratoriais que sugerem diagnóstico de dengue hemorrágica/\nsíndrome de choque da dengue são:","options":{"A":"dor abdominal intensa e contínua, vômitos persistentes, hipotensão postural e/ou lipotimia","B":"vômitos volumosos, leucocitose, plaquetose e hemoconcentração","C":"dor abdominal, leucopenia, plaquetopenia e hemodiluição","D":"prurido, leucopenia, anemia e hemodiluição"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216440","number":"216440","sourceNumber":"216440","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"J.J.G., 42 anos, morador de uma área de alagamento, procura atendimento referindo\nfebre alta com calafrios, mialgia,\nprincipalmente nas panturrilhas, cefaleia e hiperemia conjuntival há\n1 dia. Exame físico mostra linfadenopatia cervical, hepatomegalia e esplenomegalia. Hemograma\nmostrou leucocitose com desvio para a esquerda e plaquetopenia. O diagnóstico mais provável é:","options":{"A":"Febre amarela.","B":"Actinomicose.","C":"Infecção por H1N1.","D":"Leptospirose."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-214924","number":"214924","sourceNumber":"214924","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a situação epidemiológica de doenças emergentes, pode-se afirmar que:","options":{"A":"a transmissão da febre chicungunya não ocorre por contato pessoa a pessoa","B":"a febre hemorrágica pelo vírus ebola é transmitida pelo ar ou pela água","C":"todos os anos ocorrem epidemias de influenza nas estações frias nos países do hemisfério norte\ne do hemisfério sul","D":"a vacina contra influenza tem a mesma composição desde sua síntese, na década de\n1960"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-201655","number":"201655","sourceNumber":"201655","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Na investigação de dengue na infância:","options":{"A":"A ausência de alterações no hemograma (hemoconcentração e/ou plaquetopenia), após o\nterceiro dia de febre, exclui o diagnóstico de dengue e, portanto, outros exames devem ser\nrealizados em busca do diagnóstico definitivo.","B":"A presença de vômitos persistentes em lactentes não deve ser considerada como sinal de alerta\npara dengue grave nesta faixa etária, pois eles apresentam esses vômitos por diversos motivos,\ncomo doença do refluxo gastroesofágico e alergia ao leite de vaca.","C":"O isolamento viral, realizado a partir do sétimo dia da febre, é importante ferramenta para\nacompanhamento epidemiológico da doença, mas o seu\nalto custo inviabiliza a realização em todos\nos casos.","D":"A prova do laço, em crianças, deve ser realizada durante três minutos e é importante lembrar\nque ela pode ser negativa durante o choque."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215419","number":"215419","sourceNumber":"215419","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"De acordo com o tempo previsto para a chegada à unidade de terapia intensiva na\nsuspeita de febre amarela grave algumas\nmedidas podem ser iniciadas na unidade básica e\nmantidas durante o tempo de transporte, especialmente as relacionadas a coagulopatias e\nhemorragias. A avaliação deve incluir análise dos resultados das provas de coagulação, indicativas\nde maior gravidade. Estando de acordo com o seguinte item:","options":{"A":"A coagulopatia observada na febre amarela não decorre da diminuição de produção de fatores\nde coagulação, podendo estar associada à\nCoagulação Intravascular Disseminada (CIVD).","B":"A coagulopatia observada na febre amarela decorre da diminuição de produção de fatores de\ncoagulação por comprometimento hepático, não podendo estar associada à Coagulação\nIntravascular Disseminada (CIVD).","C":"A coagulopatia observada na febre amarela decorre do aumento da produção de fatores de\ncoagulação por comprometimento hepático, podendo estar associada à Coagulação Intravascular\nDisseminada (CIVD).","D":"A coagulopatia observada na febre amarela decorre da diminuição de produção de fatores de\ncoagulação por comprometimento hepático, podendo estar associada à Coagulação Intravascular\nDisseminada (CIVD)."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215446","number":"215446","sourceNumber":"215446","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O vírus da febre amarela é mantido na natureza por transmissão entre primatas não\nhumanos (PNH) e mosquitos silvestres arbóreos,\nprincipalmente dos gêneros Haemagogus e\nSabethes (no Brasil). Não sendo adequado o seguinte conceito:","options":{"A":"Na região extra-amazônica, períodos epidêmicos são registrados ocasionalmente,\ncaracterizando a reemergência do vírus no País.","B":"O padrão temporal de ocorrência é sazonal, com a maior parte dos casos incidindo entre\ndezembro e maio.","C":"Os surtos que ocorrem com periodicidade irregular, quando o vírus encontra condições\nfavoráveis para a transmissão (elevadas temperatura e pluviosidade).","D":"As condições favoráveis não seriam alta densidade de vetores e hospedeiros primários;\npresença de indivíduos suscetíveis; baixas\ncoberturas vacinais; eventualmente, novas linhagens do\nvírus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-215464","number":"215464","sourceNumber":"215464","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A conduta na suspeita de febre amarela após a avaliação inicial depende dos achados\nclínicos e laboratoriais. O acompanhamento ambulatorial pode ser feito para pacientes nas\nseguintes condições listadas abaixo; indique a alternativa inadequada:","options":{"A":"Formas clínicas leves ou moderadas.","B":"Paciente em regular estado geral, hidratado ou com desidratação leve, sem vômitos, sem\nhistória ou sinais de hemorragias, com nível de consciência normal.","C":"Exames laboratoriais normais ou com alterações discretas no hemograma (leucopenia,\nplaquetopenia acima de 150.000, hemoconcentração <10% do valor de referência).","D":"Com transaminases menores que cinco vezes o limite superior da normalidade."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-187559","number":"187559","sourceNumber":"187559","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O guia para Diagnóstico e Manejo Clinico da Dengue - Adulto e criança - do Ministério\nda Saúde (BRASIL, 2016), apresenta orientações\npara hidratação oral em crianças menores de 13\nanos de idade, levando em consideração, o peso da criança para cálculo do volume a ser\noferecido. Sendo 1/3 do volume total de soro de reidratação oral (SRO) e 2/3 do volume total em\noutros líquidos. Para crianças.","options":{"A":"até 15Kg, realizar cálculo com 80ml/kg/dia.","B":"de 10 à 20kg, realizar cálculo com 130ml/kg/dia.","C":"acima de 20kg, realizar cálculo com 80ml/kg/dia.","D":"até 10kg, realizar cálculo com 60ml/kg/dia."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-186483","number":"186483","sourceNumber":"186483","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, 22 anos, procura atendimento na unidade de saúde - ESF Liberdade,\nreferindo que há um dia iniciou quadro de dor\nmuscular, cefaleia, prurido e vermelhidão no corpo, e\nhoje pela manhã evoluiu com irritação ocular, dores articulares moderadas. Ao exame físico, a\nmédica de Família e Comunidade indentificou: - Temperatura axilar - 37,7°C; - Exantema no corpo\ne conjuntivite biocular; - Leve edema articular. Avaliando o caso apresentado, a hipótese\ndiagnóstica mais provável é:","options":{"A":"Febre Amarela.","B":"Zika.","C":"Chikungunya.","D":"Dengue."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-174141","number":"174141","sourceNumber":"174141","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Febre alta (38 a 40 °C) de início abrupto, calafrios, cefaleia, mialgia, sufusão\nhemorrágica conjuntival e secreção purulenta, dor\nabdominal, anorexia, náusea, vômito, diarreia,\ntosse, faringite e exantema maculopapular pré-tibial são sinais clínicos da","options":{"A":"leptospirose.","B":"leishmaniose.","C":"malária.","D":"rickettsiose."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-174146","number":"174146","sourceNumber":"174146","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Febre baixa (menor de 38,5°C) com duração de um a dois dias; exantema de início\nprecoce, com progressão craniocaudal,\ndisseminado e acompanhado de prurido; dor muscular leve;\ndor articular de leve a moderada, com edema nas pequenas articulações de mãos e pés; hiperemia\nconjuntival. Este quadro clínico é indicativo de:","options":{"A":"Chikungunya.","B":"Dengue.","C":"Febre amarela.","D":"Zika vírus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157056","number":"157056","sourceNumber":"157056","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Na febre hemorrágica da dengue, quais os achados clínicos e laboratoriais mais\nfrequentes?","options":{"A":"Hemoconcentração, plaquetose, leucopenia, febre, adenomegalia, ascite e petéquias.","B":"Plaquetopenia, leucocitose, febre, adenomegalia, ascite e VHS aumentada.","C":"Prova do laço negativa, febre, artralgia, plaquetopenia e dores abdominais.","D":"Hemoconcentração, prova do laço positiva, derrames cavitários, plaquetopenia, febre e\nsangramentos."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-160507","number":"160507","sourceNumber":"160507","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 56 anos apresenta-se há 2 dias com quadro de febre alta, mialgia, dor\nretrorbitária, dor abdominal de forte intensidade, náuseas e vômitos. Ao exame físico, a palpação\ndo abdome é dolorosa, sem descompressão brusca positiva, PA 104/62 mmHg, e temperatura\n37,5ºC. O caso em questão é considerado","options":{"A":"suspeita de dengue, sem sinais de alarme. A conduta é aguardar resultados dos exames\nlaboratoriais; se normais, hidratação por via oral e acompanhamento ambulatorial.","B":"suspeita de dengue, com sinais de alarme. A conduta é internação hospitalar por pelo menos 48\nhoras, com reposição volêmica inicial de 10 a 20 mL/kg/h.","C":"dengue confirmada, sem sinais de alarme. A conduta é aguardar resultados dos exames\nlaboratoriais; se normais, hidratação por via\nendovenosa por 6 horas e alta para acompanhamento\nambulatorial.","D":"dengue confirmada, com sinais de alarme. A conduta é reposição volêmica inicial de 10 mL/kg/h,\nenquanto aguarda resultados dos exames; se hematócrito normal, acompanhamento ambulatorial."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157349","number":"157349","sourceNumber":"157349","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Para um paciente de 3 anos, sexo feminino, 15 quilos, com diagnóstico de Dengue, que\napresenta ao exame físico petequias, sinal de Hermann presente, prova do laço positiva, sem sinais\nde alarme ou choque, qual deverá ser a conduta?","options":{"A":"Expansão rápida de solução isotônica com volume de 300 ml e internação em leito de UTI.","B":"Reposição volêmica de 300 ml de soro fisiológico em 2 horas, solicitação de hemograma\ncompleto, dosagem de albumina e transaminases, e internação em leito de enfermaria.","C":"Prescrição de 1.500 ml de líquidos ao dia, sendo que 500 ml desse volume deverá ser na forma\nde soro de reidratação oral, prescrição de\nparacetamol e retorno no dia da melhora da febre ou\nretorno precoce havendo sinais de alarme.","D":"Prescrição de 3.000 ml de líquidos ao dia, sendo que 1.000 ml desse volume deverá ser na\nforma de soro de reidratação oral,\nprescrição de paracetamol e retorno no dia da melhora da febre\nou retorno precoce havendo sinais de alarme.","E":"Solicitação de hemograma completo e prescrição de soro de reidratação oral de 150 a 200 ml\npara ser ingerido entre 4 e 6 horas até o resultado do hemograma."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-157342","number":"157342","sourceNumber":"157342","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em uma criança de 5 anos que há 3 semanas apresenta febre intermitente de picos de\n39ºC, associada com emagrecimento, hepatoesplenomegalia maciça, anemia, leucopenia,\ntrombocitopenia, hiperglobulinemia e hipoalbuminemia, o diagnóstico mais provável é:","options":{"A":"Lúpus eritematoso sistêmico.","B":"Leucemia linfoide aguda.","C":"Leucemia mieloide aguda.","D":"Anemia falciforme.","E":"Leishmaniose visceral."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150279","number":"150279","sourceNumber":"150279","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma das hipóteses aceitas sobre a chegada da febre do zika vírus no Brasil vincula-se:","options":{"A":"À vinda de imigrantes africanos para o estado da Bahia em 2014.","B":"Ao campeonato mundial de canoagem, realizado no Rio de Janeiro em agosto de 2014, com a\npresença de participantes de várias ilhas do Pacífico: Polinésia Francesa, Micronésia, Ilhas Cook e\nIlha de Páscoa.","C":"Aos jogos pré-olímpicos realizados no Rio de Janeiro em 2014, quando houve a presença de\nparticipantes de todos os continentes.","D":"Ao campeonato de patinação ocorrido em setembro de 2014 na cidade de Porto Alegre (RS),\nquando houve a presença de participantes da África e da Ásia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150720","number":"150720","sourceNumber":"150720","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à doença causada pelo vírus da zika, no Brasil,","options":{"A":"É considerado caso suspeito aquele que apresenta febre acompanhada de dois ou mais dos\nseguintes sinais e sintomas: exantema máculo-papular, ou náuseas/vômitos, ou milagia/artralgia.","B":"É considerada doença de notificação não compulsória.","C":"Há confirmação de transmissão autóctone.","D":"Deve-se comunicar sua suspeita às secretarias municipais e estaduais em até 15 dias para\ninvestigação."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150695","number":"150695","sourceNumber":"150695","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Desde 2015, casos de infecção pelo vírus da zika têm sido notificados no Brasil. Essa\nquestão tem preocupado profissionais e órgãos de saúde no país. Sobre esta infecção, sabe-se\nque:","options":{"A":"A doença é autolimitada, dura de quatro a sete dias, se inicia com rash cutâneo ascendente,\nfebre alta, artralgia e conjuntivite purulenta, e\napresenta 50% dos casos assintomáticos.","B":"O diagnóstico é confirmado por RT-PCR em sangue, urina ou saliva, entretanto é limitado por\nreações cruzadas com outros retrovírus.","C":"O diagnóstico diferencial entre a infecção pelo vírus da zika, dengue e chikungunya é\nessencialmente clínico, sendo os sintomas\ngeralmente mais intensos na infecção pelo vírus da zika.","D":"O paciente com diagnóstico de infecção pelo vírus da zika, que for sexualmente ativo, deve ser\ninformado sobre o risco de transmissão sexual e orientado a utilizar preservativo."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-150200","number":"150200","sourceNumber":"150200","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A partir de 2014, o Brasil passou a utilizar a nova classificação de dengue cuja\nabordagem enfatiza que é uma doença única,\ndinâmica e sistêmica. Baseado no \"Manual de\ndengue: diagnóstico e manejo clínico adulto e criança\", do Ministério da Saúde, 5° edição, 2016,\nconstitui sinal de alarme durante a avaliação da criança com quadro clínico de dengue, a seguinte\nconstatação:","options":{"A":"Sangramento de mucosa.","B":"Redução súbita do hematócrito.","C":"Prova do laço positiva.","D":"Hipertensão arterial."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127991","number":"127991","sourceNumber":"127991","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 16 anos com cefaléia e congestão nasal há 5 dias. No dia do atendimento,\nevoluiu com edema de olho direito, cefaléia\nfrontal à direita e vômitos. O exame físico revela\npaciente letárgico, mas despertável, proptose do olho direito e congestão nasal. A nuca está livre,\ne\nnão há outra alteração no exame físico. O exame a ser realizado, nesse caso, será:","options":{"A":"Punção lombar","B":"Ressonância magnética do cérebro e dos seios da face","C":"Cultura de aspirado em orofaringe","D":"Painel toxicológico"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-141547","number":"141547","sourceNumber":"141547","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção urinária tem como bactéria mais frequente:","options":{"A":"Enterococcus faecalis.","B":"Staphylococcus saprophyticus.","C":"Escherichia coli.","D":"Klebsiella sp."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137042","number":"137042","sourceNumber":"137042","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, de 32 anos, dá entrada no pronto-socorro com quadro de\nfebre, calafrios e queda do estado geral. Relata que esse quadro clínico começou há cerca de 24\nhoras. Ao exame físico, encontra-se com sudorese, hipotensão e icterícia, sendo o sinal de\nGiordano positivo. A principal hipótese diagnóstica é:","options":{"A":"Cirrose hepática de etiologia viral.","B":"Litíase vesicular.","C":"Intoxicação medicamentosa com lesão hepática.","D":"Sepsis de etiologia infecciosa, provavelmente infecção do trato urinário."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127354","number":"127354","sourceNumber":"127354","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Existem diversos mecanismos que causam lesão da célula bacteriana, e que, por sua\nvez, ou causa lise celular ou mesmo\nimpedimento de sua reprodução. Esses mecanismos de ação\ndos antimicrobianos apresentam grande importância no momento da escolha do antimicrobiano.\n\nDentre os listados abaixo, qual deles causa lesão no DNA bacteriano?","options":{"A":"Beta-lactâmicos.","B":"Carbamapenemas.","C":"Quinolonas.","D":"Macrolídeos."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127696","number":"127696","sourceNumber":"127696","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As infecções bacterianas da pele podem representar um processo patogênico cutâneo\nprimário ou uma manifestação cutânea secundária à infecção inicial de um outro órgão. Nas\npiodemites,","options":{"A":"A erisipela é uma forma de celulite superficial, causada por estafilococos e raramente por\nestreptococos, que apresenta instalação lenta e é pouco sintomática.","B":"O furúnculo é uma infecção estreptocócica do folículo piloso e da glândula sebácea anexa. Ao\nconjunto de furúnculos dá-se o nome de micetoma.","C":"A síndrome da pele escaldada estafilocócica é causada por exotoxinas esfoliativas do S. aureus\nna qual o sinal de Zileri está presente.","D":"Os estafilococos são os responsáveis pelo impetigo bolhoso, enquanto, no não bolhoso,\nisolam-se misturas de estafilococos e estreptococos."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-129916","number":"129916","sourceNumber":"129916","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, de 40 anos, vendedora, procurou atendimento médico para\navaliação de rotina. Paciente sem queixas. Nega comorbidades. Apresentava exame físico normal.\nForam solicitados hemograma, glicemia de jejum, lipidograma, ureia, creatinina, alanina\naminotransaminase, aspartato aminotransaminase, exame simples de urina e urocultura. Paciente\nretornou após uma semana com o resultado dos exames. Persistia assintomática. Os exames\napresentaram todos os resultados normais, exceto a urocultura que mostrou crescimento de\nEscherichia coli produtora de Betalactamase de Espectro Estendido (ESBL). O antibiograma\nindicou sensibilidade a amicacina, colistina, piperacilina-tazobactam e carbapenêmicos. Qual a\nconduta indicada para este paciente?","options":{"A":"Internação e início de antibioticoterapia endovenosa com meropenem 1 g, de 8 em 8 horas.","B":"Internação e início de antibioticoterapia endovenosa com meropenem em dose dobrada.","C":"Início de antibioticoterapia endovenosa com amicacina 1 g, uma vez ao dia, em regime\nambulatorial.","D":"Orientação à paciente de retornar, caso apresente sintomas, e não iniciar tratamento."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127958","number":"127958","sourceNumber":"127958","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um paciente de 6 anos, com quadro de febre alta, cefaleia e vômitos, é internado para\nobservação. Ao exame físico, nota-se rigidez da nuca. A punção lombar mostra diplococo Gram\nnegativos. Dá-se início à antibioticoterapia. O processo evolui com petéquias e choque. A criança\ntem 2 irmãos, de 4 e 2 anos. Conduta adequada neste caso é:","options":{"A":"Notificação imediata de meningite com meningococcemia e quimioprofilaxia com\nrifampicina para os irmãos e pais.","B":"Notificação imediata de meningite meningocócica e quimioprofilaxia com ceftriaxona para irmãos\ne pais.","C":"Notificação imediata de meningite com meningococcemia, vacinação para os irmãos e\nquimioprofilaxia com rifampicina para os pais.","D":"Quimioprofilaxia com rifampicina para os irmãos e pais, e notificação após confirmação por\ncultura e prova do látex."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127708","number":"127708","sourceNumber":"127708","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os estafilococos sempre representaram agentes etiológicos de inúmeras doenças\npediátricas de maior ou menor gravidade. Os\nMRSA (meticilino-resistentes) têm se disseminado,\nsendo adquiridos em ambiente hospitalar ou mesmo na comunidade. Qual é o principal mecanismo\nde resistência dos MRSA?","options":{"A":"Produção de betalactamases.","B":"Alteração nos ribossomos.","C":"Alteração nas PBP (penicilin binding proteins).","D":"Mutação da topoisomerase."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-127325","number":"127325","sourceNumber":"127325","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Menina de 1 ano iniciou com quadro de coriza e tosse há dois dias. Durante a noite,\nteve febre alta e, pela manhã, a mãe observou\nmanchas arroxeadas nas pernas. Chegou ao posto\nde saúde com febre e vômitos. Recebeu uma dose de penicilina benzatina e foi transferida para o\nhospital. Chegou ao pronto-socorro de referência, sonolenta, taquipneica, desidratada, com\npetéquias e algumas equimoses. Qual sua hipótese diagnóstica para esse quadro?","options":{"A":"Meningite meningocócica.","B":"Meningoencefalite.","C":"Sepse meningocócica.","D":"Coagulação intravascular disseminada."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-136543","number":"136543","sourceNumber":"136543","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual é o método de escolha para o diagnóstico de infecção do trato urinário em\nPediatria?","options":{"A":"Urina tipo 1.","B":"Urografia excretora.","C":"Uretrocistografia.","D":"Urocultura."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-110204","number":"110204","sourceNumber":"110204","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"João Antônio, 6 anos de idade, foi conduzido à UBS, por estar apresentando, há 4\nmeses, alteração de comportamento, com\nirritabilidade e choro fácil. Segundo a mãe do menor, há\num mês vem observando também movimentos desordenados dos braços e pernas, principalmente\nquando ocorre algum estímulo, levando a quedas frequentes. Nega presença dos movimentos\ndurante o sono. No início, achou que a criança estava \"fazendo manha\", pois os sintomas iniciaram\nlogo após a viagem da avó do menor. Mas como tem persistido, ficou preocupada e resolveu\nprocurar o serviço médico. Nega presença de qualquer outro sintoma. Quando perguntada sobre os\nantecedentes pessoais fisiológicos e patólogicos da criança, a mãe referiu que o menor nasceu de\nparto normal, hospitalar, sem intercorrências, com desenvolvimento neuropsicomotor adequado\npara a idade, sendo internado duas vezes com diarreia e vômito (com 2 e 4 anos de idade). Há 7\nmeses a criança teve um episódio de gripe e há 6 meses, amigdalite. No exame físico geral, o\nmédico anotou os seguintes achados: BEG, ativo, eupneico, normocárdico, anictérico, acianótico,\nhidratado, consciente, orientado. Presença de movimentos involuntários rápidos, arrítmicos e\nincoordenados de membros superiores e inferiores. No exame físico cardiovascular de João\nAntônio, o médico auscultou presença de sopro sistólico apical com irradiação para a axilia, sem\nvariação com a posição do paciente. Foi realizado RX de tórax, que não mostrou alterações e ECG\nque apresentou alongamento do espaço PR. A mãe do menor informou ao médico que nunca\nhaviam falado que seu filho tinha \"problema de coração\". Correlacionando os dados do texto, os\ndados do exame cardiovascular e o resultado do RX de tórax e ECG, qual o provável acometimento\ncardiológico de João Antônio?","options":{"A":"Pericardite.","B":"Miocardite.","C":"Endocardite.","D":"Pancardite."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-103692","number":"103692","sourceNumber":"103692","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente feminina de 70 anos apresentou agitação e desorientação na última semana,\ninclusive deixando de se medicar adequadamente de vez que a mesma é hipertensa crônica. Não\napresenta queixas respiratórias, porém, se queixa de mal estar e está algo agressiva. Nesse caso,\npodemos AFIRMAR que:","options":{"A":"desorientações em idosos obrigam a pesquisa de infecções, mesmo sendo subclínicas.","B":"como não há queixa de febre, não devemos explorar possibilidade de infecção.","C":"quadros demenciais são a principal causa de desorientação em idosos.","D":"a melhor conduta é prescrever ansiolíticos para acalmar a idosa."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-85397","number":"85397","sourceNumber":"85397","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Plantonista da Unidade de Pronto Atendimento (UPA) atende lactente de seis meses de\nidade, acompanhado por sua mãe. Dona Augusta informa que seu filho há três dias vem\napresentando irritabilidade, choro frequente, febre baixa (37,4°C) e inapetência. Refere há 24\nhoras intensificação da febre (38,5°C), vômitos e sonolência. O médico coletou liquor\ncefalorraquidiano e a análise mostrou o seguinte resultado: leucometria de 359 cels/mm³, sendo\n75% neutrófilos, 25% linfócitos; glicorraquia de 29 mg/dl e proteinorraquia de 140 mg/dl. De acordo\ncom o quadro clínico e o resultado do exame, qual o diagnóstico do lactente?","options":{"A":"Meningite Bacteriana.","B":"Encefalite fúngica.","C":"Meningite viral.","D":"Encefalite por enterovírus."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-83687","number":"83687","sourceNumber":"83687","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem de 27 anos apresenta mal-estar, tontura, sudorese e confusão iniciados há\n12h. Há 3h apresentou uma crise epiléptica. Exame físico: confuso e agressivo. Temperatura\n39,2°C, PA 80 x 40 mmHg, pulso 123 bpm, frequência respiratória 32 ipm, extremidades frias e\ncianóticas. Em relação ao caso descrito, é correto afirmar:","options":{"A":"Os vasopressores são indicados imediatamente e podem melhorar o nível de consciência do\npaciente.","B":"Proteína C ativada recombinante intravenosa está recomendada porque reduz mortalidade\nnessa circunstância.","C":"A ausência de melhora da pressão arterial com reposição volêmica agressiva caracteriza o\nchoque séptico.","D":"O quadro clinico é inespecífico, podendo ocorrer em qualquer tipo de choque (cardiogênico,\nséptico e hipovolêmico).","E":"A punção do liquor é de grande importância diagnóstica e deve ser realizada imediatamente\nantes de quaisquer outros exames."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-83829","number":"83829","sourceNumber":"83829","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"É fator preditivo de grave evolução em meningite bacteriana aguda:","options":{"A":"baixa celuraridade no liquor","B":"elevação de TGO no liquor","C":"redução da desidrogenase lática no liquor","D":"lactato positivo no liquor","E":"nenhuma das respostas acima é correta"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-63697","number":"63697","sourceNumber":"63697","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No estágio ambulatorial de medicina interna da UniEvangélica a Sra. Julieta, 22 anos, é\natendida com histórico de diabetes mellitus do tipo I há 12 anos. A paciente vem ao consultório com\nqueixa de disúria e poliaciúria recorrente há 1 ano, desde que se casou. Refere não estar fazendo\ncontrole rigoroso de glicemia no último ano e que ganhou 5 quilos no período. Ainda refere ter\nusado vários métodos contraceptivos, mas adaptou-se melhor com espermicida, método que vem\nutilizando desde o início do relacionamento conjugal. Que assertiva melhor descreve a hipótese\ndiagnóstica e conduta terapêutica apropriada?","options":{"A":"Infecção urinária baixa. Deve ser usado antibioticoterapia preferencialmente guiada por cultura,\nbem como controle glicêmico rigoroso e\nmodificação do método contraceptivo.","B":"Infecção urinária baixa. Deve ser usado antibioticoterapia sem preocupação com cultura, bem\ncomo controle glicêmico rigoroso. Não há\nnecessidade de modificação do método contraceptivo\nsendo este, inclusive, fator protetor contra infecções do trato urinário.","C":"Infecção urinária baixa. Deve ser usado antibioticoterapia preferencialmente guiada por cultura,\nbem como controle glicêmico rigoroso. A\nmodificação do método contraceptivo não influencia no\naumento ou diminuição da incidência de infecção urinária.","D":"Infecção urinária alta. Deve ser usado antibioticoterapia de largo espectro bem como controle\nglicêmico rigoroso. Deve ser feita a modificação do método contraceptivo."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-61729","number":"61729","sourceNumber":"61729","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem de 26 anos tem um dente ?siso? molar impactado extraído. Várias\nsemanas mais tarde, ele tem febre, seguida\nvários dias depois por cefaleia. Uma tomografia de\ncrânio revela uma lesão em anel de 3.5 centímetros na região parietal direita. Além disso, a\nausculta o paciente demonstra um sopro em crescendo/decrescendo e uma leve vibração no\nsegundo espaço intercostal da borda external direita. Uma cultura sanguínea mostra cultura de\ncrescimento positiva rica em catalase e coagulase. Quais dos seguintes achados de exame físico\napontam para a lesão que aumentou o risco dessas complicações?","options":{"A":"Sopro na carótida direita.","B":"Estenose Mitral.","C":"Regurgitação Mitral.","D":"Prolapso da válvula mitral.","E":"Sopro de ejeção sistólica."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-63281","number":"63281","sourceNumber":"63281","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação aos métodos de imagem mais sensíveis utilizados para diagnosticar\npaciente com sinais clínicos de osteomielite em\nfase inicial, consideramos correto realizar:","options":{"A":"ultrassonografia e radiografias convencionais.","B":"radiografias convencionais e cintilografia.","C":"cintilografia e ressonância magnética.","D":"tomografia convencional e ressonância magnética.","E":"densitometria óssea e tomografia computadorizada."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-63236","number":"63236","sourceNumber":"63236","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"As meningites bacterianas agudas são infecções graves, potencialmente fatais e que\nacometem com maior frequência crianças com idade inferior a 5 anos. Considerando os dados\natuais sobre a sensibilidade aos antimicrobianos dos agentes etiológicos - meningococo,\npneumococo e Haemophilus influenzae - no Brasil, qual seria o esquema antimicrobiano empírico\nmais adequado para o tratamento dessas infecções?","options":{"A":"Ampicilina.","B":"Ceftriaxona.","C":"Clindamicina.","D":"Penicilina cristalina.","E":"Vancomicina."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-48270","number":"48270","sourceNumber":"48270","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nos usuários de drogas endovenosas ilícitas, o local mais comumente atingido na\nendocardite infecciosa é:","options":{"A":"Válvula mitral.","B":"Válvula aórtica.","C":"Válvula pulmonar.","D":"Válvula tricúspide.","E":"Septo interventricular."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-48525","number":"48525","sourceNumber":"48525","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação às infecções que ocorrem no trato urinário durante a infância, pode-se\nafirmar que:","options":{"A":"O agente etiológico mais frequente é a E. Coli, adquirida por via hematogênica.","B":"A droga de eleição para o tratamento é a Ciprofloxacino.","C":"Na idade escolar, meninos têm duas vezes mais infecções que as meninas.","D":"A pesquisa de lesões obstrutivas é fundamental, principalmente em meninos.","E":"A infecção em lactentes é, na grande maioria das vezes, adquirida por via hematogênica."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-48289","number":"48289","sourceNumber":"48289","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um recém-nascido de termo, adequado para idade gestacional, sexo masculino,\nnascido de parto normal, após 22 horas de\nrotura de membranas, na décima hora de vida,\ndesenvolve quadro de cianose de extremidades associado a febre e tremores. Não houve\nrealização de cultura de secreção vaginal durante o pré-natal e não houve tempo hábil para a\nprofilaxia intraparto. Hemograma com 4.000 leucócitos e índice neutrofílico de 0,5; proteína C\nreativa elevada; liquor com 13 leucócitos sendo 8 neutrófilos e 5 linfócitos e glicemia de 78 mg%. A\nterapêutica antimicrobiana racional, neste caso, deve ser:","options":{"A":"Apenas cefalosporina de terceira geração.","B":"Cefalosporina de terceira geração e ampicilina.","C":"Claritromicina e cefalosporina de terceira geração.","D":"Penicilina cristalina e aminoglicosídeo.","E":"Apenas ampicilina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-48151","number":"48151","sourceNumber":"48151","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O tratamento antimicrobiano de escolha na erisipela é:","options":{"A":"Tetraciclina.","B":"Metronidazol.","C":"Penicilina Cristalina.","D":"Cloranfenicol.","E":"Eritromicina."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-35853","number":"35853","sourceNumber":"35853","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A cura de infecção do trato urinário depende mais da:","options":{"A":"Meia-vida sérica do antimicrobiano.","B":"Concentração sérica do antimicrobiano.","C":"Concentração urinária do antimicrobiano.","D":"Duração do tratamento antimicrobiano.","E":"Frequência do tratamento."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-26940","number":"26940","sourceNumber":"26940","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Cibele, 40 anos, portadora de insuficiência mitral secundária a prolapso, procurou\nserviço médico com queixa de febre e odinofagia há\n3 dias. O exame físico demonstrou estalido\nmesosistólico em área mitral e discreta hiperemia de orofaringe. A melhor conduta é:","options":{"A":"realização de ecocardiograma e coleta de sangue para hemoculturas","B":"coleta de sangue para hemoculturas e penicilina benzatina intramuscular","C":"realização de ecocardiograma e penicilina benzatina intramuscular","D":"realização de ecocardiograma e início de ácido-acetil-salicílico","E":"início de ácido-acetil-salicílico e observação"},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-26942","number":"26942","sourceNumber":"26942","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Endocardite por Streptococcus bovis tem forte relação com:","options":{"A":"Carcinoma de pulmão","B":"Infecções do trato urinário","C":"Tumores do intestino Grosso","D":"Abuso de drogas injetáveis","E":"Melanoma"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-26956","number":"26956","sourceNumber":"26956","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Heitor, 22 anos, portador de Síndrome de Down e estenose mitral leve, submeter-se-á a\nanestesia para extração dentária múltipla. É mandatório iniciar no pré-operatório:","options":{"A":"Digital","B":"Heparina em pequenas doses","C":"Antibiótico","D":"Antinflamatório não hormonal","E":"Diurético"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-27158","number":"27158","sourceNumber":"27158","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A pielonefrite aguda é melhor dignosticada por:","options":{"A":"Calafrios, febre e dor no flanco.","B":"Bacteriúria e piúria.","C":"Escara renal.","D":"Prejuízo da função renal.","E":"Refluxo vesico-ureteral."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-27161","number":"27161","sourceNumber":"27161","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O fator de predisposição mais comum para infecções do trato urinário adquiridas no\nhospital é:","options":{"A":"Procedimento cirúrgico.","B":"Utilização de antibióticos.","C":"Idade","D":"Sondagem vesical","E":"Diabetes Mellitus"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-26998","number":"26998","sourceNumber":"26998","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Pedro, 2 anos de idade, chega ao PS com história de febre alta há 1 dia associada a\nvômitos e queda do estado geral. Ao exame físico, apresentava-se em mau estado geral, má\nperfusão periférica, sem sinais meníngeos e sem déficits neurológicos focais e presença de\npetéquias em face e tronco. Realizada coleta de LCR por punção lombar, obtivemos o seguinte\nresultado de exame: 200 leucócitos por mm³, sendo 80% neutrófilos, proteinorraquia de 40 mg/dl e\nglicorraquia de 50 mg/dl. Em relação ao diagnóstico, o mais provável é:","options":{"A":"Meningite viral.","B":"Meningite bacteriana.","C":"Meningite tuberculosa.","D":"Meningite fúngica.","E":"Hemorragia subaracnoidea."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-26999","number":"26999","sourceNumber":"26999","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Pedro, 2 anos de idade, chega ao PS com história de febre alta há 1 dia associada a\nvômitos e queda do estado geral, má perfusão periférica, sem sinais meníngeoas e sem déficits\nneurológicos focais e presença de petéquias em face e tronco. Realizada coleta de LCR por\npunção lombar, obtivemos o seguinte resultado de exame: 200 leucócitos por mm3, sendo 80%\nneutrófilos, proteinorraquia de 40 mg/dl e glicorraquia de 50 mg/dl. Em relação ao tratamento, o\nmais indicado é:","options":{"A":"Observar a evolução por 24 horas.","B":"Hidratação venosa para melhor o estado geral e alta para casa após.","C":"Iniciar antibióticos empiricamente.","D":"Aguardar culturas para iniciar antibióticos específicos.","E":"Derivação ventrículo-peritoneal."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-27000","number":"27000","sourceNumber":"27000","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Pedro, 2 anos de idade, chega ao PS com história de febre alta há 1 dia associada a\nvômitos e queda do estado geral, má perfusão periférica, sem sinais meníngeoas e sem déficits\nneurológicos focais e presença de petéquias em face e tronco. Realizada coleta de LCR por\npunção lombar, obtivemos o seguinte resultado de exame: 200 leucócitos por mm3, sendo 80%\nneutrófilos, proteinorraquia de 40 mg/dl e glicorraquia de 50 mg/dl. Em relação aos contatos diretos\ndesta criança, o mais indicado é:","options":{"A":"Nada a fazer.","B":"Observar.","C":"Fazer punção lombar para coleta de LCR em todos.","D":"Quimioprofilaxia com rifampicina.","E":"Quimioprofilaxia com penicilina benzatina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-23057","number":"23057","sourceNumber":"23057","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Nas infecções do trato urinário adquiridas na comunidade, o agente etiológico mais\ncomum é:","options":{"A":"Klebsiella.","B":"Proteus sp.","C":"Stafilococcus epidermidis.","D":"Escherichia coli."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8938","number":"8938","sourceNumber":"8938","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Com relação à epidemiologia das meningites, assinale a alternativa incorreta:","options":{"A":"As medidas de controle da doença meningocócica envolvem o controle de contatos, a\nquimioprofilaxia e a vacinação nas situações pertinentes","B":"A meningite tuberculosa é transmissível, apresentando alta contagiosidade","C":"O streptococcus pneumoniae é um patógeno importante na causalidade das meningites em\nmenores de dois anos de idade","D":"A vacinação conjugada contra Haemophilus influenzae sorotipo b preconizada no segundo,\nquarto e sexto mês de vida, num composto\ntetravalente (DPT + Hib) é uma das medidas de\ncontrole disponíveis contra meningite por Haemophilus influenzae"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-9350","number":"9350","sourceNumber":"9350","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A endocardite infecciosa é uma afecção predominantemente da terapêutica clínica. Em\nsituações especiais, a cirurgia é realizada mesmo na vigência da infecção. Na fase aguda, o\ntratamento cirúrgico é indicado quando ocorre a presença de:","options":{"A":"toxemia, insuficiência renal aguda com indicação de hemodiálise e abscessos esplênicos.","B":"insuficiência respiratória com indicação de ventilação mecânica, micro-organismo desconhecido\ne abscessos cerebrais.","C":"insuficiência cardíaca de difícil controle, embolias de repetição e abscesso anular.","D":"quadro séptico, detecção de lesão valvar e de vegetação ao ecocardiograma."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-10663","number":"10663","sourceNumber":"10663","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O Staphylococcus aureus pode produzir patologias através de uma toxina ou pela\ninvasão tecidual direita. Uma doença desencadeada por uma toxina estafilcóccica é a:","options":{"A":"pneumonia da mucoviscidose.","B":"endocardite bacteriana aguda.","C":"artrite séptica.","D":"meningoencefalite.","E":"síndrome do choque tóxico."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-12707","number":"12707","sourceNumber":"12707","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual das causas de febre relacionadas abaixo tem origem infecciosa?","options":{"A":"Apendicite","B":"Pancreatite","C":"Pielonefrite","D":"Obstrução intestinal","E":"Trombose cerebral"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-12711","number":"12711","sourceNumber":"12711","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São critérios maiores para o diagnóstico de endocardite infecciosa, exceto:","options":{"A":"Hemocultura Positiva","B":"Esplenomegalia e febre","C":"Presença de abscesso visualizado pelo ecocardiograma","D":"Aparecimento de regurgitação valvar, antes não existente","E":"presença de vegetação em folhetos ao ecocardiograma"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8964","number":"8964","sourceNumber":"8964","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A diferenciação córtico-medular na ultrassonografia renal se dá pelo alto fluxo de\nsangue no córtex renal, a perda dessa\ndiferenciação é uma alteração comum nos pacientes\nportadores de Doença Renal Crônica terminal devido o grau acentuado de esclerose glomerular.\nOutra causa de perda de diferenciação córtico-medular na ultrassonografia é:","options":{"A":"Pielonefrite aguda","B":"Sindrome Nefrótica","C":"Uso de anti-inflamatório hormonal","D":"Desidratação"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-11063","number":"11063","sourceNumber":"11063","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Fator(es) não associados(s) com ITU aguda não complicada:","options":{"A":"Hipoestrogenismo","B":"Diafragma e espermaticidas","C":"Gravidez","D":"Tipo de roupa íntima","E":"Frequência coital"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-8978","number":"8978","sourceNumber":"8978","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os agentes mais frequentemente relacionados às meningites virais e encefalites virais\nsão respectivamente:","options":{"A":"Enterovírus e Citomegalovírus","B":"Citomegalovírus e Vírus Epstein barr","C":"Enterovírus e Herpes simples","D":"Herpes simples e HIV"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-10628","number":"10628","sourceNumber":"10628","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Adulto jovem com Síndrome de Down e estenose mitral leve submeter-se-á a anestesia\npara extração dentária múltipla. É mandatório\niniciar no pré-operatório,","options":{"A":"digital.","B":"heparina em pequenas doses.","C":"antibiótico.","D":"antiinflamatório não hormonal.","E":"diurético."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-250263","number":"250263","sourceNumber":"250263","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 4 anos de idade, sexo masculino, procedente de Santa Inês ? MA, com\nquadro clínico de febre há 2 meses,\nhepatoesplenomegalia palidez e icterícia leve. Laboratório com\npancitopenia e hipoalbuminemia. Considerando o caso clínico descrito, selecione qual exame\ncomplementar é fundamental para dar continuidade na investigação do caso:","options":{"A":"Eletroforese de hemoglobina.","B":"Antígeno rosa de bengala.","C":"Mielograma.","D":"Sorologia para arbovírus."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216433","number":"216433","sourceNumber":"216433","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 2 anos, com diagnóstico de leishmaniose visceral realizado através da\nidentificação de formas amastigotas de Leishmania sp. no esfregaço de mielograma, sendo então\niniciado tratamento com Glucantime®. Após 7 dias de tratamento, a farmácia informa falta de\nmedição nos estoques do hospital, sendo decidido pela equipe médica solicitar a transferência da\ncriança para um hospital de referência. Após 5 dias de espera no hospital de origem, a criança foi\ntransferida para o hospital de referência, contabilizando 5 dias sem uso do Glucantime®. Diante do\ncaso descrito acima, assinale a alternativa CORRETA com base nas recomendações do Ministério\nda Saúde referentes à conduta que o pediatra do hospital de referência deve adotar nesse caso.","options":{"A":"Retornar o tratamento com Glucantime® por mais 13 dias, pois já realizou 7 dias de tratamento\nno hospital de origem, totalizando ao final 20\ndias de tratamento.","B":"Reiniciar o esquema com Glucantime® por 20 dias.","C":"Como há possibilidade de resistência ao Glucantime® justificado pelo uso prévio, é\nrecomendado o uso de Anfotericina B.","D":"Realizar tratamento com miltefosina oral por mais 13 dias, pois já realizou 7 dias de tratamento\ncom Glucantime®."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-176269","number":"176269","sourceNumber":"176269","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em períodos de epidemia de Dengue e de outras arboviroses, o atendimento prioritário\ndeve ser dado a todos os pacientes abaixo,\nEXCETO:","options":{"A":"Àqueles que apresentam comorbidades, como diabetes, hipertensão arterial e nefropatias.","B":"Àqueles que se apresentam febris nos primeiros dias de doença.","C":"Àqueles que apresentam vômitos frequentes, diminuição da diurese e dor abdominal.","D":"Àqueles que apresentam sangramento de mucosas.","E":"Os idosos e menores de 1 ano de idade."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-176265","number":"176265","sourceNumber":"176265","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente com 6 meses de idade, internado com febre há 20 dias, palidez e\nesplenomegalia de 6cm do rebordo costal\nesquerdo, para investigação diagnóstica. Realizou\nhemograma com leucócitos totais de 3.200/mm3, Hb de 6,5g% e plaquetometria de 78.000/mm3.\nFez teste rápido para Calazar, com resultado positivo. O tratamento MAIS indicado, nesse caso é:","options":{"A":"Antimoniato de N-metil-glucamina (Glucantime®)","B":"Desoxicolato de anfotericina B","C":"Associação de desoxicolato de anfotericina B e antimoniato de N-metil-glucamina (Glucantime®)","D":"Anfotericina B lipossomal","E":"Desoxicolato de anfotericina B"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-155282","number":"155282","sourceNumber":"155282","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre o acometimento renal associado à leptospirose é correto afirmar, EXCETO:","options":{"A":"Ação nefrotóxica direta da leptospira, hiperbilirrubinemia, rabdomiólise e hipovolemia são\nfatores\nenvolvidos na gênese da IRA.","B":"Alterações na função tubular geralmente procedem a queda na TFG.","C":"A Insuficiência Renal Aguda (IRA) é caracteristicamente oligúrica e hipercalêmica.","D":"Pode apresentar- se de forma subclínica, com leve proteinúria, geralmente menor que 1g/24h.","E":"Pode persistir déficit de concentração urinária por período prolongado."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-155254","number":"155254","sourceNumber":"155254","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Oitenta por cento (80%) das crianças que adquirem infecção por Zika vírus:","options":{"A":"São assintomáticas.","B":"Têm rash cutâneo.","C":"Têm febre elevada.","D":"Têm edema de extremidades.","E":"Desenvolvem artralgias de semanas a meses após a infecção."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-131928","number":"131928","sourceNumber":"131928","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Embora pacientes imunocomprometidos possam apresentar infecção por qualquer\npatógeno, existe geralmente associação\nestatística entre o tipo de imunodeficiência e determinados\npatógenos específicos. Considerando as três listas de patógenos seguintes, marque a opção que\nmostra a MELHOR associação com o tipo de imunodeficiência, na sequência. -H. influenzae, N.\nmeningitides, S. pneumoniae; -Pseudomonas, S. aureus, Candida, Aspergillus; -Micobactéria,\nHerpes, Pneumocystis, Cryptococcus, Toxoplasma","options":{"A":"Neutropenia, humoral, linfopenia.","B":"Humoral, linfopenia, neutropenia.","C":"Humoral, neutropenia, linfopenia.","D":"Linfopenia, neutropenia, humoral.","E":"Linfopenia, humoral, neutropenia."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-131913","number":"131913","sourceNumber":"131913","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A etiologia da meningite bacteriana aguda dependerá da idade, do estado imunológico\ne da epidemiologia. Os principais agentes na\nfaixa etária > 3 meses são:","options":{"A":"Bastonetes Gram-negativos.","B":"Streptococcus agalactiae.","C":"Enterococcus sp.","D":"L. monocytogenes.","E":"N. meningitidis."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-105714","number":"105714","sourceNumber":"105714","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação às infecções necrosantes de pele e partes moles (INPPMs), assinale a\nalternativa INCORRETA:","options":{"A":"As INPPMs do tipo I são monomicrobianas e mais comumente causadas por bactérias\nanaeróbicas tais como clostrídios,\nestreptococos ou bacterióides, por sua vez, as INPPMs do tipo II\nsão polimicrobianas. A maioria dos patógenos, especialmente o Clostridium perfringens, secretam\nexotoxinas (hemolisina, colagenases, lecitinases e proteases) que determinam uma rápida\nevolução da necrose tissular ao longo das fáscias e planos musculares.","B":"Pacientes imunocomprometidos, incluindo pacientes com diabetes mellitus, vírus da\nimunodeficiência humana (HIV), desnutrição, doença\nvascular periférica e uso de dorgas injetáveis\naumentam o risco de desenvolvimento de INPPMs.","C":"Alto índice de suspeição e diagnóstico precoce são críticos, devido à rápida progressão para as\nalterações hemodinâmicas (choque) e falências orgânicas associadas ao retardo no diagnóstico e\nmanejo clínico e cirúrgico adequados nas INPPMs.","D":"Assim como ocorre nas infecções clostridianas (gangrena úmida), a amputação do membro está\nrecomendada como abordagem cirúrgica de escolha nos pacientes com fasceíte necrosante não\nclostridiana, envolvendo os membros inferiores, com o objetivo de se minimizar a morbiletalidade\ndo episódio.","E":"As INPPMs são consideradas como emergência cirúrgica, e recomenda-se tratamento imediato\ne agressivo com suporte hemodinâmico e\nressuscitação fluida, extensivo debridamento cirúrgico\ndos tecidos necróticos e antibioticoterapia de amplo espectro."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-105670","number":"105670","sourceNumber":"105670","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre as infecções estafilocócicas, não é correto afirmar:","options":{"A":"Na intoxicação alimentar, patologia de início e resolução agudos (geralmente em horas), a\ndoença é causada pela ingestão da\nenterotoxina pré-formada. A toxina estimula o centro do vômito\ne a peristalse intestinal, ocasionando os sintomas. Não há participação bacteriana direta nos\nsintomas, portanto o tratamento consiste apenas em suporte, sem necesidade de antibioticoterapia.","B":"Os estafilococos coagulase-negativa são mais virulentos do que os estafilococos\n\ncoagulase-positiva e, mais comumente, estão associados às infecções de dispositivos protéticos.\nComo estão presentes em grande quantidade na\npele, geralmente contaminam as culturas,\ndificultando a interpretação das mesmas.","C":"A vancomicina é uma opção menos efetiva do que a oxacilina para tratamento de infecções por\nMethicillin-Sensitive Staphylococcus Aureus (MSSA).","D":"As infecções de repetição podem ocorrer devido à colonização de superfícies corporais,\nespecialmente a parte anterior das narinas. Essa incidência pode ser reduzida com o uso de\nmupirocina tópica na região nasal.","E":"São síndromes clínicas cuja etiologia estafilocócica deve sempre ser lembrada como uma das\nmais importantes: infecções de pele e partes moles, artrite séptica, osteomielite, pneumonia\n(especialmente a comunitária grave e a nosocomial) e endocardite infecciosa."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-80906","number":"80906","sourceNumber":"80906","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, 62 anos, diagnosticada com diabetes mellitus em uso de insulinoterapia,\niniciou há 48 horas febre de 38°C e lesão\ncutânea em membro inferior esquerdo. Ao exame: estado\ngeral preservado; FC = 94 bpm; PA = 120 x 70 mmHg; apresenta eritema de limites bem definidos;\nedema e calor acometendo o terço inferior da perna esquerda. Sobre o quadro descrito, é\nCORRETO afirmar:","options":{"A":"Trata-se de celulite, o agente mais provável é o Staphylococcus aureus e o tratamento deve ser\nfeito com norfloxacino por 3 dias.","B":"Trata-se de celulite e o tratamento deve aguardar o resultado da cultura e antibiograma.","C":"Não há relevância se o diagnóstico é erisipela ou celulite, devendo-se tratar com ciprofloxacino\ne\nclindamicina.","D":"O diagnóstico é de erisipela e o tratamento deve ser com antibiótico betalactâmico.","E":"Devem ser analisados os níveis glicêmicos e indicado o tratamento com vancomicina."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-80851","number":"80851","sourceNumber":"80851","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Adolescente de 13 anos, sexo feminino, portador de estenose aórtica congênita leve,\nvai ser submetido a procedimento dentário invasivo. Neste caso, está indicada a profilaxia com:","options":{"A":"Sulfametoxazol + trimetropim.","B":"Ciprofloxacina.","C":"Amoxicilina.","D":"Azitromicina.","E":"Eritromicina."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-62647","number":"62647","sourceNumber":"62647","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher, 20 anos, chega ao Serviço de Emergência com cefaleia e febre há 72 horas. Ao\nexame físico, encontra-se sonolenta, febril\n(38,5°C) e com rigidez de nuca. Há história de sinusite\nde repetição. O médico aventou como hipótese diagnóstica meningite. Para confirmá-la, foi\nrealizada punção lombar, que revelou liquor turvo. Análise liquórica mostrou: celularidade: 800/cm³,\ncom predomínio de polimorfonucleares; proteína: 700 mg; glicose: 20 mg/dl e mostra, em coloração\npelo método de Gram, cocos Gram-positivos em cadeia. Considerando os dados clínicos e\nlaboratoriais do caso descrito, a afecção, o agente etiológico provável e o esquema antimicrobiano\na iniciar são, respectivamente:","options":{"A":"Meningite bacteriana por Neisseria meningitidis; penicilina cristalina.","B":"Meningite bacteriana por Haemophilus influenzae; ceftriaxona.","C":"Meningoencefalite viral por herpes simples; aciclovir.","D":"Meningoencefalite por Mycobacterium tuberculosis; esquema RIPE.","E":"Meningite bacteriana por Streptococcus pneumoniae; ceftriaxona."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-47476","number":"47476","sourceNumber":"47476","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma mulher de 25 anos se apresenta à clínica queixando-se de vários dias de ardor e\ndor ao urinar. Ela descreve um aumento na frequência urinária e sensibilidade suprapúbica, mas\nsem febre ou tenesmo. Ela não tem história médica pregressa, com exceção de dois episódios\nanteriores semelhantes a este nos últimos 2 anos. Análise de urina mostra aumento de leucócitos.\nQual dos seguintes é o agente causal mais provável de seus sintomas atuais?","options":{"A":"Candida.","B":"Enterobacter.","C":"Klebsiella.","D":"Escherichia coli.","E":"Proteus."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-35777","number":"35777","sourceNumber":"35777","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma criança com cinco meses apresenta choro frequente, irritabilidade, vômitos\npersistentes com exantema purpúrico em tronco e membros. O diagnóstico mais provável é:","options":{"A":"Varicela.","B":"Púrpura de Henoch-Schönlein.","C":"Glomerulonefrite pós-estreptocócica.","D":"Meningococcemia.","E":"Mononucleose."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-28237","number":"28237","sourceNumber":"28237","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Menino com febre intermitente, mialgia difusa, com limitação dos movimentos,\nbaqueteamento dos dedos, petéquias, hematúria\nmicroscópica e sopro cardíaco. Baseado na\nclínica, qual o diagnóstico provável?","options":{"A":"Artrite reumatoide","B":"Febre reumática","C":"Endocardite infecciosa","D":"Lúpus eritematoso sistêmico","E":"Hanseníase"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-11502","number":"11502","sourceNumber":"11502","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 75 anos, tabagista, com doença pulmonar obstrutiva crônica, otite média\ncrônica em tratamento com amoxacilina,\nhipertenso há 12 anos e diabético há 8 anos, em uso de\nglimeperida 4 mg/dia, metformina 850 mg/dia, amilorida 10 mg/dia, captropil 75 mg/dia, cavedilol 25\nmg/dia e sinvastatina 40 mg/dia, sequelado de AVC (hemiparético à E), chega ao pronto-socorro do\nSUS com história de cefaleia holocraniana e constante há 9 dias; disfasia há 4 dias; náuseas,\nvômitos e confusão mental há 2 dias. Há 3h, apresentou crise convulsiva tonicoclônica\ngeneralizada. Apresenta ainda dispneia de repouso e ortopneia, astenia e anorexia. Nega febre. Ao\nexame, PA de 150/90 mmHg, FC de 68 bpm, FR de 27 ir/min, afebril, hipocorado (++/4), edema de\nMMII, ++/4; AR: murmúrio vesicular universalmente diminuído com estertores difusos; ACV; RCR,\n3T, bulhas normofonéticas, sopro sistólico em foco aórtico de +/4; ABD; hepatomegalia a 2 cm do\nRCD, dolorosa e macicez móvel à percussão; Sistema nervoso: força grau III à E, desorientado,\ndisfásico, sem sinais meníngeos. Exames complementares: leucócitos de 3.100 cél/mm3, plaquetas\nde 746.000, proteína c reativa de 32 mg/dl, creatinina de 1 mg/dl, sódio de 130 meq/l, potássio de\n6,1 meq/l. Radiografia de tórax: presença das linhas B de Kerley e infiltrado Peri-hilar bilateral.\nEm\nrelação ao caso clínico, responda: Em relação à causa base do quadro clínico atual do paciente,\nmarque a melhor opção:","options":{"A":"Solicitar CT de crânio, colher culturas, iniciar ceftriaxone e metronidazol e pedir avaliação\nneurocirúrgica.","B":"Punção liquórica, colher culturas e iniciar ceftriaxone, não há necessidade de avaliação\nneurocirúrgica.","C":"Solicitar ecodopplercardiograma transesofágico, colher culturas e iniciar penicilina cristalina +\ngentamicina.","D":"Solicitar CT de crânio, iniciar AAS, aguardar resultado das culturas para iniciar antibiótico\n(já que\nnão sabemos o sítio da infecção).","E":"Solicitar RNM e ecodopplercardiograma transtorácico e aguardar resultado para próxima\nconduta."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-11485","number":"11485","sourceNumber":"11485","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os maiores coeficientes de incidência das meningites meningocócicas em nosso meio\nsão observados em que faixa etária?","options":{"A":"em adolescentes.","B":"em crianças na idade escolar.","C":"em lactentes no primeiro ano de vida.","D":"os coeficientes são iguais para todas as faixas etárias em crianças e adolescentes.","E":"em adultos acima de 40 anos."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-342404","number":"342404","sourceNumber":"342404","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a Monkeypox é INCORRETO afirmar:","options":{"A":"Os primatas não humanos (macacos) são reservatórios do vírus.","B":"O aumento recente da incidência guarda relação com a interrupção da vacinação contra a\nvaríola.","C":"Na África o aumento da incidência tem relação com a maior invasão de habitats de animais que\nsão reservatórios do vírus.","D":"A Transmissão se dá por gotículas de saliva ou respiratórias.","E":"O contato com exsudato de feridas promove a transmissão."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-342410","number":"342410","sourceNumber":"342410","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os vírus da família Togaviridae e Flaviviridae são responsáveis respectivamente por:","options":{"A":"Dengue e Zika","B":"Zika e Dengue","C":"Zika e Chikungunya","D":"Chikungunya e Zika","E":"Dengue e Chikungunya"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-342435","number":"342435","sourceNumber":"342435","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A dengue na criança pode ser assintomática ou apresentar-se como uma síndrome\nfebril clássica viral, ou com sinais e sintomas\ninespecíficos: adinamia, sonolência, recusa da\nalimentação e de líquidos, vômitos, diarreia ou fezes amolecidas. Sobre o manejo clínico da dengue\nem crianças é CORRETO afirmar:","options":{"A":"A prova do laço pode ser realizada em crianças, o médico deve verificar a pressão arterial da\ncriança e calcular o valor médio pela fórmula (PAS + PAD)/2.","B":"Grau de hidratação, temperatura e peso não são relevantes para a conduta clínica.","C":"Na presença de Manifestações hemorrágicas de pele e mucosas como petéquias, sufusões\nhemorrágicas em locais de punção venosa e equimoses, deve ser feita hemotransfusão.","D":"Após 48 horas de internação, verificar sinais de irritação meníngea, nível de consciência,\nsensibilidade, força muscular e reflexos\nosteotendíneos, bem como o exame da fontanela anterior\nem lactantes.","E":"Descartar diagnóstico de dengue na presença de dor abdominal, hepatomegalia dolorosa e\nascite."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-308626","number":"308626","sourceNumber":"308626","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção pelo vírus da dengue pode ser assintomática ou sintomática. Quando\nsintomática, causa uma doença sistêmica e\ndinâmica de amplo espectro clínico, variando desde as\nformas oligossintomáticas até quadros graves. Durante o manejo clínico da dengue uma pessoa\nque viva em área onde se registram casos de dengue, ou que tenha viajado nos últimos 14 dias\npara área com ocorrência de transmissão de dengue (ou presença de Ae. aegypti), deve apresentar\nfebre, usualmente entre dois e sete dias, e duas ou mais das seguintes manifestações: náuseas,\nvômitos, exantema, mialgias, uretralgia, cefaleia, dor retro-orbital, petéquias, prova do laço\npositiva,\nleucopenia. Também pode ser considerado caso suspeito toda criança proveniente de (ou residente\nem) área com transmissão de dengue, com quadro febril agudo usualmente entre dois e sete dias,\ne sem foco de infecção aparente. Considerando a definição de classificação de caso de dengue,\nmarque a opção CORRETA.","options":{"A":"Caso suspeito de dengue com sinais de alarme.","B":"Caso suspeito de dengue.","C":"Caso suspeito de dengue grave.","D":"Confirmado.","E":"Caso descartado."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-308632","number":"308632","sourceNumber":"308632","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a Leishmaniose Visceral, assinale a opção CORRETA.","options":{"A":"Os agentes etiológicos da leishmaniose visceral são protozoários tripanosomatideos, com uma\nforma amastigota encontrada no tubo digestivo\ndo inseto vetor e outra promastigota nos tecidos dos\nvertebrados","B":"Os vetores da leishmaniose visceral são insetos denominados flebotomíneos, conhecidos\npopularmente como mosquito palha, tatuquiras e birigui.","C":"A enzootia no homem tem precedido a ocorrência de casos no cão e a infecção em humanos\ntem sido mais prevalente do que a canina.","D":"A forma de transmissão da Leishmania chagasi é de pessoa a pessoa.","E":"O período de incubação no homem é em média de 10 dias a 24 dias e no cão é com média de 3\na 7 dias."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-263757","number":"263757","sourceNumber":"263757","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação às doenças infecciosas, relacione a coluna I com a coluna II e assinale a\nalternativa que contém a sequência CORRETA: COLUNA I: (A) Leishmaniose visceral; (B) Malária;\n\n(C) Doença de Chagas; (D) Hanseníase; (E) Febre amarela. ( ) O aspirado de medula óssea mostra\npresença de forma amastigota do parasito. Nos exames complementares, o hemograma revela\nanemia, geralmente pouco expressiva, com hemoglobina acima de 9 g/dl. A combinação de\nmanifestações clínicas e alterações laboratoriais, que melhor parece caracterizar a forma\noligossintomática, é febre, hepatomegalia, hiperglobulinemia e velocidade de hemossedimentação\nalta. ( ) Em casos de transmissão vetorial, podem ocorrer sinais de porta de entrada: sinal de\nRomaña (edema bipalpebral unilateral) ou lesão a furúnculo que supura. ( ) Doença crônica\ngranulomatosa. Esse bacilo tem a capacidade de infectar grande número de indivíduos (alta\ninfectividade), no entanto, poucos adoecem (baixa patogenicidade). Essas propriedades\ndependem, além das características intrínsecas do bacilo, de sua relação com o hospedeiro e o\ngrau de endemicidade de meio. ( ) O quadro típico tem evolução bifásica (período de infecção e de\nintoxicação), com início abrupto, febre alta e pulso lento em relação à temperatura (sinal de\nFaget),\ncalafrios, cefaleia intensa, mialgias, prostração, náuseas e vômitos, durando cerca de 3 dias, após\nos quais se observa remissão da febre e melhora dos sintomas, o que pode durar algumas horas\nou, no máximo, 2 dias. O caso pode evoluir para cura ou para a forma grave. ( ) Para diagnóstico\nda doença, a gota espessa é o método oficialmente adotado no Brasil para o diagnóstico. Mesmo\napós o avanço de técnicas diagnósticas, esse exame com exame continua sendo um método\nsimples, eficaz, de baixo custo, de fácil realização. Quando adequadamente realizada é\nconsiderado como padrão-ouro pela Organização Mundial da Saúde (OMS).","options":{"A":"A - C - D - E - B.","B":"C - D - B - A - E.","C":"A - B - C - D - E.","D":"B - A - D - C - E.","E":"C - B - E - D - A."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-263764","number":"263764","sourceNumber":"263764","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Escolar, nove anos de idade, apresenta febre alta há cinco dias, cefaleia, dor\n\nretro-orbitária e letargia. Hoje, apresentou sangramento em mucosas. A conduta para esse paciente\né:","options":{"A":"Um achado laboratorial importante é a trombocitopenia sem hemoconcentração concomitante.","B":"A conduta nesse caso é hidratação oral, paracetamol e observação por 12 horas.","C":"A conduta nesse caso é hidratação venosa, dipirona e internação hospitalar.","D":"Observação por 12 horas, pois o choque somente ocorre entre o 2º e 5º dia de doença, sem ser\nprecedido por sinais de alerta.","E":"No caso em questão, o paciente deverá receber hidratação oral, dipirona e alta para casa com\nrecomendações para retorno imediato se apresentar piora clínica."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-244648","number":"244648","sourceNumber":"244648","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A infecção pelo vírus dengue pode ser assintomática ou sintomática. Quando\nsintomática, causa uma doença sistêmica e\ndinâmica de amplo espectro clínico, variando desde\nformas oligossintomaticas até quadros graves. Durante o manejo clínico da dengue, uma pessoa\nque viva em área onde se registram casos de dengue, ou que tenha viajado nos últimos 14 dias\npara área com ocorrência de transmissão de dengue (ou presença de Ae. aegypti), deve apresentar\nfebre, usualmente entre dois e sete dias, e duas ou mais das seguintes manifestações: Náusea,\nvômitos, exantema, mialgias, uretralgia, cefaleia, dor retro orbital, petéquias, prova do laço\npositiva,\nleucopenia. Também pode ser considerado caso suspeito toda criança proveniente de (ou residente\nem) área com transmissão de dengue, com quadro febril agudo, usualmente entre dois e sete dias,\ne sem foco de infecção aparente. Considerando esta definição de Classificação de caso de dengue,\nmarque a opção CORRETA.","options":{"A":"Caso suspeito de dengue com sinais de alarme.","B":"Caso suspeito de dengue grave.","C":"Confirmado.","D":"Caso suspeito de dengue.","E":"Caso descartado."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-252407","number":"252407","sourceNumber":"252407","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Quais doenças abaixo podem ser transmitidas por carrapatos?","options":{"A":"Febre maculosa e febre recorrente","B":"Febre amarela e peste bubônica","C":"Febre amarela e febre recorrente","D":"Peste bubônica e febre maculosa","E":"Febre amarela e febre maculosa"},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-252449","number":"252449","sourceNumber":"252449","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A higienização das mãos é uma medida eficaz, barata e primordial para a segurança do\npaciente, podendo ser realizada com álcool em gel a 70% ou água e sabão, sendo na pediatria e\nna neonatologia fundamental para redução das infecções hospitalares e influenciando na redução\nda mortalidade infantil por infecções relacionadas à assistência de saúde. A realização dos cinco\nmomentos se torna uma estratégia que deve ser aplicada a todos os pacientes que estão em\ncuidados de assistência em saúde. Sobre a higienização das mãos, selecione a opção que\ncorresponde ao momento que obrigatoriamente se deve realizar higienização das mãos com água e\nsabão.","options":{"A":"Antes de contato com o paciente","B":"Após o contato com o paciente","C":"Após contato com as áreas próximo ao paciente","D":"Após exposição de fluidos corporais","E":"Antes da realização de procedimento asséptico"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-203628","number":"203628","sourceNumber":"203628","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No tratamento da fase precoce da leptospirose em adulto, o antimicrobiano de escolha\né:","options":{"A":"Cloranfenicol.","B":"Clindamicina.","C":"Tetraciclina.","D":"Sulfametoxazol-trimetropim.","E":"Amoxicilina."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-218033","number":"218033","sourceNumber":"218033","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Adolescente, 14 anos, sexo masculino, é levado à emergência por apresentar febre alta\ne dores no corpo. Mãe relata que o quadro\nteve início há dois dias com temperatura mantida em\n38,5°C a cada quatro horas e que ontem acordou com fortes dores nas mãos e pés e hoje surgiram\npintinhas generalizadas no corpo com muita coceira. Mãe refere que teve dengue há dez dias e que\nmora numa área infestada de mosquitos. Exame físico: não consegue deambular sozinho, febril\n(38°C), hidratado, eupneico, anictérico, FR = 36 irpm, FC = 96 bpm, SatO2 = 96%, PA = 100 x 60\nmmHg. Edema de mãos e pés ++/4+, exantema morbiliforme pruriginoso em face, tronco e\nmembros superiores. Laboratório: Hm = 3.500.000/mm³; Hb = 12,8 g/dl; Ht = 38%, leucócitos =\n6.500/mm³, bastões = 2%, segmentados = 32%, linfócitos = 39%, monócitos = 5%. 6 mm/1ª h,\nplaquetas = 230.000/mm³. O quadro descrito sugere:","options":{"A":"Zika.","B":"Chikungunya","C":"Febre amarela.","D":"Dengue hemorrágico.","E":"Febre reumática."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-175000","number":"175000","sourceNumber":"175000","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No paciente com suspeita ou diagnóstico de dengue, a dor abdominal constitui um dos\nsinais de alarme que serve para orientar a classificação de risco e o manejo do paciente.\n\nInicialmente, essa dor pode ser caracterizada por desconforto intenso e persistente, podendo estar\nlocalizada no (a):","options":{"A":"Região umbilical.","B":"Região hipogástrica.","C":"Hipocôndrio direito.","D":"Hipocôndrio esquerdo.","E":"Flanco direito."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-175055","number":"175055","sourceNumber":"175055","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um pré-escolar de dois anos, sexo masculino, é internado em uma unidade hospitalar\npara investigar quadro de palidez e\nhepatoesplenomegalia. A mãe relata início dos sintomas há\ndois meses, com febre baixa diária e astenia. Após 5 semanas de febre, persistiram fadiga e\ndiarreia eventual. Exame físico: peso=9.500g, comprimento=80cm, FC= 126bpm, FR= 32irpm,\nPA=80X60mmHg, petéquias generalizadas, fígado palpável a 4cm do RCD de consistência normal,\nborda lisa, doloroso à palpação e baço palpável à 8cm do RCE de consistência aumentada.\n\nExames laboratoriais: hemograma= anemia moderada, leucopenia e trombocitopenia. O\ndiagnóstico mais provável, considerando o quadro descrito, é:","options":{"A":"Dengue","B":"Febre amarela","C":"Linfoma de Hodgkin","D":"Mononucleose infecciosa","E":"Calazar"},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-160391","number":"160391","sourceNumber":"160391","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um serviço de saúde que atende casos de Dengue deve estar atento para os \"sinais de\nalarme\", que sugerem gravidade. Qual das seguintes opções corresponde a um destes sinais?","options":{"A":"Artralgias.","B":"Prova do laço positiva.","C":"Petéquias.","D":"Leucopenia.","E":"Vômitos persistentes."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-154416","number":"154416","sourceNumber":"154416","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Fazem diagnóstico diferencial com a Febre Chikungunya, segundo o manual para\nManejo Clínico (Ministério da Saúde, 2015) as seguintes patologias:","options":{"A":"Malária, febre tifoide, linfoma, meningite, viral, dengue, artrite.","B":"Malária, febre amarela, dengue, meningite bacteriana, artrite.","C":"Malária, febre tifoide, dengue, meningite viral, linfoma, artrite.","D":"Malária, leptospirose, febre reumática, artrite séptica, dengue.","E":"Malária, febre amarela, dengue, meningite viral, artrite."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-160443","number":"160443","sourceNumber":"160443","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Um homem de 40 anos, proveniente do Rio de Janeiro, vinha há 3 dias com febre alta,\nprostração e mialgias intensas. Hoje a febre cedeu, porém queixa-se de cansaço, dor abdominal e\nvômitos persistentes. No exame físico, a PA é de 100 x 60 mmHg, a FC é de 110 bpm e a FR é de\n28 irpm. A conduta mais apropriada é:","options":{"A":"Internação + hemoculturas + antibióticos de largo espectro.","B":"Coletar hemograma, bioquímica e PCRt e aguardar resultados.","C":"Hidratação oral 80 ml/kg/dia + retorno em 48h para reavaliação.","D":"Internação + cristaloide 20 ml/kg em 2 horas.","E":"Realizar prova do laço, hemograma e coagulograma para definir conduta."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-154428","number":"154428","sourceNumber":"154428","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, 27 anos, há três dias apresenta febre, cefaleia retro-orbital, mialgia e\nexantema cutâneo morbiliforme. Há oito dias\nretornou de São Luís para São Paulo e há um dia\ncomeçou a apresentar petéquias e teste do torniquete positivo. Ao exame clínico, apresentava PA =\n110 x 70 mmHg; FC = 85 bpm; temperatura = 36,8°C. Exames laboratoriais iniciais evidenciaram:\nhemoglobina = 12,3; leucócitos = 2.500; plaquetas = 110.000; INR e TTPa normais, sorologia para\ndengue (IgM) positiva. O quadro clínico caracteriza o diagnóstico de:","options":{"A":"Dengue clássica.","B":"Dengue hemorrágica.","C":"Síndrome de choque da dengue.","D":"Dengue hemorrágica com CIVD.","E":"Dengue com comprometimento neurológico."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-160423","number":"160423","sourceNumber":"160423","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A situação epidemiológica da dengue no país permanece caracterizada pelo número\ncrescente de casos graves e óbitos nos\núltimos dez anos, além dos novos desafios impostos pela\ncirculação dos vírus da febre de chikungunya e zika, cujos sintomas são parecidos com os da\ndengue, e fazem com que o tema se torne ainda mais importante. Segundo a 5ª edição do\n\"Dengue: diagnóstico e manejo clínico - adulto e criança\" do Ministério da Saúde, de 2016, pode-se\nafirmar que:","options":{"A":"A prova do laço deve ser realizada na triagem, obrigatoriamente, em todo paciente com suspeita\nde dengue e que não apresente sangramento\nespontâneo. A prova deverá ser repetida no\nacompanhamento clínico do paciente apenas se previamente negativa.","B":"A dipirona e os anti-inflamatórios não hormonais (cetoprofeno, ibuprofeno, diclofenaco,\nnimesulida) podem ser utilizados no tratamento da fase febril da dengue.","C":"Para a confirmação laboratorial, o método Enzyme-Linked Immunosorbent Assay (ELISA) deve\nser solicitado a partir do início dos sintomas.","D":"A detecção de antígenos virais: NS1, isolamento viral, RT-PCR e imunohistoquímica devem ser\nsolicitados após o quinto dia do início dos sintomas. Se forem positivos confirmam o caso.","E":"A impossibilidade de seguimento ou retorno à unidade de saúde não é indicado para internação\nhospitalar."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-103914","number":"103914","sourceNumber":"103914","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em um paciente com suspeita de meningoencefalite aguda, em que situação a punção\nliquórica deverá ser precedida por TC de crânio?","options":{"A":"Em pacientes com mais de 60 anos.","B":"Quando não houver neurologista na emergência para punção.","C":"Se houver febre acima de 40°C.","D":"Quando o paciente for imunodeprimido.","E":"Sempre."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-108059","number":"108059","sourceNumber":"108059","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O trecho da reportagem a seguir foi publicado em 13/11/2014 no portal g1.globo.com:\n\"Navio com destino ao MA deixa práticos em\nalerta para surto de Ebola. Um navio cargueiro de\nbandeira holandesa Clipper Alba, que partiu da Libéria, e que estava ancorado em território\namapaense, está seguindo, desde esta quinta-feira (13), com a sua embarcação, com destino ao\nPorto do Itaqui, em São Luís. [...] Sobre o assunto, a ANVISA informou que a previsão é de que a\ninspeção seja feita normalmente, já que não há, até o momento, nenhum relato concreto de\nsuspeita da doença a bordo.\" Disponível em:\n\"http://g1.globo.com/ma/maranhao/noticia/2014/11/navio-com-destino-ao-ma-deixa-praticos-em-aler\nta-para-surto-de-ebola.html.\" Os critérios para definição de infecção pelo Ebola envolvem aspectos\nclínicos e epidemiológicos. Observe as variáveis a seguir: I. Paciente procedente há menos de 21\ndias de países com casos confirmados de Ebola, como Libéria e Estados Unidos; II. Paciente com\nfebre e, obrigatoriamente, um dos seguintes: tosse, diarreia ou fenômenos hemorrágicos; III.\nPaciente com relato de contato com indivíduo suspeito, ainda sem confirmação de infecção por\nEbola. Faz parte dos critérios estabelecidos pelo Ministério da Saúde do Brasil, no ano de 2014,\npara caso suspeito de infecção de Ebola:","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e II.","E":"Apenas II e III."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-65567","number":"65567","sourceNumber":"65567","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à antibioticoprofilaxia cirúrgica, podemos afirmar que:","options":{"A":"A Cefazolina, uma cefalosporina de 2º geração, é muito ativa contra cocos Gram-positivos.","B":"A Cefoxitina, uma cefalosporina de 1º geração, apresenta boa atividade contra anaeróbios.","C":"A Cefoxitina, uma cefalosporina de 2º geração, apresenta boa atividade contra anaeróbios.","D":"A Cefazolina, uma cefalosporina de 1ª geração, é pouco ativa contra cocos Gram-positivos.","E":"Nenhuma das anteriores."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-65612","number":"65612","sourceNumber":"65612","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Das afirmativas abaixo, a respeito das meningites bacterianas agudas, assinale a\nincorreta.","options":{"A":"São causadas principalmente por pneumococos, meningococos, hemófilos e estreptococos do\ngrupo B.","B":"O quadro clínico pode apresentar três síndromes: síndrome de hipertensão intracraniana,\nsíndrome toxêmica e síndrome de irritação meníngea. A\npresença de duas das três síndromes\nsugere o diagnóstico.","C":"É preconizado o uso sistemático de corticosteroides no tratamento de meningite aguda.","D":"A droga de primeira escolha para o tratamento de meningite bacteriana aguda em pacientes\nentre 18 e 50 anos é a ceftriaxona ou a\ncefotaxima.","E":"Na maioria dos pacientes tratados, a melhora do quadro de confusão mental ocorre após 24h de\nevolução."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-65654","number":"65654","sourceNumber":"65654","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Meningoencefalite é definida como um processo inflamatório do cérebro e das\nmeninges, cuja etiologia mais comum é infecciosa. Identifique qual das afirmativas acerca da\nMeningoencefalite é incorreta.","options":{"A":"O quadro clínico varia segundo a faixa etária, etiologia, região do cérebro acometida e\ncomprometimento meníngeo;","B":"O vírus da parotidite (caxumba) é um agente frequente de meningoencefalite viral nos pacientes\nnão vacinados ou sem imunidade completa;","C":"As alterações do líquido cefalorraquidiano (LCR) na Meningoencefalite viral são geralmente:\naumento de celularidade e proteína normal ou\naumentada;","D":"A gravidade da doença depende do agente etiológico, diagnóstico precoce, faixa etária e estado\nimunológico do paciente;","E":"Meningoencefalite por Mycoplasma pneumoniae é raro em crianças maiores de 05 anos com\nsintomas respiratórios que antecedem os sintomas de Meningoencefalite."},"answer":"E","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-52493","number":"52493","sourceNumber":"52493","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Uma criança de 5 anos de idade apresenta um quadro agudo de cefaleia, febre baixa e\nvômitos. Ao exame observamos bom estado geral, com rigidez de nuca e sinais de Kerning e\nBrudzinski positivos.Realizado exame do LCR imediato, com o seguinte resultado: punção lombar ?\n400 leucócitos, 35% de neutrófilos, 15% de monócitos, 50% de linfócitos, proteínas de 53, glicose\n56 mg% e bacterioscopia negativa. Qual das afirmações abaixo é a errada?","options":{"A":"O diagnóstico é provavelmente de meningite viral.","B":"Penicilina e cloranfenicol são os antimicrobianos de eleição neste caso, devido à idade da\ncriança e ao exame liquórico.","C":"A conduta é expectante, com terapêutica de suporte.","D":"Pode haver indicação de novo exame liquórico, conforme evolução do paciente.","E":"A desidratação por vômito é uma complicação frequente."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-52466","number":"52466","sourceNumber":"52466","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 22 anos, masculino, dá entrada no Hospital com queixa de mal-estar, febre\ne dores no corpo há 2 horas. Ao exame\nencontra-se consciente, orientado, anictérico, febril (T.\naxilar = 38,5°C), com nuca livre. Presença de manchas purpúricas em membros inferiores e tronco.\nAusculta cardíaca e respiratória normais, FC = 120 e TA = 80 x 50 mmHg. O abdome é flácido.\n\nExames laboratoriais mostram leucocitose com desvio à esquerda e plaquetopenia leve, função\nrenal DHL normais e discreta elevação nas\ntransaminases. Após o atendimento inicial e hidratação\ncom 1000 ml de cristaloide, paciente evolui com piora clínica e rebaixamento do nível de\nconsciência sendo admitido à Unidade de Terapia Intensiva, onde vem a falecer cerca de 8h após a\nentrada na emergência. Qual o provável diagnóstico?","options":{"A":"Púrpura trombocitopênica trombótica.","B":"Meningococcemia.","C":"Dengue hemorrágica.","D":"Leptospirose.","E":"Fasceíte necrotizante."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-362854","number":"362854","sourceNumber":"362854","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem, 34 anos, mecânico, natural e procedente de São Paulo/SP, esteve em viagem\nturística de pesca pelo sul do Amazonas há 20 dias. Foi internado em UTI por quadro de prostração\nintensa, rebaixamento do sensório, hemorragias, icterícia, oliguria e albuminuria, que havia\niniciado\ncom febre, cefaleia, mialgia, náuseas e vômitos. Faleceu no 7º dia de doença. Na autopsia chamou\natenção, ao estudo anatomopatológico, as lesões hepáticas do tipo \"necrose médio-zonal\". Qual o\ndiagnóstico?","options":{"A":"Febre amarela.","B":"Dengue.","C":"Malária.","D":"Febre maculosa."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-346619","number":"346619","sourceNumber":"346619","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em se tratando da malária, assinale a alternativa ERRADA:","options":{"A":"A gravidade da doença correlaciona-se sobretudo com a porcentagem de eritrócitos infectados e\ncom a presença de pigmento malárico em mais de 5% dos neutrófilos.","B":"A infecção por Plasmodium malariae pode acompanhar-se de síndrome nefrótica decorrente de\nglomerulopatia por imunocomplexos.","C":"Na vigência da deficiência de glicose-6-fosfato desidrogenase, a primaquina, uma das drogas\nutilizadas no tratamento da protozoose, pode provocar, em seus usuários, hemólise decorrente de\nestresse oxidativo sobre os eritrócitos.","D":"Os pacientes com traço falciforme (hemoglobina AS) são particularmente suscetíveis à infecção\npor Plasmodium falciparum que, nesses pacientes, se\nreveste de maior gravidade."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-330845","number":"330845","sourceNumber":"330845","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, 50 anos, teve o diagnóstico de malária por Plasmodium\nfalciparum, realizado por gota espessa. A paciente está bem clinicamente, sem necessidade de\ninternação. Qual é o esquema terapêutico para o tratamento desta paciente?","options":{"A":"Clindamicina + primaquina","B":"Difosfato de cloroquina + primaquina","C":"Difosfato de cloroquina + clindamicina","D":"Artemeter + lumefantrina + primaquina"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-327337","number":"327337","sourceNumber":"327337","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem, 37 anos, agricultor, procedente de Belém do Pará, vem à consulta com queixa\nde febre há 30 dias, não mensurada,\nepisódios de náuseas e vômitos. Nos primeiros 15 dias, a\nfebre era diária seguida de calafrios. Após esse período, a febre surgia a cada 2 dias, com início\nabrupto seguido por calafrios e sudorese intensa. Fez uso de dipirona 1g. Nega doenças prévias.\n\nAo exame físico: REG, mucosas hipocoradas ++/4+, PA= 120 x 80 mmHg, FC= 99 bpm, FR= 18\nirpm, temp. axilar 39° C, Peso = 70 kg. Abdome globoso, fígado palpável 2 cm do rebordo costal\ndireito e baço palpável 3 cm do rebordo costal esquerdo. Demais dados do exame físico sem\nalterações. Foi realizada hematoscopia do sangue periférico com presença de Plasmodium vivax\nem hemácias. Qual tratamento deve ser prescrito ao paciente?","options":{"A":"Cloroquina 7 dias e primaquina 3 dias, dose única, após as refeições.","B":"Cloroquina 3 dias e primaquina 7 dias, dose única, após as refeições.","C":"Arteméter 3 dias e lumefantrina 5 dias, de 12/12 horas, em jejum.","D":"Artesunato+mefloquina 3 dias e primaquina 14 dias, dose única, após as refeições."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-346644","number":"346644","sourceNumber":"346644","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Os sintomas da Chikungunya são parecidos com os da dengue. Assinale a opção com\na manifestação clínica MAIS FREQUENTE na\nChikungunya do que na dengue:","options":{"A":"Convulsões","B":"Dores articulares","C":"Tipo de exantema","D":"Vômitos incoercíveis"},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-330901","number":"330901","sourceNumber":"330901","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente, 8 anos de idade, com quadro de febre há 4 dias, chegando a 39ºC,\nintermitente, com necessidade de uso de\nantipirético a cada 6 a 8 horas. Família procurou pronto\natendimento no primeiro dia do quadro e, por não haver outros sintomas associados, orientada\nretornar em 72 horas do início do quadro ou antes, se aparecessem novos sintomas. Família\nretorna no 4º dia de febre, pela persistência da mesma associada à tosse seca esporádica e dor\ntorácica, além de queixa de hiporexia, dor no corpo de caráter inespecífico, cefaleia frontal e\naparecimento de náuseas e vômitos, cerca de 2 a 3 episódios no dia. Ao ser examinada, paciente\napresenta estabilidade hemodinâmica e do ponto de vista respiratório murmúrio vesicular abolido\nna base esquerda, com macicez à percussão, além de dor à palpação profunda do hipocôndrio\ndireito, sem descompressão súbita dolorosa, o abdome é flácido. O plantonista solicita, então,\n\nraio-X de tórax, que evidencia opacidade na base esquerda, com apagamento do seio costofrênico\nipsilateral. Solicita exames laboratoriais\ncujos resultados são: Hemoglobina 11 g/dL, Hematócrito\n40%, Leucócitos 4.500/mm³ (Neutrófilos 25%, Eosinófilos 4%, Basófilos 1%, Linfócitos 60%,\nMonócitos 10%), PCR 20 mg/dL (VR até 5 mg/dL), Plaquetas 90.000/m³. Houve, após coleta dos\nexames, aparecimento de petéquias no local da punção. Assinale a afirmativa que apresenta\nprovável diagnóstico e conduta.","options":{"A":"Trata-se de provável quadro de dengue classe C. Paciente deve receber expansão volêmica e\nsintomáticos.","B":"Trata-se de provável caso de meningococcemia. Paciente deve receber expansão volêmica,\ncoleta de hemocultura e início de\nantibioticoterapia na primeira hora.","C":"Trata-se de provável púrpura trombocitopênica idiopática desencadeada por infecção de vias\náreas. Paciente deve receber imunoglobulina.","D":"Trata-se de provável sepse de foco pulmonar complicada com derrame pleural. Paciente deve\nreceber antibioticoterapia e ser submetida à toracocentese de alívio."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-308322","number":"308322","sourceNumber":"308322","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em fevereiro de 2021, a Secretaria Estadual de Saúde do Estado de Mato Grosso fez\num alerta sobre o aumento expressivo do\nnúmero de casos de malária no Estado (mais de 300% de\naumento). O principal alerta da secretaria foi a respeito da importância do diagnóstico, analise as\nafirmativas. I- O diagnóstico, em áreas de transmissão de malária, deve ser pensado em qualquer\nindivíduo com febre de qualquer intensidade, duração e frequência. II- O método mais utilizado para\no diagnóstico é a microscopia de gota espessa de sangue, colhida por punção digital e corada pelo\nmétodo de Walker. III- No teste rápido para malária, que se baseia na detecção de antígeno, é\npossível detectar tanto o Plamodium vivax, Plasmodium falciparum, quanto a malária mista, tendo\nmaior sensibilidade para a malária vivax. IV- O diagnóstico por técnicas moleculares (RT-PCR) é\nmais preciso e este já é um teste rotineiro nos serviços de referência, devendo substituir a gota\nespessa. Estão corretas as afirmativas","options":{"A":"I, II e IV, apenas.","B":"II e III, apenas.","C":"III e IV, apenas.","D":"I e II, apenas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-316025","number":"316025","sourceNumber":"316025","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A medida mais importante de controle epidemiológico da dengue é o(a):","options":{"A":"Isolamento dos doentes","B":"Vacinação dos não imunes","C":"Tratamento dos casos graves","D":"Diminuição da densidade de vetores","E":"Controle dos viajantes de áreas endêmicas"},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-316030","number":"316030","sourceNumber":"316030","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"L.R., de 26 anos, sexo masculino, vem para uma consulta de emergência na unidade\nde saúde. Ao realizar a anamnese, o paciente\nrelata forte dor de cabeça, tonturas, moleza, dor no\ncorpo e febre alta, com início súbito. Ao realizar exame físico, o médico verifica manchas\navermelhadas e erupções na pele, principalmente na região do tórax, e o paciente relata dor nas\narticulações ao fazer o movimento de abdução e adução dos braços. Ao final do exame, relata dor\nintensa atrás dos olhos, que piora com o movimento deles. Tendo em vista o relato, o possível\ndiagnóstico é:","options":{"A":"Rubéola.","B":"Sarampo.","C":"Febre amarela.","D":"Dengue.","E":"Influenza A."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-313406","number":"313406","sourceNumber":"313406","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 36 anos, previamente hígido, morador de Cuiabá, representante comercial\nde uma empresa de alimentos, com viagem há 16\ndias para Rondônia, vem para consulta em\npronto atendimento com queixa de febre acima de 40ºC acompanhada de sudorese iniciada há\ncerca de quatro dias, com período de acalmia entre crises. À ectoscopia apresenta-se ictérico +/4+\ne hipocorado +/4+. Palpação abdominal revela hepatoespienomegalia dolorosa. Diante da principal\nhipótese diagnóstica, o exame mais indicado seria o (a):","options":{"A":"Microscopia de campo escuro;","B":"Esfregaço de sangue periférico;","C":"Antígeno ns1 por imunocromatografia;","D":"RT-PCR para detecção do genoma viral."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-288139","number":"288139","sourceNumber":"288139","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 50 anos, sexo masculino, previamente hígido, apresenta há dois dias febre\ndiária, calafrios, mal-estar, prostração e mialgia. Ao exame físico, PA: 120 x 70 mmHg, FC: 110\nbpm, FR: 24 irm, T: 39°C. Regular estado geral, acianótico, anictérico, leve taquipneia, hipocorado\n1+/4+, desidratado 2+/4+, confuso (ECG 14). RCR, 2T, BNF, sem sopro. MV preservado e sem RA.\nAbdome plano, RHA+, timpanismo, indolor e sem visceromegalias. Perfusão periférica diminuída.\n\nSabendo que o paciente trabalha como advogado e viajou recentemente para o norte de Mato\nGrosso, assinale a afirmativa INCORRETA.","options":{"A":"Pode ser malária, devendo-se realizar gota espessa para o diagnóstico (pesquisa de\nPlasmodium spp.), suporte clínico e tratamento específico.","B":"Pode ser dengue, devendo-se hidratar o paciente, suporte clínico, monitorização quanto ao\nsurgimento de sinais de gravidade e solicitar sorologia para dengue (IgM e IgG) para realização do\ndiagnóstico.","C":"Pode ser dengue, devendo-se hidratar o paciente, suporte clínico, monitorização quanto ao\nsurgimento de sinais de gravidade e solicitar pesquisa do antígeno NS1 para realização do\ndiagnóstico.","D":"Pode ser sepse de foco indeterminado, devendo-se hidratar o paciente, suporte clínico,\nmonitorização quanto à piora clínica, coleta de\nexames laboratoriais, culturas, procalcitonina e início\nde antimicrobianos de amplo espectro."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-258915","number":"258915","sourceNumber":"258915","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Mulher, 18 anos, é atendida em UPA de Cuiabá, com quadro de febre de início há\nquatro dias (39°C), de início abrupto,\nseguida de cefaleia, mialgia, prostração, artralgia, anorexia,\nnáuseas, vômitos e exantema que vem piorando durante o período. Ao exame físico, são\nidentificadas hepatomegalia dolorosa, extremidades frias, sudorese, PA = 90/60 mmHg e FC = 120\nbpm. Nessas condições, qual a principal hipótese diagnóstica e conduta inicial?","options":{"A":"Febre amarela; pesquisa de genoma viral por RT-PCR no sangue, bilirrubina na urina,\nhidratação e uso de riboflavina.","B":"Leptospirose; exame de sangue Microaglutinação (MAT), hidratação, reposição de plasma, uso\nde aciclovir.","C":"Febre hemorrágica da dengue; prova do laço, hidratação endovenosa imediata, internação\nhospitalar e monitoração hemodinâmica.","D":"Hepatite infecciosa; identificação do antígeno Austrália, hidratação, sintomáticos e\nmonitorização\nde sinais vitais."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-274136","number":"274136","sourceNumber":"274136","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Pré-escolar, 4 anos de idade, sexo feminino, natural e procedente de Várzea\nGrande-MT, residente na área rural, deu entrada na UPA com quadro de febre de 39ºC,\n\nintermitente e irregular com 2 ou 3 picos por dia há 3 semanas, astenia, perda de peso. Ao exame,\nsinais vitais: Fr: 28 irpm, Fc: 130 bpm,\nTAx: 39,3ºC. REG, prostrada, palidez cutâneo-mucosa,\nhidratada. A ausculta cardíaca e pulmonar eram normais. Abdome globoso, ruídos hidroaéreos\npositivos, à palpação, fígado a 3 cm RCD e baço a 5 cm do RCE, sem sinal de irritação peritoneal.\nLinfonodos não palpáveis. Demais sem alteração. Hemograma: hemácias: 3,6 milhões, Hb: 9,0 g/dl,\nHt: 27%; leucócitos: 3.900 mm³; plaquetas: 60.000 mm³; ureia: 17 mg/dl; creatinina: 0,6 mg/dl; VHS:\n55mm; bilirrubina total: 0,3 mg/dl; bilirrubina indireta: 0,2 mg/dl; bilirrubina direta: 0,1 mg/dl;\namilase:\n153 mg/dl; AST: 27 U/ml; ALT: 15 U/ml; proteínas totais: 5,15; albumina: 3,0 mg/dl; globulina: 2,15\nmg/dl. Qual é a principal hipótese diagnóstica?","options":{"A":"Esquistossomose.","B":"Linfoma de Hodgkin.","C":"Malária por P. falciparum.","D":"Leishmaniose visceral."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-283982","number":"283982","sourceNumber":"283982","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem, 38 anos, previamente hígido, morador da baixada cuiabana, representante de\nlaboratório com viagem há 16 dias para Rondônia, vem para consulta em pronto atendimento com\nqueixa de febre acima de 40ºC acompanhada de sudorese iniciada há cerca de quatro dias, com\nperíodo de acalmia entre crises. À ectoscopia apresenta-se ictérico +/4+ e hipocorado +/4+.\n\nPalpação abdominal revela hepatoesplenomegalia dolorosa. Diante da principal hipótese\ndiagnóstica, o exame mais indicado seria o(a):","options":{"A":"Microscopia de campo escuro.","B":"Esfregaço de sangue periférico.","C":"Antígeno NS1 por imunocromatografia.","D":"RT-PCR para detecção do genoma viral."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-258953","number":"258953","sourceNumber":"258953","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre o vetor responsável pela transmissão da dengue, analise as seguintes\nafirmativas: I- No Brasil, a dengue só é\ntransmitida pelo mosquito Aedes aegypti. II- Aedes\nalbopictus é o vetor de manutenção da dengue em alguns países orientais. III- A espécie A. aegypti\ntambém pode ser transmissora do vírus da febre amarela em áreas urbanas. IV- A picada do A.\naegypti ocorre sempre no período diurno. Estão corretas as afirmativas","options":{"A":"I, II e IV, apenas.","B":"II e III, apenas.","C":"III e IV, apenas.","D":"I, II, III e IV."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-214597","number":"214597","sourceNumber":"214597","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, 38 anos, previamente hígida, apresentando há cinco dias\nfebre, calafrios, mal-estar, mialgia, astenia e sudorese fria. Mora em Rondônia, trabalha em\nescritório de advocacia e não teve viagens recentes. Conforme os dados clínicos e\nepidemiológicos, a principal hipótese diagnóstica é:","options":{"A":"Malária.","B":"Pneumonia.","C":"Infecção do trato urinário.","D":"Gripe."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221150","number":"221150","sourceNumber":"221150","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 8 anos iniciou há 9 dias quadro de febre moderada, contínua,\nacompanhada de cefaleia, mialgia muito\nimportante e prostração. Atendido na Unidade Básica de\nSaúde, realizou a prova do laço, que foi positiva, e recebeu diagnóstico de dengue. Foram\nprescritos analgésicos, hidratação abundante e repouso. Hoje retorna à unidade de saúde e sua\nmãe relata que a febre desapareceu há 4 dias, mas continua muito prostrado, desde ontem\ncomeçou a vomitar, sente dores constantes no abdome e tonturas quando se levanta. Ao exame\nclínico, estava sonolento, normotenso, com boa perfusão periférica, fígado doloroso à palpação e\nmurmúrio vesicular diminuído em ambas as bases pulmonares. Resultados dos exames\nlaboratoriais solicitados: hemoglobina = 12,5 g/dl; hematócrito = 46%; leucócitos = 5.350/mm³;\nneutrófilos = 52%; linfócitos = 36%; eosinófilos = 3%; plaquetas = 68.000/mm³; albumina = 2,9 g/dl.\nEm relação ao caso acima, marque V para as afirmativas Verdadeiras e F para as Falsas. ( ) Já no\nprimeiro atendimento, a criança apresentava sinais de sangramento oculto, como evidenciado pela\nprova do laço positiva. ( ) A queda das plaquetas sugere a intensidade da perda de volume para o\nterceiro espaço e é um preditor da gravidade. ( ) Essa criança apresenta sinais de alerta de\ngravidade e achados clínicos que a classificam como categoria C. ( ) Deve-se iniciar\nimediatamente hidratação venosa vigorosa na Unidade Básica de Saúde e encaminhá-lo a uma\nunidade de maior complexidade para seguimento. ( ) Como a criança está na segunda semana da\ndoença, já não é mais possível solicitar sorologia diagnóstica IgM e IgG, que só seriam positivas\naté\no quinto dia. ( ) Como o paciente já está na fase de convalescência da dengue, é provável que o\nquadro atual seja de complicação bacteriana, comum nos casos de dengue grave. Assinale a\nsequência CORRETA.","options":{"A":"V?V? F?F?V?F.","B":"V?F?V?V?F?F.","C":"F?V?F?F?V?V.","D":"F?F?V?V?F?V."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221036","number":"221036","sourceNumber":"221036","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 4 anos, proveniente de zona rural do interior do Mato Grosso, é internado\ncom história de febre e emagrecimento há 3\nmeses. Há cerca de um mês foi internado para\ntratamento de pneumonia por 10 dias, recebendo antibióticos e duas transfusões de concentrado\nde hemácias. Após a alta, ainda mantinha febre diária e emagrecimento e a mãe percebeu\naumento do volume abdominal, palidez, apatia e perda do apetite. Ao exame físico, a criança\napresenta panículo adiposo escasso, palidez cutâneo-mucosa de 3+/4+, petéquias na face e\nmembros inferiores, discreta adenomegalia inguinal. Abdome volumoso, sem ascite, com fígado\npalpável a 6 cm da Reborda Costal Direita (RCD) e o baço a 8 cm da RCE. Sobre o caso acima,\nmarque V para as afirmativas Verdadeiras e F para as Falsas. ( ) O paciente apresenta quadro\nclínico e laboratorial compatível com o diagnóstico de linfoma, leishmaniose visceral e\nparacoccidioidomicose sistêmica. ( ) A hipótese de paracoccidioidomicose é improvável pela\nausência de lesões mucosas e pulmonares em forma de borboleta. ( ) O diagnóstico mais provável\né o de linfoma, pois tanto a leishmaniose visceral como a paracoccidioidomicose são doenças raras\nna infância. ( ) O mielograma com pesquisa de fungos e parasitas é o exame indicado para fazer o\ndiagnóstico diferencial. ( ) Resultado positivo da sorologia para leishmaniose visceral (Leishmania\nsp.) em qualquer título confirma o diagnóstico. ( ) Caso no mielograma sejam encontradas formas\namastigotas de Leishmania sp., essa criança tem leishmaniose visceral com sinais de gravidade e\nindicação de Anfotericina lipossomal e antibióticos. Assinale a sequência CORRETA.","options":{"A":"F, V, V, V, F, F.","B":"V, F, F, V, F, V.","C":"F, V, F, F, V, V.","D":"V, F, V, F, V, F."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":["question_bank/media/medcurso/medcurso-infectologia-inf-3/221036.png"],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221344","number":"221344","sourceNumber":"221344","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em pacientes com chikungunya o sintoma mais comum na fase crônica é o\nacometimento articular persistente ou recidivante, podemos, apenas, CONCORDAR que","options":{"A":"não nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e ausência de eritema.","B":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, sem limitação de movimento, deformidade e ausência de eritema.","C":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e ausência de eritema.","D":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e presença de eritema."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221369","number":"221369","sourceNumber":"221369","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A prevalência da fase crônica em pacientes com chikungunya é bastante variável,\nsegundo os estudos, podendo atingir mais da\nmetade dos pacientes. Os principais fatores de risco\npara a cronificação são listados abaixo, indique a INADEQUADA.","options":{"A":"Idade acima de 65 anos.","B":"Sexo feminino.","C":"Desordem articular preexistente.","D":"Maior intensidade das lesões articulares na fase aguda."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-185212","number":"185212","sourceNumber":"185212","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre o diagnóstico de Dengue assinale a alternativa CORRETA:","options":{"A":"Prova do Laço positiva confirma o diagnóstico.","B":"Testes sorológicos para detecção de anticorpos (lgM e lgG) devem ser solicitados a partir do 6°\ndia de doença.","C":"Cultura viral deve ser solicitada a partir do 5° dia da doença, indicada em casos graves ou\nquando houver suspeita de entrada de novo\nsorotipo na região.","D":"A detecção do anticorpo NS1 deve ser feita nos primeiros 3 dias com sensibilidade de 90% na\ninfecção primária.","E":"A presença de leucopenia com trombocitose no hemograma coletado até o 5° dia da doença\nestá fortemente associada a Dengue."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-181594","number":"181594","sourceNumber":"181594","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente L.M.M., 50 anos, sexo masculino, advogado, mora em Várzea Grande-MT,\napresenta há dois meses febre diária,\nastenia, emagrecimento, hiporexia e aumento do volume\nabdominal. Nega viagem nos últimos três anos. Ao exame físico, evidenciada palidez cutânea e\nesplenomegalia importante. Qual é a conduta propedêutica e o diagnóstico mais provável?","options":{"A":"Gota espessa; Malária.","B":"Aspirado de medula óssea; Calazar.","C":"Raio-x de tórax; Tuberculose pulmonar.","D":"Ultrassonografia de abdome; Abscesso hepático."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-181601","number":"181601","sourceNumber":"181601","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente de 5 meses de idade, etnia indígena, apresenta quadro febril há 40 dias. Há\n15 dias a mãe percebeu aumento do volume\nabdominal, palidez e prostração. O exame físico\nmostrou esplenomegalia volumosa e hepatomegalia moderada. Ausência de adenomegalias.\n\nDiscreta icterícia, sangramento prolongado nos locais de punção. Exames laboratoriais iniciais: HB:\n7,0 g/dL; Leucócitos totais 2.300, sendo neutrófilos 550, linfócitos 1.200, sem atipia; plaquetas\n\n50.000, VHS 80 mm, Bilirrubinas Total 7,2, Direta 5,1, TGO 86, TGP 65; Albumina 2,9 g/dL,\nglobulinas 7,2 g/dL; Anticorpos contra Leishmania sp 1:80. O diagnóstico mais provável é:","options":{"A":"Leishmaniose visceral.","B":"Tuberculose disseminada.","C":"Malária.","D":"Leucemia aguda."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-181545","number":"181545","sourceNumber":"181545","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A respeito dos achados clínicos relativos às patologias citadas, numere a coluna da\ndireita de acordo com a da esquerda. 1 -\nDengue; 2 - Zika; 3 - Chikungunya; ( ) Acometimento fetal;\n( ) Febre alta, artralgia intensa, edema articular; ( ) Afebril, adenomegalia, exantema, hiperemia\nconjuntival; ( ) Febre, cefaleia, dor muscular, sem acometimento neurológico; ( ) Cronificação; ( )\nChoque. Assinale a sequência CORRETA.","options":{"A":"3, 1, 2, 3, 2, 1.","B":"2, 3, 2, 1, 3, 1.","C":"2, 2, 1, 3, 1, 3.","D":"1, 3, 2, 1, 2, 3."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-159387","number":"159387","sourceNumber":"159387","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Criança de 3 anos é trazida pela mãe na UBS apresentando febre constante de 39° C,\ncefaleia, dor no corpo e incapacidade de abaixar a cabeça há 3 dias, sem melhora com\nsintomáticos. O médico ouve atentamente as informações da mãe e suspeita de meningite. Ao\nexaminar a criança na posição supina, o médico faz uma flexão passiva do pescoço e observa que\no paciente apresenta uma flexão involuntária do joelho. Esta descrição quando positiva,\ncorresponde a um achado clínico denominado de:","options":{"A":"Sinal de Brudzinski.","B":"Sinal de Kernig.","C":"Sinal de Babinski.","D":"Manobra de Ortolani."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-136717","number":"136717","sourceNumber":"136717","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"O Aedes aegypti é um mosquito da família Culicidae proveniente da África. No Brasil,\nfoi erradicado em 1955, todavia, como alguns\npaíses da América do Sul mantinham a colonização\ndo vetor, seu retorno foi inevitável já na década de 70. Sua presença representa a ameaça de\nvárias doenças como a dengue, febre Zika, Chikungunya e febre amarela. Marque até quanto o\níndice de infestação Breteau é considerado tolerável:","options":{"A":"Menor do que 1.","B":"Menor do que 5.","C":"Menor do que 10.","D":"Menor do que 100."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-137001","number":"137001","sourceNumber":"137001","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Homem de 48 anos está internado na Unidade de Terapia Intensiva em estado grave,\ncreatinina de 2 mg/dL, hemodinamicamente instável, com catéter venoso central. Na\nhemocultura houve crescimento de cândida albicans. A melhor conduta é:","options":{"A":"Retirar o catéter venoso central e observar por ser candidemia transitória.","B":"Não retirar o catéter venoso central e iniciar fluconazol.","C":"Retirar o catéter venoso central e iniciar fluconazol via endovenosa.","D":"Não retirar o catéter venoso central e iniciar anfotericina B."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-109279","number":"109279","sourceNumber":"109279","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual antibiótico é indicado como adicional para tratamento empírico de meningite em\npaciente de 65 anos usando Ceftriaxona?","options":{"A":"Amoxicilina 8 g ao dia.","B":"Vancomicina, cálculo por peso.","C":"Gentamicina 1 g ao dia.","D":"Rifampicina 600 mg ao dia."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-88424","number":"88424","sourceNumber":"88424","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Qual o agente etiológico mais comum na bacteriúria assintomática?","options":{"A":"Staphylococcus aureus.","B":"Burkholderia cepacia.","C":"Proteus mirabilis.","D":"Escherichia coli."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-75389","number":"75389","sourceNumber":"75389","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale o conjunto de achados considerados sinais de alarme na evolução da forma\ngrave da dengue.","options":{"A":"Febre alta, hepatomegalia, trombocitopenia, anemia, derrame pleural e oligúria.","B":"Dor abdominal intensa, vômitos persistentes, derrames cavitários, fenômenos hemorrágicos\nespontâneos ou provocados, hemoconcentração e desconforto respiratório.","C":"Hipotermia, prova do laço positiva, anemia, poliúria, hepatomegalia e dor retro-ocular.","D":"Mialgias e artralgias intensas, letargia, prova do laço positiva, oligúria, leucocitose acima de\n\n15.000 e taquipneia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-75393","number":"75393","sourceNumber":"75393","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No tratamento da malária em gestantes, é contraindicado o uso de:","options":{"A":"Primaquina.","B":"Cloroquina.","C":"Quinina.","D":"Clindamicina."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-309771","number":"309771","sourceNumber":"309771","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente admitido com síndrome ictérica a esclarecer. Na anamnese é relatado quadro\nfebril de início súbito, cefaleia, mialgia\ndifusa, principalmente em panturrilhas. Exames laboratoriais:\nHb 12, Ht 31, leucograma 11.300, plaquetas 120.000; creatinina 1,8, ureia 80, sódio 135, potássio\n2,5. Enzimas hepáticas discretamente alteradas e caniculares sem alterações. Considerando a\nhipótese diagnóstica, assinale a alternativa CORRETA.","options":{"A":"Dengue ? solicitar a dosagem do antígeno NS1 após o 7º dia de sintoma.","B":"Leptospirose ? o diagnóstico pode ser feito pelo isolamento da bactéria no sangue.","C":"Febre amarela ? o tratamento é realizado com doxiciclina nos casos graves.","D":"Hepatite B ? febre na presença de pulso lento para a alta temperatura (sinal de Fabet).","E":"Colangite ? é necessário o início de antibioticoterapia e antitérmico."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-274882","number":"274882","sourceNumber":"274882","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente do sexo feminino, 33 anos, sem comorbidades, iniciou há 5 dias quadro febril,\ncom cefaleia, mialgia e artralgias. Nesse período, iniciou vômitos, dor abdominal e epistaxe.\n\nProcurou pronto atendimento médico e foi avaliada, apresentando-se consciente, orientada,\nnormotensa, diurese pouco concentrada. Exantema\npresente em todo o corpo. Por residir em área\nendêmica, com casos de dengue em elevação, foi considerado o diagnóstico clínico e\nepidemiológico. De acordo com os dados apresentados, em qual classificação de risco a paciente\nse encontra?","options":{"A":"Grupo A.","B":"Grupo B.","C":"Grupo C.","D":"Grupo D.","E":"Grupo E."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-286133","number":"286133","sourceNumber":"286133","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre as recomendações do Ministério da Saúde para a condução da dengue é correto\nafirmar:","options":{"A":"Considerar a prova do laço positiva quando houver 20 ou mais petéquias em adultos e 10 ou\nmais em crianças, em área analisada (quadrado de 2,5 cm de lado).","B":"Crianças classificadas como grupo C, da gravidade da dengue, tem benefício com o uso de\nsalicilatos devido ao risco de coagulopatia.","C":"A sorologia para dengue deve ser solicitada para todos os casos suspeitos à partir do 3º dia do\ninício dos sintomas.","D":"Nos casos em que o paciente não apresenta sinais de choque ou sinais de alarme, a prova do\nlaço negativa exclui o diagnóstico de dengue.","E":"A classificação da gravidade da dengue em grupos A, B, C e D utiliza como critérios a prova do\nlaço, sinais de alarme, tempo da doença e sinais de choque."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-274956","number":"274956","sourceNumber":"274956","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A febre amarela é uma doença imunoprevenível, causada pelo arbovírus amarílico\nflavivírus da família Flaviviridae,\ndistribuídos em regiões da África e América do Sul. Pode ser\ntransmitida pela picada das fêmeas do mosquito Aedes aegypti e Aedes albopictus (febre amarela\nurbana) e Haemagogus janthinomys (principal vetor da febre amarela silvestre no Brasil) e\nSabethes chloropterus (febre amarela silvestre). O quadro clínico da febre amarela caracteriza-se\npor (GUSSO, G. (Org); LOPES, J. M. C (Org); DIAS, L. C. Tratado de Medicina de Família e\nComunidade: princípios, formação e prática. 2ª ed. Porto Alegre: Artmed 2019):","options":{"A":"Mialgia generalizada, diarreia, hematêmese, icterícia verdínica e sinal de Faget.","B":"Mialgia na panturrilha, icterícia rubínica, sufusões hemorrágicas conjuntivais e síndrome de\nWeil.","C":"Mialgia generalizada, icterícia verdínica, vômitos alimentares ou biliosos e hemorragia\nconjuntival.","D":"Mialgia generalizada, icterícia verdínica, síndrome de Weil, hematêmese, melena e meningite.","E":"Mialgia na panturrilha, icterícia rubínica, calafrios e sinal de Charcot."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-239638","number":"239638","sourceNumber":"239638","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa correta quanto às características observadas na fase crítica da\ndengue clássica.","options":{"A":"Náusea, vômito e dor abdominal, linfadenopatias e exantema macular.","B":"Surgimento de prurido palmoplantar antes da remissão do exantema.","C":"Início súbito de febre, geralmente alta, acompanhada de cefaleia e dor retro-orbitária.","D":"Defervescência, entre 03 a 07 dias após o início dos sintomas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-239639","number":"239639","sourceNumber":"239639","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa correta sobre os três sinais de alarme da dengue.","options":{"A":"Dor abdominal intensa e contínua, hipotermia, hipotensão postural e/ou lipotimia.","B":"Dor abdominal intensa e contínua, hipotermia e aumento da diurese.","C":"Dor abdominal intensa e contínua, hipotensão postural e/ou lipotimia e aumento da diurese.","D":"Hipotermia, hipotensão postural e/ou lipotimia e aumento da diurese."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-239640","number":"239640","sourceNumber":"239640","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre a forma grave da dengue, aponte a afirmativa correta.","options":{"A":"Manifesta-se entre o sétimo e o décimo dia da doença.","B":"Em crianças, geralmente surge após o quinto dia da doença, acompanhada ou não de\ndefervescência.","C":"Durante o quadro, é possível encontrar o paciente com choque por conta de extravasamento de\nlíquidos para o terceiro espaço, com diminuição de perfusão de órgãos alvo e rebaixamento do\nnível de consciência.","D":"Ocorrem hemorragias graves, por fragilidade capilar, associadas à plaquetopenia e disfunção\norgânica."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-239641","number":"239641","sourceNumber":"239641","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"No manejo da dengue, qual desses pacientes deve ser considerado como do grupo B?","options":{"A":"Paciente com prova do laço negativa.","B":"Paciente com idade inferior a 02 anos.","C":"Paciente com hipotensão arterial na admissão.","D":"Paciente com hematócrito normal."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-247135","number":"247135","sourceNumber":"247135","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre o uso da dipirona no tratamento de exantema em crianças com febre decorrente\nde Chikungunya e Dengue, assinale a alternativa\ncorreta.","options":{"A":"A posologia sugerida é de 50 a 100 mg de cloridrato de tramadol a cada 4 ou 6 horas.","B":"O limite de administração é de 360 mg/dia.","C":"A dipirona é contraindicada em casos de depressão respiratória.","D":"A dipirona é contraindicada em menores de 3 meses de idade ou com peso menor que 5 kg.","E":"A dipirona deve ser administrada somente de 8 em 8 horas."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-213983","number":"213983","sourceNumber":"213983","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente sexo feminino, 39 anos, indígena, moradora de aldeia em Amambai, procura\nserviço médico queixando-se de dispneia,\nfraqueza, indisposição ao trabalho há cerca de 4 meses.\nAo exame físico, apresenta-se em regular estado geral, descorada 2/4+ emagrecida. Frequência\nrespiratória 18 ipm. Fc 90 bpm. Pa 110/70 mmhg t 38c. Ao exame físico, observa-se ausculta\ncardiopulmonar sem alterações. Abdome globoso flácido com rha+ doloroso difusamente à\npalpação com fígado 6 cm rcd e baço palpável cerca de 5 cm. Com relação ao quadro clínico\napresentado, afirma-se que","options":{"A":"esquistossomose é um diagnóstico diferencial, devendo-se realizar exame de fezes com\npesquisa do agente para realização do diagnóstico.","B":"hepatopatia crônica é o diagnóstico mais provável, devendo-se realizar provas sorológicas para\nhepatites virais e usg de abdome para complementação diagnóstica.","C":"paracoccidioidomicose disseminada e turberculose são os principais diagnósticos diferenciais,\ndevendo-se realizar exames de escarro para pesquisa dos agentes.","D":"leishmaniose visceral ou linfoma são diagnósticos prováveis, devendo-se ser realizado teste\nrápido de leishamiose e aspirado de medula óssea.","E":"neoplasiais abdominais são diagnósticos mais prováveis, devendo-se realizar tomografia\ncomputadorizada de abdome, endoscopia e coloscopia para auxiliar no diagnóstico correto."},"answer":"D","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-216889","number":"216889","sourceNumber":"216889","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A suspeita clínica de leishmaniose visceral deve ser levantada nos pacientes com febre\ne esplenomegalia associadas ou não à\nhepatomegalia. Precisamos ter alguns cuidados com estes\npacientes, principalmente na faixa etária pediátrica, destacando-se entre eles que:","options":{"A":"Pancitopenia é um achado frequente, sendo necessário estar atento para queda de neutrófilos\nabaixo de 500/mm³, situação em que o\npaciente deve ser conduzido como neutropenia febril.","B":"Não é frequente a elevação das transaminases hepáticas já que o comprometimento maior é\nesplênico.","C":"Pacientes com idade menor que 1 ano têm melhor prognóstico por ainda ter o sistema imune\nimaturo e não terem reações inflamatórias exacerbadas.","D":"No Brasil os medicamentos indicados para o tratamento da leishmaniose visceral são a\nanfotericina B lipossomal como primeira escolha para maioria dos casos e o antimoniato de\nN-metilglucamina para os casos mais graves."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221216","number":"221216","sourceNumber":"221216","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em pacientes com chikungunya o sintoma mais comum na fase crônica é o\nacometimento articular persistente ou recidivante, podemos, apenas, CONCORDAR que","options":{"A":"não nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e ausência de eritema.","B":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, sem limitação de movimento, deformidade e ausência de eritema.","C":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e ausência de eritema.","D":"nas mesmas articulações atingidas durante a fase aguda, caracterizado por dor com ou sem\nedema, limitação de movimento, deformidade e presença de eritema."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-221241","number":"221241","sourceNumber":"221241","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A prevalência da fase crônica em pacientes com chikungunya é bastante variável,\nsegundo os estudos, podendo atingir mais da\nmetade dos pacientes. Os principais fatores de risco\npara a cronificação são listados abaixo, indique a INADEQUADA.","options":{"A":"Idade acima de 65 anos.","B":"Sexo feminino.","C":"Desordem articular preexistente.","D":"Maior intensidade das lesões articulares na fase aguda."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-177011","number":"177011","sourceNumber":"177011","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Sobre leishmaniose visceral, marque a alternativa CORRETA:","options":{"A":"A leishmaniose visceral não é uma doença de notificação compulsória.","B":"A principal forma de transmissão da leishmaniose visceral é de pessoa a pessoa.","C":"A reação de imunofluorescência indireta bem como o exame parasitológico do aspirado de\nmedula óssea são técnicas utilizadas para diagnóstico laboratorial da leishmaniose visceral.","D":"Os antimoniais pentavalentes são as medicações de escolha pra tratar leishmaniose visceral em\npacientes que fazem uso de betabloqueadores e drogas antiarrítmicas."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-177094","number":"177094","sourceNumber":"177094","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Em relação à Dengue podemos afirmar que:","options":{"A":"o número de casos no Brasil tem demonstrado a necessidade de rever as estratégias de\ncombate ao vetor.","B":"o mosquito culex vetor biológico da Dengue, tem um ciclo obrigatório de vida onde o sangue\nhumano é essencial.","C":"os vasos de flores que acumulam água nos seus suportes (\"pratinhos\") não têm participação\nimportante na classificação dos criadouros.","D":"os casos de Dengue têm perdido sua gravidade ao longo do tempo."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-177138","number":"177138","sourceNumber":"177138","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa INCORRETA, frente a um caso de infecção pelo vírus ZIKV\n(Zika):","options":{"A":"Repouso hidratação e tratamento sintomático.","B":"Anti inflamatórios não hormonais em grandes doses.","C":"Tratamento imediato e, às vezes, suporte da medicina intensiva na ocorrência na síndrome de\nGuillain Barrè.","D":"Imunoglobulina e, em casos especiais, plasmaferese."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-177160","number":"177160","sourceNumber":"177160","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Assinale a alternativa incorreta em relação à Leishmaniose Visceral","options":{"A":"O coeficiente de incidência aumentou de 0,3 por 100.000 habitantes em 1990 para 4,1 por\n\n100.000 habitantes em 2016, no estado de Mato Grosso do Sul.","B":"Não existe medicamento específico para essa doença; por isso, a evolução é a mesma com ou\nsem tratamento.","C":"Trata-se de uma zoonose que tinha um caráter eminentemente rural e agora vem se expandindo\npelas zonas urbanas como um grave problema\nde saúde pública.","D":"Doença sistêmica caracterizada por febre de longa duração, perda de peso, astenia, adinamia e\nanemia."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-177165","number":"177165","sourceNumber":"177165","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A doença cujo nome significa \"aqueles que se dobram\"; que confere imunidade; tem\ninício súbito; dores articulares muito intensas; febre alta e historia de viagem para regiões onde\nestão ocorrendo casos é:","options":{"A":"Hanseníase","B":"Pneumonia pneumocócica","C":"Febre Chikungunya","D":"Lupus Eritematoso"},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151083","number":"151083","sourceNumber":"151083","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"São medidas de proteção contra a Dengue:","options":{"A":"Vacinação nas faixas etárias mais suscetíveis e uso prolongado de inseticidas de aplicação\nespacial.","B":"Queima de pneus e do lixo em geral.","C":"Eliminação de criadouros do vetor e alertas para diagnóstico precoce.","D":"Eliminação de toda e qualquer planta (vegetal) dos domicílios."},"answer":"C","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151057","number":"151057","sourceNumber":"151057","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"A febre Chikungunya:","options":{"A":"É transmitida pelos mosquitos Aedes aegypti e Aedes albopictus.","B":"É de curtíssima duração e baixa sintomatologia.","C":"Não permite confirmação laboratorial.","D":"Não acomete músculos e articulações; somente pele."},"answer":"A","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-151059","number":"151059","sourceNumber":"151059","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Quanto à infecção pelo vírus Zika:","options":{"A":"Sua evolução é complexa e os sintomas prolongados até um ano após a infecção.","B":"A maioria das pessoas infectadas não desenvolve manifestações clínicas.","C":"Mais de 60% dos pacientes têm formas atípicas.","D":"Até agora não foram registrados casos da Síndrome de Guillain Barré como complicação."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-infectologia-inf-3-156293","number":"156293","sourceNumber":"156293","collectionBlock":"medcurso:medcurso-infectologia-inf-3","collectionLabel":"Medcurso · INF 3","documentBlock":"","area":"Infectologia","specialty":"Infectologia","topic":"INF 3","subtopic":"","stem":"Paciente em Dourados, MS, com quadro de febre há 2 dias (temperatura máxima de 39\ngraus) associada à intensa mialgia e artralgia. Associado refere cefaleia e surgimento de exantema\nmacular não pruriginoso. A paciente está na 10ª semana gestacional e questiona sobre a\npossibilidade de microcefalia no feto. Qual a conduta diagnóstica correta?","options":{"A":"Solicita sorologias Febre do Chikungunya, Zika vírus e Dengue IGm e IGg.","B":"Solicita antígeno NS1 para dengue, hemograma, transaminases e albumina sérica.","C":"Interna a paciente e realiza amniocentese para pesquisa de Zika vírus.","D":"Solicita US morfológico urgente.","E":"Solicita VDRL, HIV e hepatites."},"answer":"B","source":"Infectologia/INF 3/INF 3.txt","sourceLabel":"Medcurso · INF 3","images":[],"optionImages":{},"commentImages":[],"tags":["Infectologia","INF 3","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
